	private void Tick()
	{
		double totalSeconds = clock.Elapsed.TotalSeconds;
		if (outro != null && totalSeconds >= outroAt)
		{
			Action action = outro;
			outro = null;
			action();
		}
		if (riding)
		{
			FollowCursor();
		}
		else if (onPanel)
		{
			HoldPanel();
		}
		else if (falling)
		{
			Tumble(totalSeconds);
		}
		else if (dragging)
		{
			Swing(totalSeconds);
		}
		else if (seat != null)
		{
			HoldSeat(totalSeconds);
		}
		if (walking)
		{
			Walk(totalSeconds);
		}
		if (!riding && !dragging && !walking && !falling && outro == null && clip != arrive && clip != leave)
		{
			Face();
		}
		if (!Steady(totalSeconds))
		{
			RenderFrame();
		}
		if (!riding && !dragging && !walking && outro == null && !preferences.Motion && clip == idle && speech == null && talkState == TalkState.Off)
		{
			frames.Stop();
		}
		int num = FrameInterval(totalSeconds);
		if (frames.Interval != num)
		{
			frames.Interval = num;
		}
	}

	private int FrameInterval(double now)
	{
		int perchFps = preferences.PerchFps;
		if (perchFps == 30 || !SittingStill || (clip != perch && clip != perchDance) || (perchFps < 30 && (clip != perch || !Quiet(now))))
		{
			return 33;
		}
		return Math.Max(1, 64 / perchFps) * 1000 / 64 - 1;
	}

	private bool Steady(double now)
	{
		int perchFps = preferences.PerchFps;
		if (perchFps != 30 && clip == perch && SittingStill && Quiet(now) && anchor == drawnAt && facingLeft == drawnFacing)
		{
			return (long)((now - clipStart) * (double)perchFps) == drawnStep;
		}
		return false;
	}

	private bool Quiet(double now)
	{
		if (speech == null && talkState == TalkState.Off && !box.Visible && !typer.Visible)
		{
			return !notes.Exists((Note note) => now - note.Born < 1.5);
		}
		return false;
	}

	private void Face()
	{
		if (!lying)
		{
			Point point = Hip();
			int num = Screen.FromPoint(point).WorkingArea.Right - point.X;
			bool flag = (float)num < (float)preferences.Size * (facingLeft ? 0.9f : 0.6f);
			if (flag != facingLeft)
			{
				facingLeft = flag;
				anchor = new Point(anchor.X + point.X - Hip().X, anchor.Y);
				Location = anchor;
				Static(everywhere: false, null);
			}
		}
	}

