	}

	internal static bool HasArt(string name)
	{
		return Assembly.GetExecutingAssembly().GetManifestResourceInfo(name) != null;
	}

	internal static Bitmap LoadArt(string name)
	{
		using Stream stream = Assembly.GetExecutingAssembly().GetManifestResourceStream(name);
		if (stream == null)
		{
			return null;
		}
		using Bitmap bitmap = new Bitmap(stream);
		Bitmap bitmap2 = new Bitmap(bitmap.Width, bitmap.Height, PixelFormat.Format32bppPArgb);
		using (Graphics graphics = Graphics.FromImage(bitmap2))
		{
			graphics.CompositingMode = CompositingMode.SourceCopy;
			graphics.DrawImage(bitmap, new Rectangle(0, 0, bitmap2.Width, bitmap2.Height));
		}
		return bitmap2;
	}

	private void Play(Clip next)
	{
		clip = next;
		clipStart = clock.Elapsed.TotalSeconds;
		idleCycle = 0;
		perchMix = 0;
		drawnStep = -1L;
		blinkWith = null;
		danceLast = -1.0;
		nodGain = 0.0;
		veiled = false;
		arrivalDue = next == arrive || next == perchArrive;
	}

	private bool FollowBeat(double now)
	{
		bool flag = groove.Locked(out var bpm, out var beatAt);
		bool flag2 = danceLast < 0.0 || now - danceLast > 0.5;
		double num = (flag2 ? 0.0 : (now - danceLast));
		double num2 = nodGain;
		danceLast = now;
		if (flag)
		{
			danceBeat = 60.0 / bpm;
		}
		nodGain = (flag ? Math.Min(1.0, nodGain + num * 2.0) : Math.Max(0.0, nodGain - num * 3.0));
		if ((!flag && nodGain <= 0.0) || danceBeat <= 0.0)
		{
			return false;
		}
		dancePos += num / danceBeat;
		if (flag)
		{
			double num3 = (now - beatAt) / danceBeat - dancePos;
			num3 -= Math.Floor(num3 + 0.5);
			dancePos += ((flag2 || num2 <= 0.0) ? num3 : Math.Max(-0.02, Math.Min(0.02, num3)));
		}
		bool result = !flag2 && num2 > 0.0 && dancePos >= 1.0;
		dancePos -= Math.Floor(dancePos);
		return result;
	}

	private void Jam(double now, bool hit)
	{
		notes.RemoveAll((Note note) => now - note.Born > 1.5 || now < note.Born);
		bool num;
		if (!(nodGain > 0.5))
		{
			if (!(nodGain <= 0.0))
			{
				return;
			}
			num = now >= nextNote;
		}
		else
		{
			if (!hit)
			{
				return;
			}
			if (danceBeat >= 0.55)
			{
				goto IL_0091;
			}
			num = ++noteBeats % 2 == 0;
		}
		if (!num)
		{
			return;
		}
		goto IL_0091;
		IL_0091:
		if (notes.Count < 5)
		{
			nextNote = now + 1.3 + random.NextDouble() * 0.6;
			if (random.NextDouble() < 0.75)
			{
				noteSide = -noteSide;
			}
			notes.Add(new Note
			{
				Born = now,
				Side = noteSide,
				Shape = random.Next(3),
				Seed = random.NextDouble() * 100.0
			});
		}
	}

	private float NodDepth()
	{
		if (nodGain <= 0.0)
		{
			return 0f;
		}
		double num = ((dancePos < 0.45) ? (1.0 - dancePos / 0.45) : 0.0);
		double num2 = ((dancePos > 0.75) ? ((dancePos - 0.75) / 0.25) : 0.0);
		return (float)(nodGain * (num * num + num2 * num2));
	}

	private int Advance(double now)
	{
		bool flag = this.clip == laydown || this.clip == laydownGlitch || this.clip == laydownSleep || this.clip == laydownLeave;
		bool flag2 = this.clip == perch || this.clip == perchGlitch || this.clip == perchDance || this.clip == perchArrive || this.clip == perchLeave || flag;
		bool flag3 = riding || onPanel || seat != null;
		if (lying && (seat == null || riding || onPanel || walking || falling || hanging || dragging))
		{
			SitUp(glitched: false);
		}
		if (flag2)
		{
			if (lying)
			{
				WarmLie();
			}
			else
			{
				WarmPerch();
			}
		}
		if (flag3 && (!flag2 || (flag && !lying && this.clip != laydownLeave)) && !walking)
		{
			Play(lying ? laydown : perch);
		}
		if ((!flag3 && flag2) || (this.clip == dangle && !dragging && !falling && !hanging))
		{
			Play(idle);
		}
		int num = (int)((now - clipStart) * this.clip.Fps);
		perchMix = 0;
		if ((this.clip == perch || this.clip == perchDance || this.clip == laydown || this.clip == laydownSleep) && preferences.PerchFps != 30)
		{
			num = PerchIndex(now - clipStart, preferences.PerchFps, out perchMix);
		}
		if (this.clip == leave || this.clip == perchLeave || this.clip == laydownLeave)
		{
			return Math.Min(num, this.clip.Count - 1);
		}
		if ((this.clip == glitch && num >= glitch.Count) || (this.clip == wake && num >= wake.Count) || (this.clip == grin && num >= grin.Count * 2))
		{
			Play(idle);
			num = 0;
		}
		if (this.clip == arrive && num >= arrive.Count)
		{
			Play(idle);
			num = 0;
			if (dropAfter)
			{
				dropAfter = false;
				if (spawnFall)
				{
					Fall();
				}
				else if (!Drop())
				{
					SavePreferences();
				}
			}
		}
		if ((this.clip == perchGlitch && num >= perchGlitch.Count) || (this.clip == perchArrive && num >= perchArrive.Count))
		{
			Play(perch);
			num = 0;
		}
		if (this.clip == laydownGlitch && num >= laydownGlitch.Count)
		{
			Play(laydown);
			num = 0;
		}
		if (dropAfter && this.clip != arrive && this.clip != glitch)
		{
			dropAfter = false;
			if (!riding && !dragging && !hanging && !hidden && seat == null && !Drop())
			{
				SavePreferences();
			}
		}
		if (this.clip == dance || this.clip == perchDance)
		{
			Jam(now, FollowBeat(now));
			return num % this.clip.Count;
		}
		if (this.clip != idle && this.clip != perch && this.clip != laydown)
		{
			return num % this.clip.Count;
		}
		if (!preferences.Motion)
		{
			perchMix = 0;
			return 0;
		}
		int num2 = num / this.clip.Count;
		if (num2 != idleCycle)
		{
			idleCycle = num2;
			double num3 = random.NextDouble();
			ref Clip reference = ref blinkWith;
			Clip clip;
			if (num3 < 0.1)
			{
				clip = Blinks(glitchy: true);
			}
			else
			{
				clip = ((num3 < 0.55) ? Blinks(glitchy: false) : null);
			}
			reference = clip;
			if (now >= nextGlitch && speech == null && talkState == TalkState.Off)
			{
				nextGlitch = now + 30.0 + random.NextDouble() * 30.0;
				Companion companion = this;
				Clip next;
				if (this.clip == perch)
				{
					next = perchGlitch;
				}
				else
				{
					next = ((this.clip == laydown) ? laydownGlitch : glitch);
				}
				companion.Play(next);
				return 0;
			}
		}
		return num % this.clip.Count;
	}

	private Clip Blinks(bool glitchy)
	{
		if (this.clip == perch)
		{
			if (!glitchy)
			{
				return perchBlink;
			}
			return perchBlinkGlitch;
		}
		if (this.clip != laydown)
		{
			if (!glitchy)
			{
				return blink;
			}
			return blinkGlitch;
		}
		Clip clip = (glitchy ? laydownBlinkGlitch : laydownBlink);
		if (!clip.Ready(facingLeft))
		{
			return null;
		}
		return clip;
	}

	internal static int PerchIndex(double t, int fps, out int mix)
	{
		long num = (long)(t * (double)fps);
		long num2 = num * 30;
		mix = (int)((fps > 30) ? (num2 % fps * 256 / fps) : 0);
		return (int)(num2 / fps);
	}

	private void StayOnTop()
	{
		if (!preferences.OnTop || hidden || !IsHandleCreated || menu.Visible || (playerMenu != null && playerMenu.Visible))
		{
			return;
		}
		IntPtr foregroundWindow = Native.GetForegroundWindow();
		if (foregroundWindow == lastForeground && ++topTicks < 8)
		{
			return;
		}
		lastForeground = foregroundWindow;
		topTicks = 0;
		if (player.Visible)
		{
			Native.SetWindowPos(player.Handle, new IntPtr(-1), 0, 0, 0, 0, 19);
		}
		Native.SetWindowPos(Handle, new IntPtr(-1), 0, 0, 0, 0, 19);
		Form[] array = new Form[3] { pill, box, typer };
		foreach (Form form in array)
		{
			if (form.Visible)
			{
				Native.SetWindowPos(form.Handle, new IntPtr(-1), 0, 0, 0, 0, 19);
			}
		}
	}

	internal static bool UpdateDue(long checkedAt, long now)
	{
		if (checkedAt > 0 && now >= checkedAt)
		{
			return now - checkedAt >= 108000000000L;
		}
		return true;
	}

	internal static bool UpdateDue(long checkedAt, long now, double elapsed, bool started)
	{
		if (elapsed >= 20.0)
		{
			if (started)
			{
				return UpdateDue(checkedAt, now);
			}
			return true;
		}
		return false;
	}

	private void CheckForUpdates(bool asked)
	{
		if (updating || installing)
		{
			return;
		}
		// the mod: an official update would install over the modded build
		if (preferences.BlockUpdates && !testing)
		{
			if (asked)
			{
				mainframe.UpdateNote("Updates are blocked by the mod (MOD > Block official updates).", problem: false);
			}
			return;
		}
		updating = true;
		updateStarted = true;
		preferences.UpdateCheckedAt = DateTime.UtcNow.Ticks;
		SavePreferences();
		checkItem.Enabled = false;
		updateItem.Enabled = false;
		if (asked)
		{
			mainframe.UpdateNote("Checking for updates...", problem: false);
		}
		ThreadPool.QueueUserWorkItem((object param0) =>
		{
			Release found = null;
			UpdateFile ready = null;
			string problem = null;
			try
			{
				found = updater.Latest();
				if (UsableRelease(found) && IsNewer(found.Tag, Assembly.GetExecutingAssembly().GetName().Version))
				{
					Post(() =>
					{
						mainframe.UpdateNote("Downloading Capri " + found.Tag.TrimStart('v', 'V') + "...", problem: false);
					});
					ready = updater.Download(found);
				}
			}
			catch (Exception ex)
			{
				problem = ((ex is BrainException) ? ex.Message : ((found == null) ? "Couldn't check for updates. I'll try again in 3 hours." : "Couldn't download the update. I'll try again in 3 hours."));
			}
			Post(() =>
			{
				ShowUpdate(found, ready, problem, asked);
			});
		});
	}

	internal static Release FetchLatestRelease()
	{
		ServicePointManager.SecurityProtocol |= SecurityProtocolType.Tls12;
		HttpWebRequest httpWebRequest = (HttpWebRequest)WebRequest.Create("https://api.github.com/repos/lachydotmcg/capri-desktop/releases/latest");
		httpWebRequest.UserAgent = "Capri-Desktop";
		httpWebRequest.Accept = "application/vnd.github+json";
		httpWebRequest.Timeout = 10000;
		httpWebRequest.ReadWriteTimeout = 10000;
		using WebResponse webResponse = httpWebRequest.GetResponse();
		using Stream body = webResponse.GetResponseStream();
		return ParseRelease(body);
	}

	internal static Release ParseRelease(Stream body)
	{
		return (Release)new DataContractJsonSerializer(typeof(Release)).ReadObject(body);
	}

	internal static bool IsNewer(string tag, Version current)
	{
		if (ReleaseVersion(tag, out var version))
		{
			return version > new Version(current.Major, current.Minor, Math.Max(0, current.Build), Math.Max(0, current.Revision));
		}
		return false;
	}

	internal static bool ReleaseVersion(string tag, out Version version)
	{
		version = null;
		if (tag == null || !Regex.IsMatch(tag, "^[vV]?\\d+\\.\\d+(\\.\\d+){0,2}$") || !Version.TryParse(tag.TrimStart('v', 'V'), out version))
		{
			return false;
		}
		version = new Version(version.Major, version.Minor, Math.Max(0, version.Build), Math.Max(0, version.Revision));
		return true;
	}

	private static bool UsableRelease(Release found)
	{
		Version version;
		if (found != null && !found.Draft && !found.Prerelease)
		{
			return ReleaseVersion(found.Tag, out version);
		}
		return false;
	}

	private void ShowUpdate(Release found, UpdateFile ready, string problem, bool asked)
	{
		updating = false;
		checkItem.Enabled = true;
		updateItem.Enabled = updateFile != null;
		Version version = Assembly.GetExecutingAssembly().GetName().Version;
		if (problem != null)
		{
			ForgetUpdate();
			mainframe.UpdateNote(problem, problem: true);
		}
		else if (ready != null)
		{
			bool flag = updateFile == null || updateFile.Path != ready.Path;
			updateFile = ready;
			updateItem.Enabled = true;
			updateItem.Text = "Restart to update to Capri " + ready.Version;
			if (!menu.Items.Contains(updateItem))
			{
				menu.Items.Insert(menu.Items.Count - 2, updateItem);
			}
			mainframe.UpdateNote(updateItem.Text + ". Use her tray menu.", problem: false);
			if (flag || asked)
			{
				balloonPage = null;
				balloonUpdate = true;
				balloonMainframe = false;
				tray.BalloonTipTitle = "Capri update ready";
				tray.BalloonTipText = updateItem.Text;
				tray.BalloonTipIcon = ToolTipIcon.Info;
				if (!testing)
				{
					tray.ShowBalloonTip(8000);
				}
			}
		}
		else
		{
			ForgetUpdate();
			if (asked || !UsableRelease(found))
			{
				mainframe.UpdateNote(UsableRelease(found) ? ("You're on the latest version (" + version.ToString(3) + ").") : "Couldn't check for updates. I'll try again in 3 hours.", !UsableRelease(found));
			}
		}
	}

	private void BalloonClicked()
	{
		if (balloonUpdate)
		{
			InstallUpdate();
		}
		else if (balloonPage != null)
		{
			OpenPage(balloonPage);
		}
		else if (balloonMainframe)
		{
			mainframe.Restore();
		}
	}

	private void ForgetUpdate()
	{
		updateFile = null;
		updateItem.Enabled = false;
		menu.Items.Remove(updateItem);
		balloonUpdate = false;
	}

	private void InstallUpdate()
	{
		if (updating || installing || updateFile == null)
		{
			return;
		}
		installing = true;
		updateItem.Enabled = false;
		checkItem.Enabled = false;
		UpdateFile ready = updateFile;
		int parent;
		long started;
		using (Process process = Process.GetCurrentProcess())
		{
			parent = process.Id;
			started = process.StartTime.ToUniversalTime().Ticks;
		}
		mainframe.UpdateNote("Checking the update before restarting...", problem: false);
		ThreadPool.QueueUserWorkItem((object param0) =>
		{
			string problem = null;
			bool invalid = false;
			try
			{
				updater.Install(ready, parent, started);
			}
			catch (Exception ex)
			{
				invalid = ex is BrainException || !File.Exists(ready.Path);
				problem = ((ex is BrainException) ? ex.Message : UpdateProblem(ex));
				Brain.Log("update", -1L, ex.GetType().Name + ": " + ex.Message);
			}
			Post(() =>
			{
				installing = false;
				checkItem.Enabled = true;
				updateItem.Enabled = true;
				if (problem != null)
				{
					if (invalid)
					{
						ForgetUpdate();
					}
					mainframe.UpdateNote(problem, problem: true);
				}
				else
				{
					updateExit();
				}
			});
		});
	}

	internal static string UpdateProblem(Exception error)
	{
		switch ((error is Win32Exception ex) ? ex.NativeErrorCode : 0)
		{
		case 1223:
			return "The update needs a Yes in the Windows prompt. Try again.";
		case 225:
		case 226:
			return "Your antivirus blocked the update. Capri is still running.";
		default:
			return "Couldn't start the update (" + Voice.Short(error.Message).TrimEnd('.') + "). Capri is still running.";
		}
	}

	private static void OpenPage(string page)
	{
		if (!(page != "https://ollama.com/download") || !(page != "https://build.nvidia.com/settings/api-keys") || !(page != "https://lachydotmcg.github.io/capri-desktop/setup/#voice") || !(page != "https://discord.gg/F4fDHfGtFk") || !(page != "https://lachydotmcg.github.io/capri-desktop/help/"))
		{
			Browse(page);
		}
	}

	private void CheckIdle(long quiet)
	{
		if (hideAsked && !hidden && !dragging && !pressed && speech == null && talkState != TalkState.Thinking && talkState != TalkState.Talking && clock.Elapsed.TotalSeconds >= voiceUntil && !speaker.Busy)
		{
			hideAsked = false;
			SetHidden(value: true);
			return;
		}
		if (napping && !Asleep)
		{
			napping = false;
		}
		if (napAsked && ((clip == idle && seat == null && !onPanel) || (clip == laydown && lying)) && !dragging && !pressed && !riding && !walking && !falling && !hanging && speech == null && talkState != TalkState.Thinking && talkState != TalkState.Talking && clock.Elapsed.TotalSeconds >= voiceUntil && !speaker.Busy)
		{
			napAsked = false;
			napping = true;
			StopChat();
			Play(lying ? laydownSleep : sleep);
			frames.Start();
			return;
		}
		if (meetAt >= 0.0 && clock.Elapsed.TotalSeconds >= meetAt && !hidden && !dragging && !pressed && !chatting && !typer.Visible && !Asleep && !napAsked && !napping && speech == null && talkState == TalkState.Off && clock.Elapsed.TotalSeconds >= voiceUntil && !speaker.Busy)
		{
			meetAt = -1.0;
			GetToKnow();
			return;
		}
		if (clip == sleep)
		{
			if (quiet < 1000 && !napping)
			{
				Play(wake);
			}
			return;
		}
		if (clip == laydownSleep)
		{
			if (quiet < 1000 && !napping)
			{
				Play(laydown);
			}
			return;
		}
		bool flag = SleepDue(quiet) && preferences.Motion && !riding && !dragging && !hidden && !chatting && speech == null && talkState == TalkState.Off && !typer.Visible;
		if (flag && clip == idle)
		{
			Play(sleep);
		}
		else if (flag && clip == laydown && lying)
		{
			Play(laydownSleep);
		}
		else if (flag && clip == perch && SittingStill)
		{
			LieDown();
		}
	}

	internal string Nap(bool sleeping)
	{
		if (!sleeping)
		{
			bool flag = napAsked || napping || Asleep;
			napAsked = false;
			napping = false;
			if (clip == sleep)
			{
				Play(wake);
				frames.Start();
			}
			else if (clip == laydownSleep)
			{
				Play(laydown);
				frames.Start();
			}
			if (!flag)
			{
				return "Already awake.";
			}
			return "Woke up.";
		}
		if (hidden)
		{
			SetHidden(value: false);
		}
		if (riding)
		{
			StopRide();
		}
		EndWalk();
		danceAsked = false;
		if (clip == perchDance)
		{
			Play(perch);
		}
		if (hanging || (seat != null && !lying && !LieDown()))
		{
			StandUp();
		}
		if (clip == dance || clip == perchDance)
		{
			Play(idle);
		}
		napAsked = true;
		return "Going to sleep. A click on me wakes me up.";
	}

	private string NapTool(bool sleeping)
	{
		if (!InvokeRequired)
		{
			return Nap(sleeping);
		}
		return (string)Invoke(new Func<bool, string>(Nap), sleeping);
	}

	internal string MoveSelf(string action, string screen)
	{
		lieBy = -1.0;
		if (action == "move_mainframe")
		{
			return MoveMainframe(screen);
		}
		if (action == "hide")
		{
			if (hidden)
			{
				return "Already hidden.";
			}
			hideAsked = true;
			return "Hiding. " + (hideKey ? (HideKeyName + " or a double-click") : "A double-click") + " on my tray icon brings me back.";
		}
		hideAsked = false;
		if (action == "show")
		{
			if (!hidden)
			{
				return "I'm right here.";
			}
			ShowHidden(value: false);
			DropSoon();
			return "Back.";
		}
		napAsked = false;
		napping = false;
		if (action == "come_here")
		{
			Teleport(MouseAt());
			return "Teleportando pro seu mouse.";
		}
		if (action == "other_screen")
		{
			Screen[] allScreens = Screen.AllScreens;
			Screen screen2 = Screen.FromPoint(Hip());
			int num = PickScreen(allScreens, screen2, screen);
			if (num < 0)
			{
				if (allScreens.Length >= 2)
				{
					return "There's no screen like that to go to.";
				}
				return "There's no other screen to go to.";
			}
			if (allScreens[num].DeviceName == screen2.DeviceName)
			{
				return "I'm already on " + ScreenName(allScreens, num) + ".";
			}
			Teleport(Across(Hip(), screen2.WorkingArea, allScreens[num].WorkingArea));
			return "Moving to " + ScreenName(allScreens, num) + ".";
		}
		if (hidden)
		{
			ShowHidden(value: false);
		}
		switch (action)
		{
		case "sit_on":
			return SitOn(screen, lie: false);
		case "lie_down":
			if (!string.IsNullOrWhiteSpace(screen))
			{
				return SitOn(screen, lie: true);
			}
			return LieHere();
		case "walk_around":
			return WalkAround();
		case "wander":
			if (Spots().Count == 0)
			{
				return "There's nowhere else to go right now.";
			}
			StopRide();
			LeavePanel(home: false);
			hanging = false;
			danceAsked = false;
			Wander();
			return "Off somewhere else.";
		case "sit":
			if (!lying)
			{
				break;
			}
			goto case "sit_up";
		case "sit_up":
			if (!lying)
			{
				if (seat == null || seat.Free)
				{
					return "I'm not lying down.";
				}
				return "Already sitting up.";
			}
			SitUp();
			return "Sitting up.";
		}
		switch (action)
		{
		case "sit":
			if (seat != null && seat.Free)
			{
				return "Already sitting.";
			}
			StopRide();
			LeavePanel(home: false);
			SitHere();
			return "Sitting right here.";
		case "stand_up":
			if (riding)
			{
				StopRide();
				return "Desci do seu cursor.";
			}
			if (hanging)
			{
				LetGo();
				return "Let go.";
			}
			if (seat == null)
			{
				return "Already standing.";
			}
			StandUp();
			return "Standing up.";
		case "hang":
			if (hanging)
			{
				return "Already hanging.";
			}
			StopRide();
			LeavePanel(home: false);
			HangHere();
			return "Hanging right here.";
		case "ride_cursor":
			if (riding)
			{
				return "Já estou no seu cursor.";
			}
			StartRide(quiet: true);
			if (!riding)
			{
				return "Não consegui subir no seu cursor agora.";
			}
			return "Estou no seu cursor. Se me pedirem pra descer, eu desço.";
		case "hop_off":
			if (!riding)
			{
				return "Não estou no seu cursor.";
			}
			StopRide();
			return "Desci do seu cursor.";
		default:
			return "Couldn't move like that.";
		}
	}

	private string MoveTool(string action, string screen)
	{
		if (!InvokeRequired)
		{
			return MoveSelf(action, screen);
		}
		return (string)Invoke(new Func<string, string, string>(MoveSelf), action, screen);
	}

	private string SitOn(string wanted, bool lie)
	{
		string text = Regex.Replace((wanted ?? "").Trim(), "^(?:the|my|your|ur|our|that|this) | (?:window|app|application|game|tab)$", "", RegexOptions.IgnoreCase).Trim();
		if (text.Length == 0)
		{
			return "Which window, choom?";
		}
		List<Ledge> list = Around();
		string text2 = null;
		List<Ledge> list2;
		string text3;
		if (Hands.TaskbarWords.IsMatch(text))
		{
			Rectangle area = Screen.FromPoint(Hip()).WorkingArea;
			list2 = list.FindAll((Ledge ledge) => ledge.Floor && ledge.Y == area.Bottom && ledge.Left == area.Left);
			text3 = "the taskbar";
		}
		else if (Hands.MainframeWords.IsMatch(text))
		{
			if (!mainframe.IsHandleCreated || !mainframe.Visible || mainframe.WindowState != FormWindowState.Normal)
			{
				return "My Mainframe isn't open. Open it and I'll sit on it.";
			}
			IntPtr own = mainframe.Handle;
			list2 = list.FindAll((Ledge ledge) => ledge.Window == own);
			text3 = "my Mainframe";
			text2 = "There's no room for me on top of my Mainframe: something's covering it, or it's too close to the top of the screen.";
		}
		else
		{
			string text4 = char.ToUpperInvariant(text[0]) + text.Substring(1);
			List<OpenWindow> list3 = Hands.WindowsNamed(text);
			if (list3.Count == 0)
			{
				return Hands.Unlisted() ?? ("I can't see " + text4 + " open.");
			}
			text3 = "your " + text4 + " window";
			list2 = new List<Ledge>();
			foreach (OpenWindow item in list3)
			{
				IntPtr handle = item.Handle;
				if (!Ledges.Showing(handle, out var bounds))
				{
					text2 = text2 ?? (text4 + " is minimized. Open it and I'll sit on it.");
					continue;
				}
				if (!Ledges.Seatable(handle, bounds))
				{
					text2 = text2 ?? ((bounds.Width < 120 || bounds.Height < 60) ? (text4 + " is too small to sit on.") : (text4 + " fills the screen, so its top edge is off the top. Make it smaller and I'll sit on it."));
					continue;
				}
				list2 = list.FindAll((Ledge ledge) => ledge.Window == handle);
				if (list2.Count <= 0)
				{
					text2 = text2 ?? ("Other windows are covering the top of " + text3 + ".");
					continue;
				}
				break;
			}
		}
		int room = Headroom();
		list2.RemoveAll((Ledge ledge) => !ledge.Icon.IsEmpty || ledge.Right - ledge.Left < 24 || ledge.Y - room < Screen.FromPoint(new Point(ledge.Left, ledge.Y)).Bounds.Top);
		if (list2.Count == 0)
		{
			return text2 ?? ("There's no room for me on top of " + text3 + ".");
		}
		Ledge spot = list2[0];
		foreach (Ledge item2 in list2)
		{
			if (item2.Right - item2.Left > spot.Right - spot.Left)
			{
				spot = item2;
			}
		}
		if (seat != null && !seat.Free && seat.Icon.IsEmpty && !riding && !walking && !falling)
		{
			bool num;
			if (!spot.Floor)
			{
				num = seat.Window == spot.Window;
			}
			else
			{
				if (!seat.Floor || seat.Y != spot.Y)
				{
					goto IL_040b;
				}
				num = seat.Left == spot.Left;
			}
			if (num)
			{
				if (!lie)
				{
					return "Already sitting on " + text3 + ".";
				}
				return LieHere(text3);
			}
		}
		goto IL_040b;
		IL_040b:
		int num2 = Math.Min(preferences.Size / 4, (spot.Right - spot.Left) / 3);
		int x = spot.Left + num2 + random.Next(Math.Max(1, spot.Right - spot.Left - 2 * num2));
		StopRide();
		LeavePanel(home: false);
		hanging = false;
		danceAsked = false;
		GlitchOut(() =>
		{
			Hop(spot, x);
		}, everywhere: false);
		if (lie)
		{
			lieBy = clock.Elapsed.TotalSeconds + 10.0;
		}
		return (lie ? "Lying down on " : "Sitting on ") + text3 + ".";
	}

	private string LieHere(string shown = null)
	{
		string result = ((shown == null) ? "Lying down." : ("Lying down on " + shown + "."));
		if (lying)
		{
			return "Already lying down.";
		}
		StopRide();
		LeavePanel(home: false);
		EndWalk();
		danceAsked = false;
		if (clip == perchDance)
		{
			Play(perch);
		}
		if (seat != null && !seat.Free && seat.Icon.IsEmpty && !falling)
		{
			if (clip != perch)
			{
				lieBy = clock.Elapsed.TotalSeconds + 10.0;
				return result;
			}
			if (!LieDown())
			{
				return "There's no room to lie down here. Try \"lie down on the taskbar\".";
			}
			return result;
		}
		if (seat != null)
		{
			StandUp();
		}
		hanging = false;
		Ledge ledge = Ledges.Below(Around(), Hip(), 0, int.MaxValue, 0, Headroom());
		if (ledge == null)
		{
			return "There's nothing under me to lie on.";
		}
		lieBy = clock.Elapsed.TotalSeconds + 10.0;
		falling = true;
		fallTo = ledge;
		fallSpeed = 0.0;
		fallStep = clock.Elapsed.TotalSeconds;
		frames.Start();
		return result;
	}

	private string WalkAround()
	{
		if (walking)
		{
			return "Already walking.";
		}
		StopRide();
		LeavePanel(home: false);
		danceAsked = false;
		SitUp(glitched: false);
		if (hanging)
		{
			hanging = false;
			Play(idle);
		}
		if (clip == perchDance)
		{
			Play(perch);
		}
		else if (clip == dance)
		{
			Play(idle);
		}
		if (Stroll())
		{
			return "Going for a little walk.";
		}
		if (Spots().Count == 0)
		{
			return "There's no room to walk around here.";
		}
		Wander();
		return "Wandering off somewhere.";
	}

	private void Teleport(Point to)
	{
		Rectangle area = Screen.FromPoint(to).WorkingArea;
		Action action = () =>
		{
			StopRide();
			LeavePanel(home: false);
			seat = null;
			hanging = false;
			falling = false;
			walking = false;
			anchor = Within(Seated(to.X, to.Y), area, Body);
			ShowHidden(value: false);
			DropSoon();
		};
		if (hidden)
		{
			action();
		}
		else
		{
			GlitchOut(action, everywhere: false);
		}
	}

	private static int PickScreen(Screen[] screens, Screen from, string which)
	{
		int[] array = new int[screens.Length];
		int[] array2 = new int[screens.Length];
		int[] array3 = new int[screens.Length];
		int primary = 0;
		int current = -1;
		int pointed = -1;
		Screen screen = Screen.FromPoint(MouseAt());
		for (int i = 0; i < screens.Length; i++)
		{
			Rectangle bounds = screens[i].Bounds;
			array[i] = bounds.Left + bounds.Width / 2;
			array2[i] = bounds.Top + bounds.Height / 2;
			Match match = Regex.Match(screens[i].DeviceName ?? "", "(\\d+)$");
			array3[i] = ((match.Success && match.Length < 3) ? int.Parse(match.Value) : 0);
			if (screens[i].Primary)
			{
				primary = i;
			}
			if (screens[i].DeviceName == from.DeviceName)
			{
				current = i;
			}
			if (screens[i].DeviceName == screen.DeviceName)
			{
				pointed = i;
			}
		}
		return Hands.PickScreen(array, array2, array3, primary, current, pointed, which);
	}

	private static string ScreenName(Screen[] screens, int index)
	{
		if (screens[index].Primary)
		{
			return "your main screen";
		}
		Match match = Regex.Match(screens[index].DeviceName ?? "", "(\\d+)$");
		if (screens.Length != 2 && match.Success)
		{
			return "screen " + match.Value;
		}
		return "your other screen";
	}

	internal static Point Across(Point at, Rectangle from, Rectangle to)
	{
		double num = ((from.Width > 0) ? Math.Max(0.0, Math.Min(1.0, (double)(at.X - from.Left) / (double)from.Width)) : 0.5);
		double num2 = ((from.Height > 0) ? Math.Max(0.0, Math.Min(1.0, (double)(at.Y - from.Top) / (double)from.Height)) : 0.5);
		return new Point(to.Left + (int)Math.Round(num * (double)to.Width), to.Top + (int)Math.Round(num2 * (double)to.Height));
	}

	internal static Rectangle Shifted(Rectangle window, Rectangle from, Rectangle to)
	{
		double num = ((from.Width > window.Width) ? Math.Max(0.0, Math.Min(1.0, (double)(window.Left - from.Left) / (double)(from.Width - window.Width))) : 0.5);
		double num2 = ((from.Height > window.Height) ? Math.Max(0.0, Math.Min(1.0, (double)(window.Top - from.Top) / (double)(from.Height - window.Height))) : 0.5);
		return Placed(new Rectangle(to.Left + (int)Math.Round(num * (double)(to.Width - window.Width)), to.Top + (int)Math.Round(num2 * (double)(to.Height - window.Height)), window.Width, window.Height), to);
	}

	internal static Rectangle Placed(Rectangle window, Rectangle area)
	{
		return new Rectangle(Math.Max(area.Left, Math.Min(window.Left, area.Right - window.Width)), Math.Max(area.Top, Math.Min(window.Top, area.Bottom - window.Height)), window.Width, window.Height);
	}

	private string MoveMainframe(string which)
	{
		Screen[] allScreens = Screen.AllScreens;
		bool flag = mainframe.WindowState == FormWindowState.Normal;
		Rectangle rect = (flag ? mainframe.Bounds : mainframe.RestoreBounds);
		Screen screen = Screen.FromRectangle(rect);
		bool flag2 = Regex.IsMatch(which ?? "", "^\\s*(here|this|mouse|cursor|pointer)\\s*$", RegexOptions.IgnoreCase);
		int num = PickScreen(allScreens, screen, which);
		if (num < 0)
		{
			if (allScreens.Length >= 2)
			{
				return "There's no screen like that for the Mainframe.";
			}
			return "There's no other screen for the Mainframe.";
		}
		Rectangle bounds;
		if (flag2)
		{
			Point point = MouseAt();
			bounds = Placed(new Rectangle(point.X - rect.Width / 2, point.Y - rect.Height / 2, rect.Width, rect.Height), allScreens[num].WorkingArea);
		}
		else
		{
			if (allScreens[num].DeviceName == screen.DeviceName)
			{
				if (!testing)
				{
					mainframe.Restore();
				}
				return "The Mainframe's already on " + ScreenName(allScreens, num) + ".";
			}
			bounds = Shifted(rect, screen.WorkingArea, allScreens[num].WorkingArea);
		}
		bool flag3 = mainframe.WindowState == FormWindowState.Maximized;
		if (!flag)
		{
			mainframe.WindowState = FormWindowState.Normal;
		}
		mainframe.Bounds = bounds;
		if (flag3)
		{
			mainframe.WindowState = FormWindowState.Maximized;
		}
		if (!testing)
		{
			mainframe.Restore();
		}
		if (!flag2)
		{
			return "Moved the Mainframe to " + ScreenName(allScreens, num) + ".";
		}
		return "Trouxe o Mainframe pro seu mouse.";
	}

	internal string Animate(string name)
	{
		if (name == "stop_dancing")
		{
			bool flag = danceAsked || clip == dance || clip == perchDance;
			danceAsked = false;
			danceHeld = musicOn;
			if (clip == dance || clip == perchDance)
			{
				Play((seat != null || onPanel) ? perch : idle);
				UpdateAnimation();
			}
			if (!flag)
			{
				return "I wasn't dancing.";
			}
			return "Stopped dancing.";
		}
		napAsked = false;
		napping = false;
		if (hidden)
		{
			ShowHidden(value: false);
		}
		if (name == "dance")
		{
			StopRide();
			if (hanging)
			{
				LetGo();
			}
			danceAsked = true;
			danceHeld = false;
			frames.Start();
			return "Dançando. Me manda parar quando quiser.";
		}
		bool flag2 = seat != null || onPanel || riding;
		switch (name)
		{
		case "idle":
			danceAsked = false;
			danceHeld = musicOn;
			if (hanging)
			{
				LetGo();
			}
			Play(flag2 ? perch : idle);
			break;
		case "glitch":
			if (hanging)
			{
				LetGo();
			}
			else
			{
				Play(flag2 ? perchGlitch : glitch);
			}
			break;
		case "grin":
			if (riding)
			{
				StopRide();
				break;
			}
			LeavePanel(home: false);
			if (hanging)
			{
				LetGo();
			}
			else if (seat != null)
			{
				StandUp();
			}
			Play(grin);
			break;
		case "blink":
			if (hanging)
			{
				LetGo();
			}
			Play(flag2 ? perch : idle);
			blinkWith = (flag2 ? perchBlink : blink);
			break;
		default:
			return "I don't have an animation called " + name + ".";
		}
		frames.Start();
		RenderFrame();
		return name switch
		{
			"grin" => "Grinning.", 
			"glitch" => "Glitched.", 
			"idle" => "De volta ao meu modo parado.", 
			_ => "Blinked.", 
		};
	}

	private string AnimateTool(string name)
	{
		if (!InvokeRequired)
		{
			return Animate(name);
		}
		return (string)Invoke(new Func<string, string>(Animate), name);
	}

	private static Size CanvasSize(int size)
	{
		return new Size(size + 96, size + 96);
	}

	private void AddSize(ToolStripMenuItem parent, string label, int size)
	{
		ToolStripMenuItem toolStripMenuItem = new ToolStripMenuItem(label, null, (object param0, EventArgs param1) =>
		{
			SetCharacterSize(size);
		});
		toolStripMenuItem.Tag = size;
		toolStripMenuItem.Checked = preferences.Size == size;
		parent.DropDownItems.Add(toolStripMenuItem);
	}

	internal void SetCharacterSize(int size)
	{
		size = Math.Max(140, Math.Min(560, size));
		EndWalk();
		Point point = new Point(anchor.X + Width / 2, anchor.Y + Height / 2);
		int num = Hip().X;
		preferences.Size = size;
		Size = CanvasSize(size);
		anchor = ((seat != null) ? Seated(num, seat.Y) : KeepOnScreen(new Point(point.X - Width / 2, point.Y - Height / 2)));
		Location = anchor;
		foreach (ToolStripItem item in menu.Items)
		{
			if (!(item is ToolStripMenuItem toolStripMenuItem) || toolStripMenuItem.Text != "Size")
			{
				continue;
			}
			foreach (ToolStripMenuItem dropDownItem in toolStripMenuItem.DropDownItems)
			{
				dropDownItem.Checked = (int)dropDownItem.Tag == size;
			}
		}
		RenderFrame();
		SavePreferences();
		mainframe.Sync();
	}

	private Point KeepOnScreen(Point point)
	{
		return Within(point, Screen.FromPoint(new Point(point.X + Width / 2, point.Y + Height / 2)).WorkingArea, Body);
	}

	private Point Within(Point point, Rectangle area, RectangleF body)
	{
		int size = preferences.Size;
		int val = area.Left - 48 - (int)((float)size * body.Left);
		int val2 = area.Right - 48 - (int)Math.Ceiling((float)size * body.Right);
		int val3 = area.Top - 48 - (int)((float)size * body.Top);
		int val4 = area.Bottom - 48 - (int)Math.Ceiling((float)size * body.Bottom);
		return new Point(Math.Max(val, Math.Min(point.X, val2)), Math.Max(val3, Math.Min(point.Y, val4)));
	}

	private Rectangle BodyOnScreen(Point point, RectangleF body)
	{
		int size = preferences.Size;
		return Rectangle.FromLTRB(point.X + 48 + (int)((float)size * body.Left), point.Y + 48 + (int)((float)size * body.Top), point.X + 48 + (int)Math.Ceiling((float)size * body.Right), point.Y + 48 + (int)Math.Ceiling((float)size * body.Bottom));
	}

