	private void MovePointer(Point position)
	{
		if (!pressed)
		{
			return;
		}
		int num = position.X - pointerStart.X;
		int num2 = position.Y - pointerStart.Y;
		if (!dragging && num * num + num2 * num2 < 25)
		{
			return;
		}
		if (onPanel)
		{
			if (!dragging)
			{
				panelGrabbed = taskPanel.Location;
			}
			dragging = true;
			pendingClick = false;
			clickDelay.Stop();
			taskPanel.MoveTo(new Point(panelGrabbed.X + num, panelGrabbed.Y + num2));
			return;
		}
		if (!dragging && lying)
		{
			int num3 = anchor.X;
			SitUp(glitched: false);
			anchorStart.X += anchor.X - num3;
		}
		if (!dragging)
		{
			seat = null;
			falling = false;
			hanging = false;
			walking = false;
			dropAfter = false;
			leanAngle = 0.0;
			swingSpeed = 0.0;
			dragVX = 0.0;
			dragVY = 0.0;
			flyVX = 0.0;
			dragLast = anchor;
			dragStep = clock.Elapsed.TotalSeconds;
			Zap(0.25, ground: false, Cue.Spark);
			Play(dangle);
			frames.Start();
			RefreshIcons();
		}
		dragging = true;
		pendingClick = false;
		clickDelay.Stop();
		anchor = KeepOnScreen(new Point(anchorStart.X + num, anchorStart.Y + num2));
		Location = anchor;
	}

