	private void Petted()
	{
		EndWalk();
		petPurr = random.NextDouble() < PurrChances[PurrChance];
		preferences.Pets++;
		if (petPurr)
		{
			preferences.Purrs++;
		}
		SavePreferences();
		ShowPetHearts();
		Sfx.Play(petPurr ? Cue.PetPurr : Cue.PetHappy);
		if (lying)
		{
			Play(laydown);
			blinkWith = Blinks(glitchy: false);
		}
		else if (seat != null)
		{
			Play(perch);
			blinkWith = perchBlink;
		}
		else
		{
			Play(grin);
		}
		frames.Start();
		RenderFrame();
		int ticket = ++petTicket;
		ThreadPool.QueueUserWorkItem((object param0) =>
		{
			Thread.Sleep(1300);
			Post(() =>
			{
				PetLine(ticket);
			});
		});
	}

