	private void Greet(int ticket, DateTime now)
	{
		greetTried = true;
		string[] array = Brain.Holiday(now);
		string text = ((array != null) ? array[random.Next(array.Length)] : Brain.Greeting(now.Hour));
		if (text != null && ticket == asking && !hidden && !chatting && speech == null && talkState == TalkState.Off && !typer.Visible)
		{
			heard = "startup";
			box.Prompt = "> sys: ";
			if (array != null)
			{
				holidaySaid = now.Date;
			}
			byte[] array2 = ((array != null) ? null : Hello(Brain.GreetingClip(now.Hour)));
			if (array2 == null)
			{
				Answer(++asking, text, TalkState.Talking);
			}
			else
			{
				Begin(++asking, text, TalkState.Talking, array2);
			}
		}
	}

	private void CheckHoliday(DateTime now, long quiet)
	{
		string[] array = Brain.Holiday(now);
		if (array != null && !(now.Date == holidaySaid) && greetTried && quiet <= 60000 && !Hushed && !hidden && !quitting && !dragging && !pressed && !chatting && !typer.Visible && !menu.Visible && speech == null && talkState == TalkState.Off && outro == null && !onPanel && !(popOut >= 0.0) && working == null && !FullScreen())
		{
			holidaySaid = now.Date;
			Remark("holiday", array[random.Next(array.Length)]);
		}
	}

	internal static byte[] Hello(string name)
	{
		using Stream stream = Assembly.GetExecutingAssembly().GetManifestResourceStream("Capri.Voice.hello-" + name + ".wav");
		if (stream == null)
		{
			return null;
		}
		using MemoryStream memoryStream = new MemoryStream();
		stream.CopyTo(memoryStream);
		return memoryStream.ToArray();
	}

	private void PetLine(int ticket)
	{
		if (ticket == petTicket && !hidden && !chatting && speech == null && talkState == TalkState.Off && !typer.Visible)
		{
			heard = "pets you";
			box.Prompt = "> sys: ";
			Answer(++asking, petPurr ? NextPurrLine() : NextPetLine(), TalkState.Talking);
		}
	}

	private string NextPurrLine()
	{
		int pick = random.Next(PurrLines.Length - 1);
		lastPurr = pick >= lastPurr && lastPurr >= 0 ? pick + 1 : pick;
		return PurrLines[lastPurr];
	}

	internal string NextPetLine()
	{
		if (petBag.Count == 0)
		{
			for (int i = 0; i < PetLines.Length; i++)
			{
				petBag.Insert(random.Next(petBag.Count + 1), i);
			}
			if (petBag[0] == lastPet)
			{
				petBag[0] = petBag[petBag.Count - 1];
				petBag[petBag.Count - 1] = lastPet;
			}
		}
		lastPet = petBag[0];
		petBag.RemoveAt(0);
		return PetLines[lastPet];
	}

	protected override void OnMouseUp(MouseEventArgs e)
	{
		base.OnMouseUp(e);
		if (e.Button == MouseButtons.Right)
		{
			menu.Show(Cursor.Position);
		}
		else
		{
			if (e.Button != MouseButtons.Left || !pressed)
			{
				return;
			}
			pressed = false;
			Capture = false;
			if (dragging)
			{
				pendingClick = false;
				clickDelay.Stop();
				if (!onPanel)
				{
					Keys keys = ((!testing) ? Control.ModifierKeys : Keys.None);
					if ((keys & Keys.Control) != 0)
					{
						HangHere();
					}
					else if ((keys & Keys.Shift) != 0)
					{
						SitHere();
					}
					else if (!Throw() && !Drop())
					{
						leanAngle = 0.0;
						SavePreferences();
					}
				}
			}
			else if (pendingClick && IsDoubleClick(pendingPoint, PointToScreen(e.Location), clock.ElapsedMilliseconds - pendingTime))
			{
				pendingClick = false;
				clickDelay.Stop();
				StartRide();
			}
			else
			{
				pendingClick = true;
				pendingPoint = PointToScreen(e.Location);
				pendingTime = clock.ElapsedMilliseconds;
				clickDelay.Stop();
				clickDelay.Start();
			}
			dragging = false;
		}
	}

	protected override void OnMouseCaptureChanged(EventArgs e)
	{
		base.OnMouseCaptureChanged(e);
		if (!Capture)
		{
			pressed = false;
		}
	}

	protected override void WndProc(ref Message message)
	{
		if (message.Msg == 132 && frame != null)
		{
			long num = message.LParam.ToInt64();
			Point point = PointToClient(new Point((short)(num & 0xFFFF), (short)((num >> 16) & 0xFFFF)));
			if (!Solid(point))
			{
				message.Result = new IntPtr(-1);
				return;
			}
		}
		if (message.Msg == 786 && message.WParam.ToInt32() == 17249)
		{
			StopRide();
			return;
		}
		if (message.Msg == 786 && message.WParam.ToInt32() == 17238)
		{
			if (hidden)
			{
				SetHidden(value: false);
			}
			ToggleChat();
			return;
		}
		if (message.Msg == 786 && message.WParam.ToInt32() == 17229)
		{
			ToggleMic();
			return;
		}
		if (message.Msg == 786 && message.WParam.ToInt32() == 17236)
		{
			if (hidden)
			{
				SetHidden(value: false);
			}
			OpenTyper();
			return;
		}
		if (message.Msg == 786 && message.WParam.ToInt32() == 17224)
		{
			ToggleHidden();
			return;
		}
		if (message.Msg == 786 && message.WParam.ToInt32() == 17233)
		{
			ToggleShush();
			return;
		}
		if (message.Msg == 736)
		{
			anchor = KeepOnScreen(anchor);
			Location = anchor;
			RenderFrame();
		}
		base.WndProc(ref message);
	}

	private bool Solid(Point point, bool uncovered = false)
	{
		for (int i = -4; i <= 4; i += 4)
		{
			for (int j = -4; j <= 4; j += 4)
			{
				int num = point.X + i;
				int num2 = point.Y + j;
				if (num >= 0 && num2 >= 0 && num < frame.Width && num2 < frame.Height && frame.GetPixel(num, num2).A >= 12 && (!uncovered || Uncovered(PointToScreen(new Point(num, num2)))))
				{
					return true;
				}
			}
		}
		return false;
	}

	private void OnClickDelay()
	{
		clickDelay.Stop();
		if (pendingClick)
		{
			pendingClick = false;
			if (!hidden && !riding && !dragging && !pressed)
			{
				React();
			}
		}
	}

	internal static bool IsDoubleClick(Point a, Point b, long elapsed)
	{
		Size doubleClickSize = SystemInformation.DoubleClickSize;
		if (elapsed >= 0 && elapsed <= SystemInformation.DoubleClickTime && Math.Abs(a.X - b.X) <= doubleClickSize.Width / 2)
		{
			return Math.Abs(a.Y - b.Y) <= doubleClickSize.Height / 2;
		}
		return false;
	}

	private void StartRide(bool quiet = false)
	{
		if (riding || hidden || !IsHandleCreated)
		{
			return;
		}
		Halt();
		LeavePanel(home: false);
		dropAfter = false;
		pendingClick = false;
		clickDelay.Stop();
		pressed = false;
		dragging = false;
		Capture = false;
		seat = null;
		falling = false;
		hanging = false;
		walking = false;
		hopName = null;
		for (int i = 0; i < HopNames.Length; i++)
		{
			if (hopName != null)
			{
				break;
			}
			if (Native.RegisterHotKey(Handle, 17249, HopKeys[i, 0] | 0x4000, HopKeys[i, 1]))
			{
				hopName = HopNames[i];
			}
		}
		hotkey = hopName != null;
		riding = true;
		Native.SetWindowLong(Handle, -20, Native.GetWindowLong(Handle, -20) | 0x20);
		rideItem.Text = "Hop off";
		tray.Text = (hotkey ? ("Capri · " + hopName + " pra descer") : "Capri · Desça pelo menu da bandeja");
		if (!testing && !quiet)
		{
			balloonPage = null;
			balloonUpdate = false;
			balloonMainframe = false;
			tray.ShowBalloonTip(6000, "A Capri está no seu cursor", hotkey ? ("Aperte " + hopName + " pra ela descer.") : "Clique com o botão direito no ícone dela na bandeja e escolha Mover e Descer.", ToolTipIcon.Info);
		}
		Play(perchGlitch);
		frames.Start();
		pill.Hide();
		mainframe.Sync();
	}

	private void StopRide()
	{
		if (hotkey && IsHandleCreated)
		{
			Native.UnregisterHotKey(Handle, 17249);
		}
		hotkey = false;
		if (riding)
		{
			riding = false;
			leanAngle = 0.0;
			Play(grin);
			if (IsHandleCreated)
			{
				Native.SetWindowLong(Handle, -20, Native.GetWindowLong(Handle, -20) & -33);
			}
			if (rideItem != null)
			{
				rideItem.Text = "Ride cursor";
			}
			if (tray != null)
			{
				tray.Text = "Capri · Double-click to restore";
			}
			if (!IsDisposed)
			{
				Location = anchor;
				UpdateAnimation();
				SavePreferences();
				mainframe.Sync();
			}
		}
	}

	private Point PointerHome()
	{
		if (hidden || !preferences.Motion)
		{
			return Cursor.Position;
		}
		return new Point(anchor.X + 48 + (int)((float)preferences.Size * 0.267f) - 12, anchor.Y + 48 + (int)((float)preferences.Size * 0.73f) + 12);
	}

	private void FollowCursor()
	{
		Point position = Cursor.Position;
		Rectangle workingArea = Screen.FromPoint(position).WorkingArea;
		int num = 48 + (int)((float)preferences.Size * 0.267f) - 12;
		int num2 = 48 + (int)((float)preferences.Size * 0.73f) + 12;
		Point point = Within(new Point(position.X - num, position.Y - num2), workingArea, PerchedBody);
		int num3 = anchor.X + (int)Math.Round((double)(point.X - anchor.X) * 0.25);
		int num4 = anchor.Y + (int)Math.Round((double)(point.Y - anchor.Y) * 0.25);
		double num5 = Math.Max(-8.0, Math.Min(8.0, (double)(num3 - anchor.X) * 0.4));
		leanAngle = leanAngle * 0.8 + num5 * 0.2;
		anchor = Within(new Point(num3, num4), workingArea, PerchedBody);
	}

	private Point Hip()
	{
		if (walking && seat != null)
		{
			return new Point(anchor.X + 48 + (int)((float)preferences.Size * 0.35f), anchor.Y + 48 + (int)((float)preferences.Size * 0.99f));
		}
		return new Point(anchor.X + 48 + (int)((float)preferences.Size * SitX), anchor.Y + 48 + (int)((float)preferences.Size * 0.79f));
	}

	private Point Standing(int x, int y)
	{
		return new Point(x - 48 - (int)((float)preferences.Size * 0.35f), y - 48 - (int)((float)preferences.Size * 0.99f));
	}

	private Ledge Perch(IEnumerable<Ledge> ledges, Point hip)
	{
		return Ledges.Below(ledges, hip, Math.Max(32, (int)((float)preferences.Size * 0.45f)), Math.Max(160, preferences.Size), 24, Headroom());
	}

	private int Headroom()
	{
		return (int)Math.Ceiling((float)preferences.Size * (0.79f - PerchedBody.Top));
	}

	private Point Seated(int x, int y)
	{
		return new Point(x - 48 - (int)((float)preferences.Size * SitX), y - 48 - (int)((float)preferences.Size * 0.79f));
	}

	private List<IntPtr> Skip()
	{
		List<IntPtr> list = new List<IntPtr>();
		Form[] array = new Form[6] { this, pill, box, typer, mainframe, tear };
		foreach (Form form in array)
		{
			if (form.IsHandleCreated)
			{
				list.Add(form.Handle);
			}
		}
		return list;
	}

	private List<Ledge> Around()
	{
		List<IntPtr> list = Skip();
		IntPtr intPtr = (mainframe.IsHandleCreated ? mainframe.Handle : IntPtr.Zero);
		list.Remove(intPtr);
		return Ledges.Find(list, icons, intPtr);
	}

	private void SpawnInMiddle()
	{
		Rectangle workingArea = Screen.FromPoint(new Point(anchor.X + Width / 2, anchor.Y + Height / 2)).WorkingArea;
		seat = null;
		anchor = KeepOnScreen(new Point(workingArea.Left + (workingArea.Width - Width) / 2, workingArea.Top + (workingArea.Height - Height) / 2));
		Location = anchor;
		spawnFall = true;
	}

	private void Fall()
	{
		spawnFall = false;
		if (!riding && !onPanel && !dragging && !hanging && !hidden && seat == null)
		{
			falling = true;
			fallTo = null;
			fallSpeed = 0.0;
			fallStep = clock.Elapsed.TotalSeconds;
			frames.Start();
		}
	}

	private bool Drop()
	{
		if (preferences.NoSitting || onPanel)
		{
			return false;
		}
		Ledge ledge = Perch(Around(), Hip());
		if (ledge == null)
		{
			return false;
		}
		falling = true;
		fallTo = ledge;
		fallSpeed = 0.0;
		fallStep = clock.Elapsed.TotalSeconds;
		frames.Start();
		return true;
	}

	internal string ErrorDetails()
	{
		Cloud remote = brain.Remote;
		string text = "Capri v" + Assembly.GetExecutingAssembly().GetName().Version.ToString(3) + " | brain: " + ((remote != null) ? (remote.Name + " " + remote.Model) : ((brain.Local != null) ? ("built-in " + brain.Model) : ((brain.Model != null) ? ("Ollama " + brain.Model) : "none"))) + " | watch: " + (preferences.Watch ? (GlanceGap + " s") : "off") + " | voice: " + ((voice.Key != null) ? "ElevenLabs" : "none") + " | hey capri: " + (preferences.HeyCapri ? "on" : "off");
		string[] array = new string[0];
		try
		{
			if (Brain.LogPath != null && File.Exists(Brain.LogPath))
			{
				array = File.ReadAllLines(Brain.LogPath);
			}
		}
		catch (IOException)
		{
		}
		int num = Math.Max(0, array.Length - 25);
		return text + Environment.NewLine + ((array.Length == 0) ? "No errors logged." : string.Join(Environment.NewLine, array, num, array.Length - num));
	}

	private void CopyErrors()
	{
		try
		{
			Clipboard.SetText(ErrorDetails());
		}
		catch (ExternalException)
		{
			return;
		}
		Tell("copy error details", "Copied my error log. Paste it in the Discord so they can fix me, choom.");
	}

	internal void ToggleWander()
	{
		preferences.Wander = !preferences.Wander;
		wanderItem.Checked = preferences.Wander;
		nextWander = (preferences.Wander ? (clock.Elapsed.TotalSeconds + 3.0) : (-1.0));
		SavePreferences();
		mainframe.Sync();
	}

	private void CheckPopIn(double now, long quiet)
	{
		if (popOut >= 0.0 && (clicks != popClicks || chatting || typer.Visible || talkState != TalkState.Off))
		{
			EndPopIn(leave: false);
		}
		if (popOut >= 0.0 && now >= popOut && speech == null)
		{
			EndPopIn(leave: true);
		}
		if (!preferences.CheckIns || Hushed)
		{
			nextPopIn = -1.0;
			return;
		}
		if (nextPopIn < 0.0)
		{
			nextPopIn = now + PopGap();
		}
		if (!(now < nextPopIn))
		{
			nextPopIn = now + PopGap();
			if (quiet <= 60000 && !quitting && !dragging && !pressed && !chatting && !typer.Visible && !menu.Visible && speech == null && talkState == TalkState.Off && outro == null && !onPanel && !(popOut >= 0.0))
			{
				PopIn(now);
			}
		}
	}

	private void PopIn(double now)
	{
		bool wasHidden = hidden;
		string line = PopLines[random.Next(PopLines.Length)];
		if (!wasHidden && (!preferences.Wander || riding || hanging || (seat != null && seat.Free)))
		{
			if (IsHandleCreated)
			{
				Native.SetWindowPos(Handle, new IntPtr(-1), 0, 0, 0, 0, 19);
			}
			Say(line);
			popOut = (preferences.OnTop ? (-1.0) : (clock.Elapsed.TotalSeconds + 6.0));
			popClicks = clicks;
			popHide = false;
			return;
		}
		Rectangle workingArea = Screen.FromPoint(Cursor.Position).WorkingArea;
		Point spot = default;
		ref Point reference = ref spot;
		reference = new Point(workingArea.Left + (int)(random.NextDouble() * (double)Math.Max(1, workingArea.Width - Width)), workingArea.Bottom - Height - 12);
		Action action = () =>
		{
			StopRide();
			seat = null;
			falling = false;
			walking = false;
			anchor = spot;
			ShowHidden(value: false);
			DropSoon();
			if (IsHandleCreated)
			{
				Native.SetWindowPos(Handle, new IntPtr(-1), 0, 0, 0, 0, 19);
			}
			Say(line);
			popOut = ((wasHidden || !preferences.OnTop) ? (clock.Elapsed.TotalSeconds + 6.0) : (-1.0));
			popClicks = clicks;
			popHide = wasHidden;
		};
		if (wasHidden)
		{
			action();
		}
		else
		{
			GlitchOut(action, everywhere: false);
		}
	}

	private void EndPopIn(bool leave)
	{
		popOut = -1.0;
		if (!preferences.OnTop && IsHandleCreated)
		{
			Native.SetWindowPos(Handle, new IntPtr(-2), 0, 0, 0, 0, 19);
		}
		if (leave && popHide && !hidden)
		{
			SetHidden(value: true);
		}
		popHide = false;
	}

	internal void ToggleCheckIns()
	{
		preferences.CheckIns = !preferences.CheckIns;
		nextPopIn = -1.0;
		nudgeOut = -1.0;
		nudgeGap = 7200.0;
		noticed = -1.0;
		SavePreferences();
		mainframe.Sync();
	}

	internal void ToggleShush()
	{
		shushed = !shushed;
		nextPopIn = -1.0;
		nudgeOut = -1.0;
		nudgeGap = 7200.0;
		noticed = -1.0;
		nextGlance = -1.0;
		if (shushed)
		{
			voice.Stop();
		}
		Say(shushed ? ("Going quiet. " + QuietKeyName + " when you want me back.") : "Voltei, choom.");
	}

	private void CheckNudge(double now, long quiet)
	{
		bool flag = clicks != noticedClicks || dragging || pressed || chatting || typer.Visible || menu.Visible || talkState != TalkState.Off || onPanel;
		if (noticed < 0.0 || flag)
		{
			noticed = now;
			noticedClicks = clicks;
		}
		if (nudgeOut >= 0.0)
		{
			if (flag)
			{
				nudgeOut = -1.0;
				nudgeGap = 7200.0;
				if (!chatting && !typer.Visible && talkState == TalkState.Off && !onPanel)
				{
					Say(NoticedLines[random.Next(NoticedLines.Length)]);
				}
			}
			else if (now >= nudgeOut && speech == null)
			{
				nudgeOut = -1.0;
				nudgeGap = Math.Min(nudgeGap * 2.0, 28800.0);
				noticed = now;
				if (quiet < 20000 && !hidden)
				{
					Say(SnubbedLines[random.Next(SnubbedLines.Length)]);
				}
			}
		}
		else if (preferences.CheckIns && !Hushed && !hidden && quiet <= 30000 && !(now - noticed < nudgeGap) && (!(lastGlance >= 0.0) || !(now - lastGlance < 300.0)) && !quitting && !riding && !onPanel && !falling && !hanging && !typer.Visible && speech == null && outro == null && !(popOut >= 0.0) && (clip == idle || clip == perch))
		{
			Nudge(now);
		}
	}

	private void Nudge(double now)
	{
		nudgeOut = now + 20.0;
		string line = NudgeLines[random.Next(NudgeLines.Length)];
		Point position = Cursor.Position;
		Point pt = Hip();
		Rectangle workingArea = Screen.FromPoint(position).WorkingArea;
		Action ask = () =>
		{
			if (!preferences.OnTop && IsHandleCreated)
			{
				Native.SetWindowPos(Handle, new IntPtr(-1), 0, 0, 0, 0, 19);
				popOut = clock.Elapsed.TotalSeconds + 20.0;
				popClicks = clicks;
				popHide = false;
			}
			Say(line);
		};
		if (!preferences.Wander || (seat != null && seat.Free) || (workingArea.Contains(pt) && Math.Abs(pt.X - position.X) <= Math.Max(300, Width * 2)))
		{
			ask();
			return;
		}
		int val = ((position.X - workingArea.Left < workingArea.Width / 2) ? (position.X + Width / 2) : (position.X - Width - Width / 2));
		Point spot = default;
		ref Point reference = ref spot;
		reference = new Point(Math.Max(workingArea.Left, Math.Min(workingArea.Right - Width, val)), workingArea.Bottom - Height - 12);
		GlitchOut(() =>
		{
			StopRide();
			seat = null;
			falling = false;
			walking = false;
			anchor = spot;
			ShowHidden(value: false);
			DropSoon();
			ask();
		}, everywhere: false);
	}

	private static bool Installed()
	{
		try
		{
			return string.Equals(Path.GetFullPath(Application.ExecutablePath), Path.GetFullPath(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData), "Capri", "Capri.exe")), StringComparison.OrdinalIgnoreCase);
		}
		catch (ArgumentException)
		{
			return false;
		}
		catch (NotSupportedException)
		{
			return false;
		}
		catch (IOException)
		{
			return false;
		}
	}

	internal void DefaultStartup(bool installed)
	{
		if (!preferences.StartupSet && installed && Startup.Set(Application.ExecutablePath, on: true))
		{
			preferences.StartupSet = true;
			SavePreferences();
			mainframe.Sync();
		}
	}

	internal void ToggleStartup()
	{
		if (!Startup.Set(Application.ExecutablePath, !StartsWithWindows))
		{
			Brain.Log("startup", -1L, "Windows wouldn't let Capri change her Run entry.");
		}
		preferences.StartupSet = true;
		SavePreferences();
		mainframe.Sync();
	}

	internal void ToggleCursor()
	{
		preferences.QuickHands = !preferences.QuickHands;
		SavePreferences();
		mainframe.Sync();
	}

	internal void ToggleBypass()
	{
		Security.Pick(Computer.Bypass ? 2 : 3);
	}

	internal static bool Migrate(Preferences saved)
	{
		if (saved.Permissions != null)
		{
			return false;
		}
		saved.Permissions = Security.Of(saved.Bypass ? 3 : 2);
		if (saved.Bypass)
		{
			saved.HeyCapri = true;
		}
		return true;
	}

	private void SecurityChanged()
	{
		preferences.Permissions = Security.Saved;
		preferences.Bypass = Computer.Bypass;
		SavePreferences();
		mainframe.Sync();
	}

