	private static bool SpotifyRunning()
	{
		Process[] processesByName = Process.GetProcessesByName("Spotify");
		Process[] array = processesByName;
		foreach (Process process in array)
		{
			process.Dispose();
		}
		return processesByName.Length > 0;
	}

	private string DoTool(string tool, ToolArguments args)
	{
		return DoTool(tool, args, asking);
	}

	private string DoTool(string tool, ToolArguments args, int ticket)
	{
		if (ticket == escAsk)
		{
			return "";
		}
		string text = Security.Gate(tool, args);
		if (text != null)
		{
			return text;
		}
		string text2 = ((preferences.QuickHands || args == null || brain.Model == null || !Security.On(5)) ? null : CursorJob(tool, args));
		bool flag = text2 != null || tool == "use_computer";
		bool flag2 = false;
		bool lockTaken = false;
		string text3;
		try
		{
			if (flag)
			{
				Monitor.Enter(mouseGate, ref lockTaken);
			}
			if (ticket == escAsk)
			{
				text3 = "";
			}
			else if (text2 == null)
			{
				text3 = Hands.Do(tool, args);
			}
			else
			{
				try
				{
					text3 = Hands.Work(text2, null);
				}
				catch (WebException ex)
				{
					text3 = "That didn't work: " + ex.Message;
					flag2 = ex.Status != WebExceptionStatus.RequestCanceled;
				}
				catch (Exception ex2)
				{
					text3 = "That didn't work: " + ex2.Message;
					flag2 = true;
				}
			}
		}
		finally
		{
			if (lockTaken)
			{
				Monitor.Exit(mouseGate);
			}
		}
		if (text3 == "You pressed Esc, so I stopped.")
		{
			escAsk = ticket;
		}
		if (text2 != null && (flag2 || (text3 != null && (text3.Contains("Bigger brain models handle jobs like this better. Pick one under BRAIN in Capri Mainframe.") || (tool == "media" && Hands.Failed(text3) && !text3.StartsWith("You ", StringComparison.Ordinal))))))
		{
			text3 = Hands.Do(tool, args);
		}
		if (tool != "look_at_screen" && !string.IsNullOrEmpty(text3))
		{
			Brain.Transcribe(null, "Job: " + text3);
		}
		return text3;
	}

	internal static string CursorJob(string tool, ToolArguments args)
	{
		if (tool == "play_music" && !string.IsNullOrWhiteSpace(args.Song))
		{
			string text = args.Song.Trim();
			if (!(args.App == "spotify") && (!(args.App != "youtube") || !Hands.Installed("spotify")))
			{
				return "Play " + Voice.Quote(text) + " on YouTube: open YouTube, click its search bar, type " + Voice.Quote(text) + " and press Enter, scroll down through the results and look at a few, then click the video that fits best.";
			}
			if (Regex.IsMatch(text, "^liked songs$", RegexOptions.IgnoreCase))
			{
				return "Play their Liked Songs on Spotify: open Spotify, go to Your Library, open Liked Songs and press its play button.";
			}
			return "Play " + Voice.Quote(text) + ((string.IsNullOrEmpty(args.Kind) || args.Kind == "song") ? "" : (" (the " + args.Kind + ")")) + " on Spotify: open Spotify, click its search box, type " + Voice.Quote(text) + " and press Enter, then press play on the best match.";
		}
		if (tool == "open_website" && !string.IsNullOrWhiteSpace(args.Search) && Regex.IsMatch((args.Site ?? "").Trim(), "^(https?://)?(www\\.|m\\.)?youtube(\\.com)?/?$", RegexOptions.IgnoreCase))
		{
			return "Search YouTube for " + Voice.Quote(args.Search.Trim()) + ": open YouTube, click its search bar, type it and press Enter, then scroll down through the results.";
		}
		if (tool == "media" && (args.Action == "volume_up" || args.Action == "volume_down") && args.App == "spotify" && SpotifyOpen())
		{
			bool flag = args.Action == "volume_up";
			return "Turn Spotify's volume " + (flag ? "up" : "down") + ": open Spotify and drag its volume slider, at the bottom right, a little to the " + (flag ? "right." : "left.");
		}
		return null;
	}

	private void CheckWander(double now, long quiet)
	{
		bool flag = talkState == TalkState.Off || (talkState == TalkState.Talking && replyDone >= 0.0 && now - replyDone > 8.0);
		if (!preferences.Wander || napAsked || napping || hidden || dragging || pressed || riding || onPanel || falling || hanging || chatting || typer.Visible || menu.Visible || speech != null || !flag || quiet > 90000 || (seat != null && seat.Free) || outro != null || (clip != idle && clip != perch && clip != dance && clip != perchDance))
		{
			return;
		}
		double num = WanderPaces[preferences.WanderPace];
		if (nextWander < 0.0)
		{
			nextWander = now + (20.0 + random.NextDouble() * 40.0) * num;
		}
		if (!(now < nextWander))
		{
			nextWander = now + (45.0 + random.NextDouble() * 75.0) * num;
			if (talkState != TalkState.Off)
			{
				CloseTalk();
			}
			if (!(random.NextDouble() < 0.5) || !Blink())
			{
				Wander();
			}
		}
	}

	private bool Stroll()
	{
		if (walking || riding || onPanel || falling || hanging || dragging || outro != null || (seat != null && (seat.Free || !seat.Icon.IsEmpty)))
		{
			return false;
		}
		int size = preferences.Size;
		Point point = Hip();
		Rectangle workingArea = Screen.FromPoint(point).WorkingArea;
		int num;
		int to;
		int num2;
		if (seat != null)
		{
			if (seat.Y - (int)((float)size * 0.99f) < Screen.FromPoint(point).Bounds.Top)
			{
				return false;
			}
			num = Math.Max(seat.Left, workingArea.Left) + (int)((float)size * 0.1f) + 8;
			to = Math.Min(seat.Right, workingArea.Right) - (int)((float)size * 0.41f) - 8;
			num2 = point.X;
		}
		else
		{
			num = workingArea.Left - 48 - (int)((float)size * Body.Left);
			to = workingArea.Right - 48 - (int)Math.Ceiling((float)size * Body.Right);
			num2 = anchor.X;
		}
		int num3 = WalkTarget(num2, num, to, size, random.NextDouble(), random.NextDouble());
		if (num3 == num2)
		{
			return false;
		}
		if (seat != null)
		{
			anchor = Standing(point.X, seat.Y);
			num3 -= point.X - anchor.X;
		}
		walking = true;
		walkTo = num3;
		walkStep = clock.Elapsed.TotalSeconds;
		walkCarry = 0.0;
		Play(walk);
		frames.Start();
		return true;
	}

	private bool Blink()
	{
		if (walking || riding || falling || hanging || dragging || outro != null || seat == null || seat.Free || !seat.Icon.IsEmpty)
		{
			return false;
		}
		int size = preferences.Size;
		Point point = Hip();
		Rectangle workingArea = Screen.FromPoint(point).WorkingArea;
		int num = Math.Max(seat.Left, workingArea.Left) + (int)((float)size * 0.1f) + 8;
		int to = Math.Min(seat.Right, workingArea.Right) - (int)((float)size * 0.41f) - 8;
		int target = WalkTarget(point.X, num, to, size, random.NextDouble(), random.NextDouble());
		if (target == point.X)
		{
			return false;
		}
		Ledge spot = seat;
		GlitchOut(() =>
		{
			Hop(spot, target);
		}, everywhere: false);
		return true;
	}

	internal static int WalkTarget(int at, int from, int to, int size, double side, double length)
	{
		int num = size / 2;
		int val = size * 3;
		bool flag = side < 0.5;
		if ((flag ? (to - at) : (at - from)) < num)
		{
			flag = !flag;
		}
		int num2 = Math.Min(val, flag ? (to - at) : (at - from));
		if (num2 < num)
		{
			return at;
		}
		int num3 = num + (int)((double)(num2 - num) * length);
		if (!flag)
		{
			return at - num3;
		}
		return at + num3;
	}

	private void Walk(double now)
	{
		double num = Math.Max(0.0, Math.Min(0.05, now - walkStep));
		walkStep = now;
		int value = walkTo - anchor.X;
		walkCarry += (double)preferences.Size * 0.42 * num;
		int num2 = (int)walkCarry;
		walkCarry -= num2;
		if (Math.Abs(value) <= num2)
		{
			anchor.X = walkTo;
			EndWalk();
		}
		else
		{
			anchor.X += Math.Sign(value) * num2;
			if (Zappy && random.NextDouble() < num * 3.0)
			{
				Rectangle feet = ZapBody();
				crackle.Fizz(new Point(feet.Left + feet.Width / 2, feet.Bottom), (float)preferences.Size / 240f);
			}
			leanAngle = leanAngle * 0.85 + (double)Math.Sign(value) * 2.5 * 0.15;
		}
	}

	private void EndWalk()
	{
		if (walking)
		{
			Point point = Hip();
			walking = false;
			leanAngle = 0.0;
			if (seat != null)
			{
				anchor = Seated(point.X, seat.Y);
				Play(perchGlitch);
			}
			else
			{
				Play(idle);
			}
			SavePreferences();
		}
	}

	private void GlitchOut(Action then, bool everywhere = true)
	{
		if (instant || hidden || !IsHandleCreated || !preferences.Motion)
		{
			then();
			return;
		}
		EndWalk();
		falling = false;
		fallTo = null;
		dropAfter = false;
		pendingClick = false;
		clickDelay.Stop();
		Companion companion = this;
		Clip next;
		if (lying)
		{
			next = laydownLeave;
		}
		else
		{
			next = ((seat != null || riding || onPanel) ? perchLeave : leave);
		}
		companion.Play(next);
		if (frame != null)
		{
			shatter.Play(new Bitmap(frame), anchor, Screen.FromPoint(new Point(anchor.X + Width / 2, anchor.Y + Height / 2)).Bounds, leave: true, preferences.Size);
			veiled = true;
			Zap(0.6, ground: seat != null, null);
		}
		Static(everywhere, everywhere ? Cue.Leave : Cue.Hop);
		outro = then;
		outroAt = clipStart + (double)(clip.Count + 1) / clip.Fps;
		frames.Start();
	}

	internal void Quit()
	{
		quitting = true;
		GlitchOut(Close);
	}

	private void Halt()
	{
		if (outro != null && !quitting)
		{
			outro = null;
			shatter.Stop();
			if (clip == leave || clip == perchLeave)
			{
				Play((seat != null || riding || onPanel) ? perch : idle);
			}
		}
	}

	private void Static(bool everywhere, Cue? sound, bool spawn = false)
	{
		if (!instant && !hidden && preferences.Motion && IsHandleCreated)
		{
			Rectangle rectangle = BodyOnScreen(anchor, (seat != null || riding || onPanel) ? PerchedBody : Body);
			tear.Burst(rectangle, Screen.FromRectangle(rectangle).Bounds, everywhere, spawn, Handle);
			if (sound.HasValue)
			{
				Sfx.Play(sound.Value);
			}
		}
	}

