	internal static bool Bindable(int mods, int vk)
	{
		if ((mods & -16) == 0 && vk > 0 && vk < 255)
		{
			return Array.IndexOf(NotKeys, vk) < 0;
		}
		return false;
	}

	internal static bool ByMouse(int vk)
	{
		if (vk >= 4)
		{
			return vk <= 6;
		}
		return false;
	}

	internal static int HotMods(Keys keys, bool win)
	{
		return (int)((((keys & Keys.Alt) != 0) ? 1u : 0u) | (uint)(((keys & Keys.Control) != 0) ? 2 : 0) | (uint)(((keys & Keys.Shift) != 0) ? 4 : 0)) | (win ? 8 : 0);
	}

	internal static string ModNames(int mods)
	{
		return (((mods & 8) != 0) ? "Win + " : "") + (((mods & 2) != 0) ? "Ctrl + " : "") + (((mods & 1) != 0) ? "Alt + " : "") + (((mods & 4) != 0) ? "Shift + " : "");
	}

	internal static string KeyName(int mods, int vk)
	{
		return ModNames(mods) + KeyWord(vk);
	}

	private static string KeyWord(int vk)
	{
		if ((vk >= 65 && vk <= 90) || (vk >= 48 && vk <= 57))
		{
			return ((char)vk).ToString();
		}
		if (vk >= 112 && vk <= 135)
		{
			return "F" + (vk - 111);
		}
		if (vk >= 96 && vk <= 105)
		{
			return "Num " + (vk - 96);
		}
		if (ByMouse(vk))
		{
			return MouseWords[vk - 4];
		}
		int num = Array.IndexOf(WordedKeys, vk);
		if (num >= 0)
		{
			return KeyWords[num];
		}
		char c = (char)(Native.MapVirtualKey(vk, 2) & 0xFFFF);
		if (c <= ' ')
		{
			return "Key " + vk;
		}
		return c.ToString();
	}

	internal static bool Swallows(int mods, int vk)
	{
		if ((mods & 0xB) == 0)
		{
			if ((vk < 65 || vk > 90) && (vk < 48 || vk > 57) && (vk < 96 || vk > 111) && (vk < 186 || vk > 192) && (vk < 219 || vk > 223) && vk != 226 && vk != 32 && vk != 13 && vk != 9)
			{
				return vk == 8;
			}
			return true;
		}
		return false;
	}

	internal static void CheckKeys(Preferences value)
	{
		if (!Bindable(value.TalkMods, value.TalkVk))
		{
			value.TalkMods = 3;
			value.TalkVk = 86;
		}
		if (!Bindable(value.MuteMods, value.MuteVk) || (value.MuteMods == value.TalkMods && value.MuteVk == value.TalkVk))
		{
			value.MuteMods = 3;
			value.MuteVk = 78;
		}
		if (!Bindable(value.TypeMods, value.TypeVk))
		{
			value.TypeMods = 3;
			value.TypeVk = 84;
		}
		if (!Bindable(value.HideMods, value.HideVk))
		{
			value.HideMods = 3;
			value.HideVk = 72;
		}
		if (!Bindable(value.QuietMods, value.QuietVk))
		{
			value.QuietMods = 3;
			value.QuietVk = 80;
		}
		Unclash(value);
	}

	internal static void Unclash(Preferences value)
	{
		int[] array = new int[10] { value.TalkMods, value.TalkVk, value.MuteMods, value.MuteVk, value.TypeMods, value.TypeVk, value.HideMods, value.HideVk, value.QuietMods, value.QuietVk };
		for (int i = 2; i < KeyJobs.Length; i++)
		{
			if (!Clashes(array, i, array[i * 2], array[i * 2 + 1], i))
			{
				continue;
			}
			int[] array2 = SpareKeys[i];
			foreach (int num in array2)
			{
				if (!Clashes(array, i, 3, num, KeyJobs.Length))
				{
					array[i * 2] = 3;
					array[i * 2 + 1] = num;
					break;
				}
			}
		}
		value.TypeMods = array[4];
		value.TypeVk = array[5];
		value.HideMods = array[6];
		value.HideVk = array[7];
		value.QuietMods = array[8];
		value.QuietVk = array[9];
	}

	private static bool Clashes(int[] bound, int slot, int mods, int vk, int below)
	{
		for (int i = 0; i < below; i++)
		{
			if (i != slot && bound[i * 2] == mods && bound[i * 2 + 1] == vk)
			{
				return true;
			}
		}
		return false;
	}

	internal string SetHotkey(int slot, Keys keys)
	{
		return SetHotkey(slot, HotMods(keys, win: false), (int)(keys & Keys.KeyCode));
	}

	internal string SetHotkey(int slot, int mods, int vk)
	{
		if (!Bindable(mods, vk))
		{
			return "Press a key, alone or with Ctrl, Alt, Shift or Win.";
		}
		string text = KeyName(mods, vk);
		int[] array = new int[10] { preferences.TalkMods, preferences.TalkVk, preferences.MuteMods, preferences.MuteVk, preferences.TypeMods, preferences.TypeVk, preferences.HideMods, preferences.HideVk, preferences.QuietMods, preferences.QuietVk };
		for (int i = 0; i < KeyJobs.Length; i++)
		{
			if (i != slot && mods == array[i * 2] && vk == array[i * 2 + 1])
			{
				return text + " is already her " + KeyJobs[i] + " key.";
			}
		}
		if (!testing && IsHandleCreated)
		{
			if (slot == 1)
			{
				bool flag = muteKey;
				if (flag)
				{
					Native.UnregisterHotKey(Handle, 17229);
				}
				bool flag2 = ByMouse(vk) || Native.RegisterHotKey(Handle, 17229, mods | 0x4000, vk);
				if (flag2 && !flag && !ByMouse(vk))
				{
					Native.UnregisterHotKey(Handle, 17229);
				}
				if (!flag2)
				{
					if (flag)
					{
						muteKey = ByMouse(preferences.MuteVk) || Native.RegisterHotKey(Handle, 17229, preferences.MuteMods | 0x4000, preferences.MuteVk);
					}
					return text + " is taken by another app. Try another.";
				}
			}
			else
			{
				int id = slot switch
				{
					3 => 17224, 
					2 => 17236, 
					0 => 17238, 
					_ => 17233, 
				};
				if (slot switch
				{
					3 => hideKey, 
					2 => typeKey, 
					0 => talkKey, 
					_ => quietKey, 
				})
				{
					Native.UnregisterHotKey(Handle, id);
				}
				bool flag3 = ByMouse(vk) || Native.RegisterHotKey(Handle, id, mods | 0x4000, vk);
				bool flag4 = flag3 || ByMouse(array[slot * 2 + 1]) || Native.RegisterHotKey(Handle, id, array[slot * 2] | 0x4000, array[slot * 2 + 1]);
				switch (slot)
				{
				case 0:
					talkKey = flag4;
					break;
				case 2:
					typeKey = flag4;
					break;
				case 3:
					hideKey = flag4;
					break;
				default:
					quietKey = flag4;
					break;
				}
				if (!flag3)
				{
					return text + " is taken by another app. Try another.";
				}
			}
		}
		switch (slot)
		{
		case 0:
			preferences.TalkMods = mods;
			preferences.TalkVk = vk;
			break;
		case 1:
			preferences.MuteMods = mods;
			preferences.MuteVk = vk;
			break;
		case 2:
			preferences.TypeMods = mods;
			preferences.TypeVk = vk;
			break;
		case 3:
			preferences.HideMods = mods;
			preferences.HideVk = vk;
			break;
		default:
			preferences.QuietMods = mods;
			preferences.QuietVk = vk;
			break;
		}
		SavePreferences();
		WatchMouse();
		if (!testing)
		{
			mainframe.ShowShortcut(talkKey, mute: true);
			mainframe.ShowKeys(typeKey, hideKey, quietKey);
		}
		mainframe.Hotkeys(TalkKeyName, MuteKeyName, TypeKeyName, HideKeyName, QuietKeyName);
		return null;
	}

	private void WatchMouse()
	{
		if (!testing && (ByMouse(preferences.TalkVk) || ByMouse(preferences.MuteVk) || ByMouse(preferences.TypeVk) || ByMouse(preferences.HideVk) || ByMouse(preferences.QuietVk)))
		{
			if (!mouseKeys.Enabled)
			{
				int[] array = new int[3] { 4, 5, 6 };
				foreach (int key in array)
				{
					Native.GetAsyncKeyState(key);
				}
			}
			mouseKeys.Start();
		}
		else
		{
			mouseKeys.Stop();
		}
	}

	internal void WatchMouseKeys()
	{
		int[] array = new int[10] { preferences.TalkMods, preferences.TalkVk, preferences.MuteMods, preferences.MuteVk, preferences.TypeMods, preferences.TypeVk, preferences.HideMods, preferences.HideVk, preferences.QuietMods, preferences.QuietVk };
		int[] array2 = new int[5] { 17238, 17229, 17236, 17224, 17233 };
		int num = (KeyHeld(18) ? 1 : 0) | (KeyHeld(17) ? 2 : 0) | (KeyHeld(16) ? 4 : 0) | ((KeyHeld(91) || KeyHeld(92)) ? 8 : 0);
		Dictionary<int, bool> dictionary = new Dictionary<int, bool>();
		for (int i = 0; i < array2.Length; i++)
		{
			int num2 = array[i * 2 + 1];
			bool value = false;
			if (ByMouse(num2) && !dictionary.TryGetValue(num2, out value))
			{
				value = (dictionary[num2] = KeyHeld(num2));
			}
			bool flag2 = value && !mouseHeld[i] && num == array[i * 2];
			mouseHeld[i] = value;
			if (flag2 && (i != 1 || muteKey) && !mainframe.Picking)
			{
				Message m = Message.Create(Handle, 786, new IntPtr(array2[i]), IntPtr.Zero);
				WndProc(ref m);
			}
		}
	}

