	internal static int PerchRate(int fps)
	{
		if (fps <= 0)
		{
			return 30;
		}
		int num = 0;
		for (int i = 0; i < PerchRates.Length; i++)
		{
			if (Math.Abs(PerchRates[i] - fps) < Math.Abs(PerchRates[num] - fps))
			{
				num = i;
			}
		}
		return PerchRates[num];
	}

