	internal string ChooseCustomModel(string name, string[] installed)
	{
		name = (name ?? "").Trim();
		if (name.Length == 0)
		{
			return "Type a model name first.";
		}
		if (brain.Local != null)
		{
			return "Custom models need Ollama or an API key.";
		}
		if (brain.Model == null)
		{
			return "Find her a brain first.";
		}
		Cloud remote = brain.Remote;
		if (remote == null && installed != null && Array.IndexOf(installed, name) < 0 && Array.IndexOf(installed, name + ":latest") < 0)
		{
			return "Ollama doesn't have it. Run: ollama pull " + name;
		}
		ChooseModel(name);
		if (remote == null)
		{
			mainframe.ShowOllama(installed ?? new string[1] { name }, name);
			return "Using " + name + ".";
		}
		if (cloudModels == null)
		{
			cloudModels = new List<string> { remote.Model };
		}
		if (!cloudModels.Contains(name))
		{
			cloudModels.Add(name);
		}
		mainframe.ShowCloud(remote, cloudModels);
		return "Using " + name + ". If it doesn't answer, it isn't on your key.";
	}

