	private void CheckLag(double now)
	{
		if (now - lagAt < 15.0)
		{
			return;
		}
		lagAt = now;
		if (Native.CpuTimes(out var num, out var total))
		{
			double busy = ((lagTotal == 0 || total <= lagTotal) ? 0.0 : (1.0 - (double)(num - lagIdle) / (double)(total - lagTotal)));
			lagIdle = num;
			lagTotal = total;
			bool free = preferences.CheckIns && !Hushed && !hidden && !quitting && !dragging && !pressed && !chatting && !typer.Visible && !menu.Visible && speech == null && talkState == TalkState.Off && !onPanel && outro == null && !Native.Gaming();
			string text = Lagging(busy, now, free);
			if (text != null)
			{
				Say(text);
			}
		}
	}

	private string Lagging(double busy, double now, bool free)
	{
		lagHot = ((busy >= 0.9) ? (lagHot + 1) : 0);
		if (lagHot < 4 || !free || now - lagSaid < 1800.0)
		{
			return null;
		}
		lagHot = 0;
		lagSaid = now;
		return LagLines[random.Next(LagLines.Length)];
	}

	private string Cheer(bool game, bool song, double now, bool free)
	{
		bool flag = game && !homeGame;
		bool flag2 = song && !homeSong;
		homeGame = game;
		homeSong = song;
		if (!free)
		{
			return null;
		}
		if (flag && now - gameCheered >= 7200.0)
		{
			gameCheered = now;
			return HomeGameLines[random.Next(HomeGameLines.Length)];
		}
		if (flag2 && now - songCheered >= 7200.0)
		{
			songCheered = now;
			return HomeSongLines[random.Next(HomeSongLines.Length)];
		}
		return null;
	}

	private static bool MediaPlaying()
	{
		//IL_0050: Unknown result type (might be due to invalid IL or missing references)
		//IL_0056: Invalid comparison between Unknown and I4
		//IL_006d: Unknown result type (might be due to invalid IL or missing references)
		//IL_0073: Invalid comparison between Unknown and I4
		//IL_0095: Unknown result type (might be due to invalid IL or missing references)
		//IL_009b: Invalid comparison between Unknown and I4
		if (mediaMissing)
		{
			return false;
		}
		try
		{
			if (media == null)
			{
				media = GlobalSystemMediaTransportControlsSessionManager.RequestAsync().AsTask<GlobalSystemMediaTransportControlsSessionManager>().Result;
			}
			foreach (GlobalSystemMediaTransportControlsSession session in media.GetSessions())
			{
				GlobalSystemMediaTransportControlsSessionPlaybackInfo playbackInfo = session.GetPlaybackInfo();
				if (playbackInfo == null || (int)playbackInfo.PlaybackStatus != 4)
				{
					continue;
				}
				Windows.Media.MediaPlaybackType? playbackType = playbackInfo.PlaybackType;
				if (playbackType.HasValue && (int)playbackType.Value == 2)
				{
					continue;
				}
				if (IsMusicApp(session.SourceAppUserModelId))
				{
					return true;
				}
				if (!playbackType.HasValue || (int)playbackType.Value != 1)
				{
					continue;
				}
				try
				{
					GlobalSystemMediaTransportControlsSessionMediaProperties result = session.TryGetMediaPropertiesAsync().AsTask<GlobalSystemMediaTransportControlsSessionMediaProperties>().Result;
					GlobalSystemMediaTransportControlsSessionTimelineProperties timelineProperties = session.GetTimelineProperties();
					if (result != null && IsSong(result.Title, result.Artist, (timelineProperties != null) ? (timelineProperties.EndTime - timelineProperties.StartTime) : TimeSpan.Zero))
					{
						return true;
					}
				}
				catch (Exception)
				{
				}
			}
			return false;
		}
		catch (TypeLoadException)
		{
			mediaMissing = true;
			return false;
		}
		catch (Exception)
		{
			media = null;
			return false;
		}
	}

	internal static bool IsMusicApp(string id)
	{
		if (id != null)
		{
			return Regex.IsMatch(id, "spotify|zunemusic|applemusic|itunes|amazonmusic|tidal|deezer|foobar|musicbee|winamp|aimp|soundcloud|pandora", RegexOptions.IgnoreCase);
		}
		return false;
	}

	internal static bool IsSong(string title, string artist, TimeSpan length)
	{
		if (Regex.IsMatch(title ?? "", "official\\s+(music\\s+)?(video|audio|visuali[sz]er)|\\blyrics?\\b|\\bremix\\b|\\bmix\\b|playlist|\\blo-?fi\\b|beats to|\\bradio\\b|\\bdj\\b|full album|nightcore|sped up|slowed|\\bfeat\\.|\\bft\\.|[(\\[]audio[)\\]]", RegexOptions.IgnoreCase))
		{
			return true;
		}
		if (!string.IsNullOrWhiteSpace(artist) && length > TimeSpan.Zero)
		{
			return length <= TimeSpan.FromMinutes(12.0);
		}
		return false;
	}

