	private void Tuned(Tune tune, double now, double asked)
	{
		if (tune != null && tune.Playing)
		{
			tuneHeard = now;
		}
		else if (playerClosed && now - tuneHeard >= 10.0)
		{
			playerClosed = false;
			tuneHeard = -1.0;
		}
		bool flag = !preferences.NoPlayer && !hidden && !quitting && !playerClosed;
		bool flag2 = flag && tune != null && tuneHeard >= 0.0 && now - tuneHeard < 60.0 && !FullScreen();
		if (!flag2 && flag && player.Busy)
		{
			flag2 = true;
			tune = tune ?? player.Tune;
		}
		if (!flag2)
		{
			HidePlayer();
		}
		else if (!player.Visible || !(asked < player.SentAt + 0.3))
		{
			ShowPlayer(tune, now);
		}
	}

