	private bool HopOnPlayer()
	{
		if (seat != null && seat.Window == player.Handle)
		{
			return true;
		}
		bool flag = talkState == TalkState.Off || (talkState == TalkState.Talking && replyDone >= 0.0 && clock.Elapsed.TotalSeconds - replyDone > 8.0);
		if (!preferences.Wander || preferences.NoSitting || napAsked || napping || hidden || dragging || pressed || riding || onPanel || falling || hanging || walking || chatting || typer.Visible || menu.Visible || speech != null || !flag || (seat != null && seat.Free) || outro != null || (clip != idle && clip != perch && clip != dance && clip != perchDance))
		{
			return false;
		}
		Rectangle plate = player.Plate;
		int x = plate.Left + (int)((float)plate.Width * 0.1f);
		Ledge spot = Around().Find((Ledge ledge) => ledge.Window == player.Handle && ledge.Left <= x && x <= ledge.Right);
		if (spot == null || spot.Y - Headroom() < Screen.FromPoint(new Point(x, spot.Y)).Bounds.Top)
		{
			return false;
		}
		GlitchOut(() =>
		{
			Hop(spot, x);
		}, everywhere: false);
		return true;
	}

