	private void PlayerLayer(bool now)
	{
		if (!player.IsHandleCreated || !IsHandleCreated)
		{
			return;
		}
		IntPtr foregroundWindow = Native.GetForegroundWindow();
		if (now || !(foregroundWindow == playerFront))
		{
			playerFront = foregroundWindow;
			if (!preferences.OnTop)
			{
				Native.SetWindowPos(player.Handle, Handle, 0, 0, 0, 0, 19);
				return;
			}
			Native.SetWindowPos(player.Handle, new IntPtr(-1), 0, 0, 0, 0, 19);
			lastForeground = new IntPtr(-1);
			StayOnTop();
		}
	}

	private void PlayerCommand(string what)
	{
		if (what == "menu")
		{
			ShowPlayerMenu();
		}
		else if (what == "close")
		{
			playerClosed = true;
			HidePlayer();
		}
		else
		{
			if (player.Tune == null)
			{
				return;
			}
			lock (playerPresses)
			{
				playerPresses.Enqueue(new KeyValuePair<Tune, string>(player.Tune, what));
				if (playerSending)
				{
					return;
				}
				playerSending = true;
			}
			ThreadPool.QueueUserWorkItem((object param0) =>
			{
				while (true)
				{
					KeyValuePair<Tune, string> press;
					lock (playerPresses)
					{
						if (playerPresses.Count == 0)
						{
							playerSending = false;
							break;
						}
						press = playerPresses.Dequeue();
					}
					bool sent = false;
					try
					{
						sent = Tunes.Send(press.Key, press.Value);
					}
					catch (Exception)
					{
					}
					Post(() =>
					{
						player.Sent(press.Value, sent);
						tuneAt = -10.0;
					});
				}
			});
		}
	}

