	private List<Ledge> Spots()
	{
		List<Ledge> list = new List<Ledge>();
		int num = Headroom();
		foreach (Ledge item in Around())
		{
			if (item.Icon.IsEmpty && item.Right - item.Left >= preferences.Size / 2 && (seat == null || !(item.Window == seat.Window) || item.Floor != seat.Floor) && item.Y - num >= Screen.FromPoint(new Point(item.Left, item.Y)).Bounds.Top)
			{
				list.Add(item);
			}
		}
		return list;
	}

	private bool Wander()
	{
		List<Ledge> list = Spots();
		if (list.Count == 0)
		{
			return false;
		}
		Ledge spot = list[random.Next(list.Count)];
		int num = preferences.Size / 4;
		int x = spot.Left + num + random.Next(Math.Max(1, spot.Right - spot.Left - 2 * num));
		GlitchOut(() =>
		{
			Hop(spot, x);
		}, everywhere: false);
		return seat == spot;
	}

	private void Hop(Ledge spot, int x)
	{
		lying = false;
		hanging = false;
		walking = false;
		seat = null;
		anchor = Seated(x, spot.Y);
		Land(spot, arriving: true);
		if (seat != spot)
		{
			anchor = KeepOnScreen(anchor);
			Play(arrive);
			dropAfter = true;
		}
		Static(everywhere: false, null);
		frames.Start();
	}

