	private bool? LieWay()
	{
		if (seat == null || seat.Free || !seat.Icon.IsEmpty || riding || onPanel || walking || falling || hanging || dragging || hidden)
		{
			return null;
		}
		Point point = Hip();
		Rectangle workingArea = Screen.FromPoint(point).WorkingArea;
		int num = (int)Math.Ceiling((float)preferences.Size * 0.45f);
		int num2 = (int)Math.Ceiling((float)preferences.Size * 0.78f);
		bool flag = point.X - seat.Left >= num && point.X - num2 >= workingArea.Left;
		bool flag2 = seat.Right - point.X >= num && point.X + num2 <= workingArea.Right;
		if (facingLeft ? flag2 : flag)
		{
			return facingLeft;
		}
		if (facingLeft ? flag : flag2)
		{
			return !facingLeft;
		}
		return null;
	}

	private bool LieDown()
	{
		bool? flag = LieWay();
		if (lying || !flag.HasValue || clip != perch)
		{
			return false;
		}
		Point point = Hip();
		facingLeft = flag.Value;
		lying = true;
		nextLie = -1.0;
		anchor = Seated(point.X, seat.Y);
		Location = anchor;
		laydown.Load(facingLeft);
		laydownGlitch.Load(facingLeft);
		WarmLie();
		Play(preferences.Motion ? laydownGlitch : laydown);
		Static(everywhere: false, null);
		frames.Start();
		return true;
	}

	private void SitUp(bool glitched = true)
	{
		if (lying)
		{
			Point point = Hip();
			lying = false;
			nextLie = -1.0;
			anchor = new Point(anchor.X + point.X - Hip().X, anchor.Y);
			Location = anchor;
			if (glitched && seat != null)
			{
				Play(preferences.Motion ? perchGlitch : perch);
				frames.Start();
			}
		}
	}

	private void WarmLie()
	{
		laydown.Warm(facingLeft);
		laydownBlink.Warm(facingLeft);
		laydownBlinkGlitch.Warm(facingLeft);
		laydownGlitch.Warm(facingLeft);
		if (TalkingNow || talkState != TalkState.Off || chatting)
		{
			laydownTalk.Warm(facingLeft);
		}
	}

	private void CheckLie(double now)
	{
		if (lieBy >= 0.0)
		{
			if (now > lieBy || lying || dragging || riding || hanging || hidden)
			{
				lieBy = -1.0;
			}
			else if (clip == perch && SittingStill)
			{
