			}
		}
		bool flag = preferences.Motion && !preferences.NoSitting && !hidden && !dragging && !pressed && !chatting && !typer.Visible && !menu.Visible && !napAsked && !napping && !musicOn && !danceAsked && working == null && outro == null && Quiet(now);
		if (lying)
		{
			if (clip == laydown)
			{
				if (nextLie < 0.0)
				{
					nextLie = now + 180.0 + random.NextDouble() * 300.0;
				}
				if (now >= nextLie && flag)
				{
					SitUp();
				}
			}
		}
		else if (!flag || clip != perch || !SittingStill || seat.Free || !seat.Icon.IsEmpty)
		{
			nextLie = -1.0;
		}
		else
		{
			if (nextLie < 0.0)
			{
				nextLie = now + 120.0 + random.NextDouble() * 180.0;
			}
			if (!(now < nextLie))
			{
				nextLie = -1.0;
				LieDown();
			}
		}
	}

	private void Tumble(double now)
	{
		double num = Math.Max(0.0, Math.Min(0.05, now - fallStep));
		fallStep = now;
		Point hip = Hip();
		if (fallTo == null)
		{
			fallTo = Ledges.Below(Around(), hip, 0, int.MaxValue, 0, Headroom());
		}
		if (fallTo == null)
		{
			falling = false;
			SavePreferences();
			return;
		}
		if (flyVX != 0.0 || fallSpeed < 0.0)
		{
			Fly(num);
			hip = Hip();
			fallTo = fallSpeed < 0.0 ? null : Ledges.Below(Around(), hip, 0, int.MaxValue, 0, Headroom());
			if (fallSpeed < 0.0)
			{
				fallSpeed += (double)(preferences.Size * 11) * num;
				anchor.Y += (int)Math.Floor(fallSpeed * num);
				Point kept = KeepOnScreen(anchor);
				if (kept.Y > anchor.Y)
				{
					fallSpeed = 0.0;
				}
				anchor = kept;
				return;
			}
			if (fallTo == null)
			{
				flyVX = 0.0;
				leanAngle = 0.0;
				falling = false;
				SavePreferences();
				return;
			}
		}
		fallSpeed += (double)(preferences.Size * 11) * num;
		int num2 = (int)Math.Ceiling(fallSpeed * num);
		if (hip.Y + num2 >= fallTo.Y)
		{
			Land(fallTo);
		}
		else
		{
			anchor.Y += num2;
		}
	}

	private bool Zappy => !instant && !hidden && preferences.Motion && IsHandleCreated;

	private Rectangle ZapBody()
	{
		return BodyOnScreen(anchor, (seat != null || riding || onPanel) ? PerchedBody : Body);
	}

	// her anime lightning bursting off her, with a crackle
	private void Zap(double power, bool ground, Cue? sound)
	{
		if (Zappy)
		{
			crackle.Burst(ZapBody(), (float)preferences.Size / 240f, power, ground);
			if (sound.HasValue)
			{
				Sfx.Play(sound.Value);
			}
		}
	}

	// little arcs trailing behind her while she flies or swings fast
	private void ZapTrail(double now, double vx, double vy)
	{
		if (Zappy && now - zapAt >= 0.06)
		{
			zapAt = now;
			crackle.Trail(ZapBody(), (float)preferences.Size / 240f, Math.Atan2(-vy, -vx));
		}
	}

	// while held she hangs from the cursor like a pendulum: moving the hand pushes her body the other way,
	// and she overshoots and settles back when the hand stops
	private void Swing(double now)
	{
		double dt = Math.Max(0.005, Math.Min(0.05, now - dragStep));
		dragStep = now;
		double vx = (double)(anchor.X - dragLast.X) / dt;
		double vy = (double)(anchor.Y - dragLast.Y) / dt;
		dragLast = anchor;
		double prevVX = dragVX;
		dragVX = dragVX * 0.55 + vx * 0.45;
		dragVY = dragVY * 0.55 + vy * 0.45;
		double push = Math.Max(-4000.0, Math.Min(4000.0, (dragVX - prevVX) / dt)) * 0.012;
		double target = Math.Max(-30.0, Math.Min(30.0, dragVX * 0.018));
		swingSpeed += ((target - leanAngle) * 55.0 - swingSpeed * 3.2 + push) * dt;
		leanAngle = Math.Max(-38.0, Math.Min(38.0, leanAngle + swingSpeed * dt));
		if (dragVX * dragVX + dragVY * dragVY > 1100.0 * 1100.0)
		{
			ZapTrail(now, dragVX, dragVY);
		}
	}

	// a fast release flings her: she flies with the hand's speed, bounces off the screen sides, then falls onto a ledge
	private bool Throw()
	{
		double speed = Math.Sqrt(dragVX * dragVX + dragVY * dragVY);
		if (preferences.NoSitting || onPanel || speed < 650.0)
		{
			return false;
		}
		double scale = Math.Min(1.0, 3600.0 / speed);
		flyVX = dragVX * scale;
		if (Math.Abs(flyVX) < 1.0)
		{
			flyVX = 1.0 * Math.Sign(dragVX + 0.5);
		}
		falling = true;
		fallTo = null;
		fallSpeed = dragVY * scale;
		fallStep = clock.Elapsed.TotalSeconds;
		Zap(speed / 3600.0, ground: false, Cue.Zap);
		preferences.Throws++;
		SavePreferences();
		frames.Start();
		return true;
	}

	private void Fly(double dt)
	{
		flyVX *= Math.Pow(0.55, dt);
		int nx = anchor.X + (int)Math.Round(flyVX * dt);
		Point kept = KeepOnScreen(new Point(nx, anchor.Y));
		if (kept.X != nx)
		{
			flyVX = -flyVX * 0.5;
			swingSpeed += flyVX * 0.08;
			Zap(0.35, ground: false, Cue.Spark);
		}
		anchor.X = kept.X;
		if (Math.Abs(flyVX) < 20.0)
		{
			flyVX = 0.0;
		}
		// spin with the flight, then ease upright as it slows
		double target = Math.Max(-35.0, Math.Min(35.0, flyVX * 0.015));
		swingSpeed += ((target - leanAngle) * 40.0 - swingSpeed * 2.5) * dt;
		leanAngle = Math.Max(-45.0, Math.Min(45.0, leanAngle + swingSpeed * dt));
		ZapTrail(clock.Elapsed.TotalSeconds, flyVX, fallSpeed);
	}

	private void Land(Ledge ledge, bool arriving = false)
	{
		double impact = falling ? fallSpeed / (double)Math.Max(1, preferences.Size * 9) : 0.0;
		SitUp(glitched: false);
		fallTo = null;
		walking = false;
		flyVX = 0.0;
		if (ledge.Window != IntPtr.Zero)
		{
			if (!Ledges.Showing(ledge.Window, out var bounds) || !Ledges.Seatable(ledge.Window, bounds))
			{
				return;
			}
			if (bounds != ledge.Bounds)
			{
				ledge.Left = bounds.Left;
				ledge.Right = bounds.Right;
				ledge.Y = bounds.Top;
				ledge.Bounds = bounds;
			}
		}
		falling = false;
		coveredSince = -1.0;
		seatLost = -1.0;
		int val = (ledge.Icon.IsEmpty ? Math.Max(ledge.Left + 8, Math.Min(Hip().X, ledge.Right - 8)) : (ledge.Icon.Left + ledge.Icon.Width / 2));
		Rectangle workingArea = Screen.FromPoint(new Point(val, ledge.Y - 1)).WorkingArea;
		int num = workingArea.Right - (int)Math.Ceiling((float)preferences.Size * (PerchedBody.Right - SitX));
		if (ledge.Icon.IsEmpty && ledge.Right >= workingArea.Right - 8 && BodyOnScreen(anchor, Body).Right >= workingArea.Right - 2)
		{
			val = num;
		}
		val = Math.Max(workingArea.Left + (int)Math.Ceiling((float)preferences.Size * (SitX - PerchedBody.Left)), Math.Min(val, num));
		seat = ledge;
		leanAngle = 0.0;
		anchor = Seated(val, ledge.Y);
		Play((arriving && preferences.Motion && !instant) ? perchArrive : perchGlitch);
		if (!arriving && impact > 0.25)
		{
			Zap(impact, ground: true, (impact > 0.6) ? Cue.Zap : Cue.Spark);
		}
		SavePreferences();
	}

	private void HoldSeat(double now)
	{
		if (seat.Window == IntPtr.Zero)
		{
			return;
		}
		if (!Ledges.Showing(seat.Window, out var bounds) || !Ledges.Seatable(seat.Window, bounds))
		{
			if (seatLost < 0.0)
			{
				seatLost = now;
			}
			if (!Ledges.Alive(seat.Window) || now - seatLost >= 0.3)
			{
				StandUp();
			}
			return;
		}
		seatLost = -1.0;
		if (!(bounds == seat.Bounds))
		{
			int num = ((bounds.Width == seat.Bounds.Width) ? (bounds.Left - seat.Bounds.Left) : 0);
			int num2 = Math.Max(bounds.Left + 8, Math.Min(Hip().X + num, bounds.Right - 8));
			seat.Bounds = bounds;
			seat.Left = bounds.Left;
			seat.Right = bounds.Right;
			seat.Y = bounds.Top;
			if (!walking)
			{
				anchor = Seated(num2, bounds.Top);
				return;
			}
			int num3 = anchor.X;
			anchor = Standing(num2, bounds.Top);
			walkTo += anchor.X - num3;
			int val = Standing(bounds.Right - (int)((float)preferences.Size * 0.41f) - 8, bounds.Top).X;
			walkTo = Math.Max(Standing(bounds.Left + (int)((float)preferences.Size * 0.1f) + 8, bounds.Top).X, Math.Min(walkTo, val));
		}
	}

	private void CheckSeat(double now)
	{
		if (seat == null || falling || seat.Floor)
		{
			return;
		}
		if (!seat.Icon.IsEmpty && now - iconsAt > 2.0)
		{
			RefreshIcons();
		}
		if (!Ledges.Covered(seat, Hip().X, Skip()))
		{
			coveredSince = -1.0;
			return;
		}
		if (coveredSince < 0.0)
		{
			coveredSince = now;
		}
		if (now - coveredSince >= 0.7)
		{
			StandUp();
		}
	}

	private void RefreshIcons()
	{
		if (iconsBusy)
		{
			return;
		}
		iconsBusy = true;
		ThreadPool.QueueUserWorkItem((object param0) =>
		{
			List<Rectangle> found;
			try
			{
				found = Ledges.Icons();
			}
			catch
			{
				found = new List<Rectangle>();
			}
			Post(() =>
			{
				iconsBusy = false;
				icons = found;
				iconsAt = clock.Elapsed.TotalSeconds;
				if (seat != null && !seat.Icon.IsEmpty && !falling && !found.Contains(seat.Icon))
				{
					StandUp();
				}
			});
		});
	}

	internal void ToggleSitting()
	{
		preferences.NoSitting = !preferences.NoSitting;
		sitItem.Checked = !preferences.NoSitting;
		if (preferences.NoSitting && (seat != null || falling))
		{
			SitUp(glitched: false);
			seat = null;
			falling = false;
			walking = false;
			Play(idle);
			UpdateAnimation();
		}
		SavePreferences();
	}

	private void React()
	{
		if (hanging)
		{
			LetGo();
			return;
		}
		EndWalk();
		clicks++;
		napAsked = false;
		if (clip == sleep)
		{
			napping = false;
			Play(wake);
			if (!hidden)
			{
				frames.Start();
			}
			RenderFrame();
		}
		else if (clip == laydownSleep)
		{
			napping = false;
			Play(laydown);
			if (!hidden)
			{
				frames.Start();
			}
			RenderFrame();
		}
		else
		{
			Companion companion = this;
			Clip next;
			if (lying)
			{
				next = laydownGlitch;
			}
			else
			{
				next = ((seat != null || onPanel) ? perchGlitch : glitch);
			}
			companion.Play(next);
			if (!hidden)
			{
				frames.Start();
			}
			RenderFrame();
		}
	}

	private void SetHidden(bool value)
	{
		if (value && !hidden)
		{
			GlitchOut(() =>
			{
				ShowHidden(value: true);
			});
		}
		else
		{
			ShowHidden(value);
		}
	}

	private void ShowHidden(bool value)
	{
		if (!quitting)
		{
			outro = null;
			hidden = value;
			visibilityItem.Text = (value ? "Show Capri" : "Hide Capri");
			if (value)
			{
				SitUp(glitched: false);
				StopRide();
				LeavePanel(home: true);
				seat = null;
				falling = false;
				hanging = false;
				walking = false;
				dropAfter = false;
				pendingClick = false;
				clickDelay.Stop();
				frames.Stop();
				Hide();
				pill.Hide();
				typer.Hide();
				box.Hide();
				if (!hideKeepsEars)
				{
					CloseTalk();
					StopChat();
				}
			}
			else
			{
				anchor = KeepOnScreen(anchor);
				Location = anchor;
				Play((instant || !preferences.Motion) ? grin : arrive);
				Show();
				RenderFrame();
				UpdateAnimation();
				Static(everywhere: true, Cue.Arrive);
				if (chatting)
				{
					pill.SetChat(on: true, micMuted: ears.Muted);
				}
			}
			hideKeepsEars = false;
			mainframe.Sync();
		}
	}

	private void RestoreAtCursor()
	{
		StopRide();
		LeavePanel(home: false);
		seat = null;
		falling = false;
		walking = false;
		Rectangle workingArea = Screen.FromPoint(Cursor.Position).WorkingArea;
		anchor = new Point(workingArea.Right - Width - 28, workingArea.Bottom - Height - 12);
		ShowHidden(value: false);
		DropSoon();
	}

