		SavePreferences();
		mainframe.Sync();
		if (voice.Key != null && !hidden && !IsDisposed)
		{
			heard = "settings";
			box.Prompt = "> sys: ";
			Companion companion = this;
			int ticket = ++asking;
			string said;
			if (preferences.Quiet)
			{
				said = ((FreeChatOn && !testing && kokoro.Installed) ? "ElevenLabs off. Free voice it is." : "ElevenLabs off. I'll type, no credits used.");
			}
			else
			{
				said = "ElevenLabs back on.";
