	internal void Silence()
	{
		if (!preferences.Silent)
		{
			preferences.Silent = true;
			voice.Stop();
			qwen.Stop();
			if (chatting && !local)
			{
				StopChat();
			}
			SavePreferences();
			mainframe.Sync();
			ShowVoice();
			if (!hidden && !IsDisposed)
			{
				heard = "settings";
				box.Prompt = "> sys: ";
				Answer(++asking, "Voice off. I'll type instead.", TalkState.Talking, quiet: true);
