	internal void ChooseVoiceTier(bool paid)
	{
		if (paid && preferences.CloudVoice != "ElevenLabs")
		{
			preferences.CloudVoice = "ElevenLabs";
			SavePreferences();
		}
		bool silent = preferences.Silent;
		preferences.Silent = false;
		if (silent)
		{
			preferences.Quiet = !paid;
			SavePreferences();
			if (!paid)
			{
				GetFreeVoice();
			}
			if (!hidden && !IsDisposed && (!paid || voice.Key != null))
			{
				heard = "settings";
				box.Prompt = "> sys: ";
				Answer(++asking, "Voice back on.", TalkState.Talking);
			}
		}
		else if (voice.Key != null && paid == preferences.Quiet)
		{
			ToggleSpeaking();
		}
		else if (paid && preferences.Quiet)
		{
			preferences.Quiet = false;
			SavePreferences();
		}
		mainframe.Sync();
		ShowVoice();
		if (paid && voice.Key == null)
		{
			mainframe.VoiceNote("Paste your ElevenLabs key, then press Connect.", problem: false);
		}
	}

	private void CheckSlow(double now)
	{
		if (slowWarned || working != null || talkState != TalkState.Thinking || (chatting && !local) || double.IsNaN(thinkingSince))
		{
			return;
		}
		Cloud remote = brain.Remote;
		if ((remote == null && localWarned) || now - thinkingSince < (double)((remote != null) ? 8 : 25))
		{
			return;
		}
		slowWarned = true;
		if (remote != null)
		{
			mainframe.ShowProblem("Waiting for " + remote.Company + ". You can pick another model.");
			UpdateTalk(now);
			return;
		}
		localWarned = true;
		mainframe.ShowProblem("Slow? Press Free key for a free NVIDIA key.");
		UpdateTalk(now);
		if (!testing)
		{
			balloonPage = "https://build.nvidia.com/settings/api-keys";
			balloonUpdate = false;
			balloonMainframe = false;
			tray.ShowBalloonTip(15000, "Capri is replying slowly", "Her brain runs on your PC, and open games share that power. For fast replies, click here, make a free NVIDIA key, then paste it in Capri Mainframe under BRAIN and press Connect.", ToolTipIcon.Info);
		}
	}

