		watchTicket++;
		nextGlance = -1.0;
		lastGlance = -1.0;
		lastPrint = null;
		SavePreferences();
		mainframe.Sync();
		if (!preferences.Watch)
		{
			return;
		}
		Cloud remote = brain.Remote;
		Engine engine = brain.Local;
		Pick localPick = brain.LocalPick;
		if (remote != null && remote.Kind == "deepseek")
		{
			mainframe.ShowProblem("DeepSeek can't see. Use an NVIDIA key to watch.");
		}
		else if (remote == null && engine != null && localPick != null)
		{
			if (localPick.EyesFile == null)
			{
				mainframe.ShowProblem("This brain can't see. Press Free key to fix.");
