	private string Unseeing()
	{
		Cloud remote = brain.Remote;
		if (remote != null)
		{
			if (!(remote.Kind == "deepseek"))
			{
				if (!(remote.Model == brain.Unsighted))
				{
					return null;
				}
				return Brain.Sightless(remote);
			}
			return "DeepSeek can't see your screen. In Capri Mainframe, press Free key and connect a free NVIDIA key instead.";
		}
		if (brain.Model == null)
		{
			return "You can't see their screen: your brain is offline.";
		}
		Engine engine = brain.Local;
		Pick localPick = brain.LocalPick;
		if (engine == null || localPick == null)
		{
			return null;
		}
		if (localPick.EyesFile == null)
		{
			return "Your brain can't see. Tell them to press Free key in Capri Mainframe and connect a free NVIDIA key so you can.";
		}
		if (engine.HasEyes(localPick))
		{
			return null;
		}
		FetchEyes(engine, localPick);
		return "Your eyes are still downloading, so you can't see their screen yet.";
	}

	private void FetchEyes(Engine local, Pick pick)
	{
		if (fetchingEyes)
		{
			return;
		}
		fetchingEyes = true;
		ThreadPool.QueueUserWorkItem((object param0) =>
		{
			string problem = null;
			try
			{
				local.InstallEyes(pick, (string label, long have, long size) =>
				{
					Post(() =>
					{
						mainframe.ShowProblem(label + " " + have * 100 / Math.Max(1L, size) + "%");
					});
				});
			}
			catch (Exception ex)
			{
				problem = ex.Message;
			}
			fetchingEyes = false;
			Post(() =>
			{
				if (brain.Local == local)
				{
					mainframe.ShowProblem(problem ?? "Her eyes are in. She can see your screen now.");
				}
			});
		});
	}

	private string LookAt(string focus)
	{
		string text = Unseeing();
		if (text != null)
		{
			return text;
		}
		byte[] jpeg;
		using (Bitmap bitmap = (InvokeRequired ? ((Bitmap)Invoke(new Func<Bitmap>(CaptureScreen))) : CaptureScreen()))
		{
			if (bitmap == null)
			{
				return "The screen capture is black. Try borderless or windowed mode.";
			}
			jpeg = Jpeg(bitmap, 1280);
		}
		string text2;
		try
		{
			text2 = brain.See(jpeg, "You describe screenshots accurately and briefly.", "Describe what's on this screen in two or three plain sentences: what kind of game or app it is (name it only if the name is on screen), what's happening, and any text or numbers that matter. Don't guess who a person is from their face; name someone only if their name is written on screen." + (string.IsNullOrWhiteSpace(focus) ? "" : (" Pay attention to: " + focus.Trim())), 160);
		}
		catch (BrainException)
		{
			string text3 = Unseeing();
			if (text3 == null)
			{
				throw;
			}
			return text3;
		}
		if (text2.Length == 0)
		{
			return "You looked but couldn't make out their screen.";
		}
		brain.Saw(text2, null, asked: true);
		return "You looked at their screen. You see: " + text2;
	}

	private double nextEyePopup = -1.0;

	private readonly List<EyePopup> eyePopups = new List<EyePopup>();

	// gap between eyes per pace (Rarely, Sometimes, Often, Swarm): base seconds and random spread
	private static readonly double[,] EyePaces = { { 60.0, 90.0 }, { 25.0, 50.0 }, { 10.0, 20.0 }, { 3.0, 7.0 } };

	// eye size per setting (Small, Medium, Large); Mixed rolls one each time
	private static readonly float[] EyeScales = { 0.65f, 1f, 1.4f };

	// petting feel: { swing px, turns needed, max ms between turns } for Gentle / Normal / Easy
	private static readonly int[,] PetFeels = { { 45, 8, 600 }, { 30, 6, 700 }, { 20, 4, 900 } };

