	// an eye peeks in at the chosen pace; one time in five a small staggered cluster, up to the chosen most at once
	private void CheckEyePopup(double now)
	{
		eyePopups.RemoveAll((EyePopup eye) => eye.IsDisposed);
		if (!preferences.EyePopups || hidden || Hushed || quitting || dragging || PlayingGame)
		{
			return;
		}
		if (nextEyePopup < 0.0)
		{
			nextEyePopup = now + Math.Min(20.0, EyePaces[Math.Clamp(preferences.EyePace, 0, 3), 0]);
		}
		if (now < nextEyePopup)
		{
			return;
		}
		int pace = Math.Clamp(preferences.EyePace, 0, 3);
		int most = Math.Clamp(preferences.EyeMost, 0, 4) + 1;
		nextEyePopup = now + EyePaces[pace, 0] + random.NextDouble() * EyePaces[pace, 1];
		int count = (random.NextDouble() < 0.2) ? (2 + random.Next(2)) : 1;
		for (int i = 0; i < count && eyePopups.Count < most; i++)
		{
			int size = Math.Clamp(preferences.EyeSize, 0, 3);
			float scale = size < 3 ? EyeScales[size] : 0.55f + (float)random.NextDouble();
			EyePopup eye = new EyePopup(eyePopups.ConvertAll((EyePopup other) => other.Bounds), i * random.Next(250, 700), scale);
			eyePopups.Add(eye);
			eye.Show();
		}
	}

	private void CheckGlance(double now, long quiet)
	{
		if (!preferences.Watch || glancing || Hushed)
		{
			return;
		}
		if (nextGlance < 0.0)
		{
			nextGlance = now + (double)Math.Min(20, GlanceGap);
		}
		if (now < nextGlance || quiet > 600000 || brain.Model == null || hidden || MicOpen || PlayingGame || dragging || typer.Visible || talkState != TalkState.Off)
		{
			return;
		}
		nextGlance = now + (double)GlanceGap * (0.8 + random.NextDouble() * 0.4);
		if (Unseeing() != null)
		{
			return;
		}
		byte[] shot;
		try
		{
			using Bitmap bitmap = CaptureScreen();
			if (bitmap == null)
			{
				lastPrint = null;
				mainframe.ShowProblem("The screen capture is black. Try borderless or windowed mode.");
				return;
			}
			if (!Changed(bitmap, lastGlance < 0.0 || now - lastGlance >= 300.0))
			{
				return;
			}
			shot = Jpeg(bitmap, 1280);
		}
		catch (Exception)
		{
			lastPrint = null;
			mainframe.ShowProblem("Couldn't capture the screen. I'll try again.");
			return;
		}
		glancing = true;
		lastGlance = now;
		int ticket = asking;
		int watch = watchTicket;
		string ask = Glances.Ask(RecentGlances(clock.Elapsed.TotalSeconds));
		ThreadPool.QueueUserWorkItem((object param0) =>
		{
			string said = null;
			string saw = null;
			string problem = null;
			try
			{
				said = Glances.Reply(brain.See(shot, Brain.Persona + Brain.Speech(), ask, 140), out saw);
			}
			catch (Exception ex2)
			{
				if (!(ex2 is WebException { Status: WebExceptionStatus.RequestCanceled }))
				{
					problem = "Couldn't read the screen. I'll try again.";
					Brain.Log("glance", -1L, ex2.GetType().Name + ": " + ex2.Message);
				}
			}
			Post(() =>
			{
				FinishGlance(ticket, watch, said, problem, saw);
			});
		});
	}

	private void FinishGlance(int ticket, int watch, string said, string problem, string saw = null)
	{
		glancing = false;
		if (preferences.Watch && watch == watchTicket)
		{
			string text = Unseeing();
			if (text != null || problem != null)
			{
				lastPrint = null;
				mainframe.ShowProblem(text ?? problem);
				return;
			}
			if (string.IsNullOrEmpty(said))
			{
				Glimpsed(saw);
				return;
			}
			if (ticket != asking || talkState != TalkState.Off || typer.Visible || MicOpen || PlayingGame || Hushed || hidden || dragging)
			{
				lastPrint = null;
				Glimpsed(saw);
				return;
			}
			if (Glances.Repeats(said, RecentGlances(clock.Elapsed.TotalSeconds), Brain.Nickname))
			{
				Glimpsed(saw);
				return;
			}
			glanced.Add(Tuple.Create(clock.Elapsed.TotalSeconds, said));
			brain.Saw(saw, said);
			brain.Remember(string.IsNullOrEmpty(saw) ? "(You glanced at their screen.)" : ("(You glanced at their screen and saw: " + saw + ")"), said);
			Remark("watching", said);
		}
	}

	private void Glimpsed(string saw)
	{
		if (preferences.CaughtUp)
		{
			brain.Saw(saw, null);
		}
	}

	private List<string> RecentGlances(double now)
	{
		glanced.RemoveAll((Tuple<double, string> line) => now - line.Item1 > 3600.0 || now < line.Item1);
		if (glanced.Count > 30)
		{
			glanced.RemoveRange(0, glanced.Count - 30);
		}
		return glanced.ConvertAll((Tuple<double, string> line) => line.Item2);
	}

	private bool Changed(Bitmap screen, bool force = false)
	{
		byte[] array = new byte[6912];
		using (Bitmap bitmap = new Bitmap(64, 36, PixelFormat.Format24bppRgb))
		{
			using (Graphics graphics = Graphics.FromImage(bitmap))
			{
				graphics.InterpolationMode = InterpolationMode.HighQualityBilinear;
				graphics.DrawImage(screen, 0, 0, 64, 36);
			}
			for (int i = 0; i < 36; i++)
			{
				for (int j = 0; j < 64; j++)
				{
					Color pixel = bitmap.GetPixel(j, i);
					int num = (i * 64 + j) * 3;
					array[num] = pixel.R;
					array[num + 1] = pixel.G;
					array[num + 2] = pixel.B;
				}
			}
		}
		if (!force && !Glances.Moved(array, lastPrint))
		{
			return false;
		}
		lastPrint = array;
		return true;
	}

	private Bitmap CaptureScreen()
	{
		return CaptureScreen(CaptureArea(Native.GetForegroundWindow()));
	}

	private static Rectangle CaptureArea(IntPtr window)
	{
		return Display((window != IntPtr.Zero && Control.FromHandle(window) == null) ? window : IntPtr.Zero);
	}

	private Bitmap CaptureScreen(Rectangle area)
	{
		if (area != lastArea)
		{
			lastArea = area;
			lastPrint = null;
			lastGlance = -1.0;
		}
		Bitmap bitmap = OwnGrab(area);
		try
		{
			if (Black(bitmap))
			{
				bitmap.Dispose();
				return null;
			}
			PaintOut(bitmap, area);
			if (Black(bitmap))
			{
				bitmap.Dispose();
				return null;
			}
			return bitmap;
		}
		catch
		{
			bitmap.Dispose();
			throw;
		}
	}

	private void PaintOut(Bitmap shot, Rectangle area)
	{
		Bitmap bitmap = frame;
		if (bitmap != null && !hidden)
		{
			Smear(shot, bitmap, anchor.X - area.X, anchor.Y - area.Y, bitmap.Width, bitmap.Height);
		}
		if (box.Visible)
		{
			Smear(shot, null, box.Left - area.X, box.Top - area.Y, box.Width, box.Height);
		}
		if (pill.Visible)
		{
			Smear(shot, null, pill.Left - area.X, pill.Top - area.Y, pill.Width, pill.Height);
		}
		Bitmap image = herPointer.Image;
		if (herPointer.Visible && image != null)
		{
			Smear(shot, image, herPointer.Left - area.X, herPointer.Top - area.Y, image.Width, image.Height);
		}
	}

	private Bitmap HandsGrab(Rectangle area)
	{
		Bitmap shot = OwnGrab(area);
		if (!InvokeRequired)
		{
			PaintOut(shot, area);
			return shot;
		}
		try
		{
			IAsyncResult asyncResult = BeginInvoke((Action)(() =>
			{
				PaintOut(shot, area);
			}));
			if (!asyncResult.AsyncWaitHandle.WaitOne(3000))
			{
				return Grab(area);
			}
			EndInvoke(asyncResult);
		}
		catch (InvalidOperationException)
		{
		}
		return shot;
	}

	private Bitmap OwnGrab(Rectangle area)
	{
		bool flag = PanelUnseen(unseen: true);
		try
		{
			if (flag)
			{
				Thread.Sleep(50);
			}
			return Grab(area);
		}
		finally
		{
			PanelUnseen(unseen: false);
		}
	}

	private bool PanelUnseen(bool unseen)
	{
		if (!InvokeRequired)
		{
			return taskPanel.Unseen(unseen) | player.Unseen(unseen);
		}
		try
		{
			IAsyncResult asyncResult = BeginInvoke((Func<bool>)(() => taskPanel.Unseen(unseen) | player.Unseen(unseen)));
			return unseen && asyncResult.AsyncWaitHandle.WaitOne(1000) && (bool)EndInvoke(asyncResult);
		}
		catch (InvalidOperationException)
		{
			return false;
		}
	}

	private static bool Black(Bitmap shot)
	{
		BitmapData bitmapData = shot.LockBits(new Rectangle(0, 0, shot.Width, shot.Height), ImageLockMode.ReadOnly, PixelFormat.Format24bppRgb);
		try
		{
			byte[] array = new byte[shot.Width * 3];
			for (int i = 0; i < shot.Height; i++)
			{
				Marshal.Copy(bitmapData.Scan0 + i * bitmapData.Stride, array, 0, array.Length);
				byte[] array2 = array;
				for (int j = 0; j < array2.Length; j++)
				{
					if (array2[j] != 0)
					{
						return false;
					}
				}
			}
			return true;
		}
		finally
		{
			shot.UnlockBits(bitmapData);
		}
	}

	internal static void Smear(Bitmap shot, Bitmap mask, int left, int top, int width, int height)
	{
		Rectangle rectangle = Rectangle.Intersect(new Rectangle(left, top, width, height), new Rectangle(0, 0, shot.Width, shot.Height));
		if (rectangle.IsEmpty)
		{
			return;
		}
		BitmapData bitmapData = shot.LockBits(new Rectangle(0, 0, shot.Width, shot.Height), ImageLockMode.ReadWrite, PixelFormat.Format24bppRgb);
		BitmapData bitmapData2 = mask?.LockBits(new Rectangle(0, 0, mask.Width, mask.Height), ImageLockMode.ReadOnly, PixelFormat.Format32bppArgb);
		try
		{
			byte[] array = new byte[bitmapData.Stride];
			byte[] array2 = ((bitmapData2 == null) ? null : new byte[bitmapData2.Stride]);
			for (int i = rectangle.Top; i < rectangle.Bottom; i++)
			{
				IntPtr intPtr = bitmapData.Scan0 + i * bitmapData.Stride;
				Marshal.Copy(intPtr, array, 0, array.Length);
				if (bitmapData2 != null)
				{
					Marshal.Copy(bitmapData2.Scan0 + (i - top) * bitmapData2.Stride, array2, 0, array2.Length);
				}
				int j = rectangle.Left;
				while (j < rectangle.Right)
				{
					if (bitmapData2 != null && array2[(j - left) * 4 + 3] <= 8)
					{
						j++;
						continue;
					}
					int num = j;
					for (; j < rectangle.Right && (bitmapData2 == null || array2[(j - left) * 4 + 3] > 8); j++)
					{
					}
					int num2 = num - 1;
					int num3 = j;
					for (int k = num; k < num3; k++)
					{
						double num4 = (double)(k - num2) / (double)(num3 - num2);
						for (int l = 0; l < 3; l++)
						{
							int num5;
							if (num2 >= 0)
							{
								num5 = array[num2 * 3 + l];
							}
							else
							{
								num5 = ((num3 < shot.Width) ? array[num3 * 3 + l] : 128);
							}
							int num6 = ((num3 < shot.Width) ? array[num3 * 3 + l] : num5);
							array[k * 3 + l] = (byte)((double)num5 + (double)(num6 - num5) * num4);
						}
					}
				}
				Marshal.Copy(array, 0, intPtr, array.Length);
			}
		}
		finally
		{
			shot.UnlockBits(bitmapData);
			if (bitmapData2 != null)
			{
				mask.UnlockBits(bitmapData2);
			}
		}
	}

	private static bool ShownCopy(Graphics graphics, Point from, Point to, Size size)
	{
		try
		{
			graphics.CopyFromScreen(from, to, size);
			return true;
		}
		catch (Win32Exception)
		{
			return false;
		}
	}

	private static void Snapped(Graphics sheet, Control window, int x, int y)
	{
		using Bitmap bitmap = new Bitmap(window.Width, window.Height);
		window.DrawToBitmap(bitmap, new Rectangle(Point.Empty, window.Size));
		if (window.Region != null)
		{
			using Region region = window.Region.Clone();
			region.Translate(x, y);
			sheet.SetClip(region, CombineMode.Replace);
		}
		sheet.DrawImageUnscaled(bitmap, x, y);
		sheet.ResetClip();
	}

	private static Bitmap GrabScreen(Rectangle area)
	{
		Bitmap bitmap = new Bitmap(area.Width, area.Height, PixelFormat.Format24bppRgb);
		try
		{
			using (Graphics graphics = Graphics.FromImage(bitmap))
			{
				graphics.CopyFromScreen(area.Location, Point.Empty, area.Size);
			}
			return bitmap;
		}
		catch
		{
			bitmap.Dispose();
			throw;
		}
	}

	internal static byte[] Jpeg(Bitmap picture, int longest)
	{
		double num = Math.Min(1.0, (double)longest / (double)Math.Max(picture.Width, picture.Height));
		int num2 = Math.Max(1, (int)Math.Round((double)picture.Width * num));
		int num3 = Math.Max(1, (int)Math.Round((double)picture.Height * num));
		using Bitmap bitmap = new Bitmap(num2, num3, PixelFormat.Format24bppRgb);
		using (Graphics graphics = Graphics.FromImage(bitmap))
		{
			graphics.InterpolationMode = InterpolationMode.HighQualityBicubic;
			graphics.DrawImage(picture, 0, 0, num2, num3);
		}
		ImageCodecInfo encoder = Array.Find(ImageCodecInfo.GetImageEncoders(), (ImageCodecInfo found) => found.FormatID == ImageFormat.Jpeg.Guid);
		using EncoderParameters encoderParameters = new EncoderParameters(1);
		using MemoryStream memoryStream = new MemoryStream();
		encoderParameters.Param[0] = new EncoderParameter(System.Drawing.Imaging.Encoder.Quality, 80L);
		bitmap.Save(memoryStream, encoder, encoderParameters);
		return memoryStream.ToArray();
	}

