	internal void FindBrain()
	{
		Cloud remote = brain.Remote;
		if (remote != null)
		{
			brain.Local = null;
			if (remote.Model != null)
			{
				brain.Model = remote.Model;
				mainframe.ShowCloud(remote, cloudModels);
			}
			ListCloud(remote.Key, connecting: false);
		}
		else
		{
			if (finding || SettingUp)
			{
				return;
			}
			finding = true;
			mainframe.Searching();
			ThreadPool.QueueUserWorkItem((object param0) =>
			{
				string[] installed = null;
				try
				{
					installed = Brain.InstalledModels();
				}
				catch (WebException)
				{
				}
				catch (IOException)
				{
				}
				catch (SerializationException)
				{
				}
				Machine found = Machine.Read();
				Pick local = engine.Installed();
				Post(() =>
				{
					finding = false;
					UseBrain(installed, found, local);
				});
			});
		}
	}

	private void Post(Action action)
	{
		try
		{
			if (!IsDisposed)
			{
				BeginInvoke(action);
			}
		}
		catch (InvalidOperationException)
		{
		}
	}

	private string RunJob(string task, string asked)
	{
		return Work(new Job(task, asked));
	}

	private string ResumeJob(string text)
	{
		string text2 = Security.Resume(text, DoTool);
		if (text2 != null)
		{
			return text2;
		}
		Job job = this.job;
		if (job == null || !job.Asking)
		{
			return null;
		}
		string input = text.Trim();
		if (Regex.IsMatch(input, "^(yes|yeah|yep|yup|ya|yea|sure|ok|okay|do it|go ahead|go for it|send it|press it|oui)\\b[\\s.!,]*(please|pls|plz|choom)?[\\s.!]*$", RegexOptions.IgnoreCase))
		{
			return Work(job);
		}
		this.job = null;
		if (Regex.IsMatch(input, "^(no|nah|nope|don't|do not|stop|cancel|never mind|nevermind|leave it|non)\\b", RegexOptions.IgnoreCase))
		{
			return "Okay, I left it alone.";
		}
		return null;
	}

	private string Work(Job running)
	{
		lock (mouseGate)
		{
			return Worked(running);
		}
	}

	private string Worked(Job running)
	{
		job = running;
		running.Think = (string system, string user, List<KeyValuePair<string, ToolArguments>> calls) => brain.Step(system, user, Computer.Tools, Computer.ClaudeTools, Computer.Listing, calls);
		Cloud driver = brain.Remote;
		running.Drive = ((brain.Drives && driver.Model != blindModel) ? ((Func<string, string, string, ClaudeReply>)((string system, string tools, string messages) => brain.Drive(system, tools, messages, running.Playing))) : null);
		running.Blind = () =>
		{
			blindModel = driver.Model;
		};
		running.Progress = (string status) =>
		{
			Post(() =>
			{
				working = status + " Esc stops me.";
				UpdateTalk(clock.Elapsed.TotalSeconds);
			});
		};
		running.Seen = (Sight sight) =>
		{
			if (sight != null && !(sight.Window == IntPtr.Zero))
			{
				IntPtr window = sight.Window;
				Rectangle bounds = sight.Bounds;
				string name = AppName(sight);
				Post(() =>
				{
					if (job == running && preferences.Motion && !hidden)
					{
						takeover.Follow(window, name, bounds, (float)preferences.Size / 240f);
					}
				});
			}
		};
		running.Busy = (string what) =>
		{
			Post(() =>
			{
				taskPanel.Busy(running, what);
			});
		};
		running.Stepped = (JobStep step) =>
		{
			Post(() =>
			{
				taskPanel.Add(running, step);
			});
		};
		Computer.PlacePointer(PointerHome());
		Post(() =>
		{
			JobOn(running);
		});
		string result = null;
		bool flag = !testing && Computer.PlaysMedia(running.Task, running.Words, running.Playing);
		Tune before = (flag ? Tunes.Current() : null);
		try
		{
			result = running.Run();
			if (flag && !running.Playing)
			{
				KeepPlaying(running.Outcome, before, 800);
			}
			return result;
		}
		finally
		{
			Computer.Finish();
			if (job == running && !running.Asking)
			{
				job = null;
			}
			string outcome = running.Outcome ?? "failed";
			Post(() =>
			{
				JobOff(running, outcome, result);
			});
		}
	}

	internal static bool KeepPlaying(string outcome, Tune before, int settle)
	{
		if (outcome != "done")
		{
			return false;
		}
		for (int i = 0; i < 2; i++)
		{
			Tune tune = Tunes.Current();
			if (tune == null || tune.Playing || (before != null && before.Key == tune.Key && !before.Playing))
			{
				return false;
			}
			if (i == 0)
			{
				Thread.Sleep(settle);
				continue;
			}
			return Tunes.Send(tune, "play");
		}
		return false;
	}

	private void JobOn(Job running)
	{
		working = "On it. Esc stops me.";
		if (typer.Visible)
		{
			typer.Hide();
		}
		pointing = true;
		if (!hidden)
		{
			taskPanel.Begin(running, running.Words, Screen.FromControl(this).WorkingArea);
		}
		if (SitOnPanel())
		{
			Computer.PlacePointer(PointerHome());
		}
		herPointer.Begin(Computer.HerAt);
		PassThrough();
		if (!chatting && !testing && preferences.HeyCapri && FreeChatOn && OwnEars && HandsFreeMic(preferences.Mic) == null)
		{
			jobEars = true;
			StartLocal();
		}
		UpdateTalk(clock.Elapsed.TotalSeconds);
		SayJobStart(running);
	}

	private void SayJobStart(Job running)
	{
		SayAside("On it. Escape stops me.", running);
	}

	private void SayAside(string line, Job running)
	{
		if (testing || preferences.Silent || (chatting && !local))
		{
			return;
		}
		Func<string, byte[]> fallback = FreeSpeak ?? ((!kokoro.Installed) ? null : new Func<string, byte[]>(kokoro.Speak));
		Func<string, byte[]> free;
		if (preferences.Quiet && !FreeChatOn)
		{
			free = null;
		}
		else
		{
			free = (preferences.ServerVoice ? Served(fallback) : (FreeSpeak ?? Hd(fallback)));
		}
		Func<string, byte[]> speak = ((preferences.Quiet || local || voiceBroke) ? null : Speak);
		if (speak == null && !local && !voiceBroke && voice.Ready && !preferences.Quiet)
		{
			speak = voice.Speak;
		}
		if (speak == null && (voice.Key == null || local || voiceBroke || preferences.Quiet))
		{
			speak = free;
		}
		if (speak == null)
		{
			return;
		}
		string words = Voice.Spoken(line);
		ThreadPool.QueueUserWorkItem((object param0) =>
		{
			byte[] wav = Voiced(speak, free, words, out var problem);
			if (wav == null)
			{
				if (problem != null)
				{
					Brain.Log("job line", -1L, problem);
				}
			}
			else
			{
				int tries = 0;
				Action play = null;
				play = () =>
				{
					if (job == running && !IsDisposed && (!chatting || local))
					{
						double totalSeconds = clock.Elapsed.TotalSeconds;
						if (voiceUntil > totalSeconds)
						{
							if (tries++ < 16)
							{
								ThreadPool.QueueUserWorkItem((object obj) =>
								{
									Thread.Sleep(500);
									Post(play);
								});
							}
						}
						else
						{
							voiceUntil = totalSeconds + Voice.Seconds(wav) + 0.6;
							CheckEars(totalSeconds);
							voice.Play(wav);
						}
					}
				};
				Post(play);
			}
		});
	}

	private void JobOff(Job running, string outcome, string result)
	{
		working = null;
		if (jobEars)
		{
			jobEars = false;
			if (chatting && local)
			{
				StopChat();
			}
		}
		pointing = false;
		herPointer.End();
		PassThrough();
		takeover.Release();
		taskPanel.End(running, outcome, result);
	}

	private bool SitOnPanel()
	{
		if (onPanel)
		{
			return true;
		}
		if (riding || hidden || !preferences.Motion || !taskPanel.Showing || !IsHandleCreated)
		{
			return false;
		}
		Halt();
		EndWalk();
		panelHome = anchor;
		panelSeat = seat;
		panelHung = hanging;
		seat = null;
		falling = false;
		fallTo = null;
		hanging = false;
		dropAfter = false;
		pendingClick = false;
		clickDelay.Stop();
		pressed = false;
		dragging = false;
		Capture = false;
		leanAngle = 0.0;
		onPanel = true;
		taskPanel.Room = Headroom();
		HoldPanel();
		Location = anchor;
		Play(perchGlitch);
		frames.Start();
		pill.Hide();
		Native.SetWindowPos(Handle, new IntPtr(-1), 0, 0, 0, 0, 19);
		return true;
	}

	private void HoldPanel()
	{
		if (!taskPanel.Showing)
		{
			LeavePanel(home: true);
			return;
		}
		Rectangle plate = taskPanel.Plate;
		if (!plate.IsEmpty)
		{
			Rectangle workingArea = Screen.FromRectangle(plate).WorkingArea;
			int val = plate.Right - plate.Width * 3 / 10;
			val = Math.Max(workingArea.Left + (int)Math.Ceiling((float)preferences.Size * (SitX - PerchedBody.Left)), Math.Min(val, workingArea.Right - (int)Math.Ceiling((float)preferences.Size * (PerchedBody.Right - SitX))));
			anchor = Seated(val, plate.Top);
		}
	}

	private void LeavePanel(bool home)
	{
		if (!onPanel)
		{
			return;
		}
		onPanel = false;
		taskPanel.Room = 0;
		if (!preferences.OnTop && IsHandleCreated)
		{
			Native.SetWindowPos(Handle, new IntPtr(-2), 0, 0, 0, 0, 19);
		}
		if (!home)
		{
			return;
		}
		anchor = panelHome;
		seat = panelSeat;
		hanging = panelHung;
		leanAngle = 0.0;
		if (!hidden && !IsDisposed)
		{
			Location = anchor;
			Companion companion = this;
			Clip next;
			if (hanging)
			{
				next = dangle;
			}
			else
			{
				next = ((seat != null) ? perchGlitch : glitch);
			}
			companion.Play(next);
			frames.Start();
			if (seat == null && !hanging)
			{
				DropSoon();
			}
		}
	}

	private string AppName(Sight sight)
	{
		if (sight.Window == namedWindow && namedApp != null)
		{
			return namedApp;
		}
		string input = sight.Program ?? "";
		try
		{
			Native.GetWindowThreadProcessId(sight.Window, out var process);
			using Process process2 = Process.GetProcessById(process);
			string fileDescription = process2.MainModule.FileVersionInfo.FileDescription;
			if (!string.IsNullOrWhiteSpace(fileDescription))
			{
				input = fileDescription.Trim();
			}
		}
		catch (Win32Exception)
		{
		}
		catch (InvalidOperationException)
		{
		}
		catch (ArgumentException)
		{
		}
		catch (NotSupportedException)
		{
		}
		input = Regex.Replace(input, "\\s+", " ").Trim();
		if (input.Length == 0)
		{
			input = "this app";
		}
		if (input.Length > 26)
		{
			input = input.Substring(0, 26).TrimEnd() + "...";
		}
		namedWindow = sight.Window;
		namedApp = char.ToUpperInvariant(input[0]) + input.Substring(1);
		return namedApp;
	}

	private void PassThrough()
	{
		Form[] array = new Form[5] { this, pill, box, taskPanel, player };
		foreach (Form form in array)
		{
			if (form.IsHandleCreated)
			{
				int windowLong = Native.GetWindowLong(form.Handle, -20);
				if ((windowLong & 0x80000) != 0)
				{
					bool flag = lentOut || ((form == this) ? riding : (form != taskPanel && pointing));
					Native.SetWindowLong(form.Handle, -20, flag ? (windowLong | 0x20) : (windowLong & -33));
				}
			}
		}
	}

	private void Lend(bool lent)
	{
		if (InvokeRequired)
		{
			try
			{
				IAsyncResult asyncResult = BeginInvoke((Action)(() =>
				{
					Lend(lent);
				}));
				asyncResult.AsyncWaitHandle.WaitOne(1000);
				return;
			}
			catch (InvalidOperationException)
			{
				return;
			}
		}
		lentOut = lent;
		if (lent)
		{
			taskPanel.LetGo();
			player.LetGo();
			if (pressed)
			{
				pressed = false;
				dragging = false;
				Capture = false;
			}
		}
		PassThrough();
	}

	private void UseBrain(string[] installed, Machine found, Pick local)
	{
		machine = found;
		fit = Engine.Fit(found);
		ollamaRunning = installed != null;
		Cloud remote = brain.Remote;
		if (remote != null)
		{
			brain.Local = null;
			brain.Model = remote.Model;
			mainframe.ShowCloud(remote, cloudModels);
		}
		else if (installed != null && installed.Length > 0)
		{
			brain.Local = null;
			brain.Model = Brain.PickModel(installed, preferences.Model, fit);
			mainframe.ShowOllama(installed, brain.Model);
		}
		else if (local != null)
		{
			brain.LocalPick = local;
			brain.Local = engine;
			brain.Model = local.Name;
			mainframe.ShowLocal(local);
		}
		else
		{
			brain.Local = null;
			brain.Model = null;
			mainframe.ShowSetup(found, fit, ollamaRunning, null);
		}
	}

	internal void SetUpBrain()
	{
		if (SettingUp || machine == null)
		{
			return;
		}
		SettingUp = true;
		engine.Cancel = false;
		Pick pick = fit;
		bool viaOllama = ollamaRunning;
		mainframe.ShowProgress(1, "Starting download", 0L, 0L);
		long shownAt = 0L;
		ThreadPool.QueueUserWorkItem((object param0) =>
		{
			Action<string, long, long> progress = (string text, long done, long total) =>
			{
				long elapsedMilliseconds = clock.ElapsedMilliseconds;
				if (elapsedMilliseconds - Interlocked.Read(ref shownAt) >= 200 || done >= total)
				{
					Interlocked.Exchange(ref shownAt, elapsedMilliseconds);
					string label = (viaOllama ? ("Downloading " + pick.Name) : text);
					Post(() =>
					{
						if (SettingUp)
						{
							mainframe.ShowProgress(1, label, done, total);
						}
					});
				}
			};
			try
			{
				if (viaOllama)
				{
					Brain.Pull(pick.Ollama, progress, () => engine.Cancel);
				}
				else
				{
					engine.Install(pick, progress);
				}
				Post(() =>
				{
					mainframe.ShowProgress(2, "Loading " + pick.Name, 0L, 0L);
				});
				if (viaOllama)
				{
					brain.Local = null;
					brain.Model = pick.Ollama;
					brain.Warm();
				}
				else
				{
					brain.LocalPick = pick;
					brain.Local = engine;
					brain.Model = pick.Name;
					engine.Ensure(pick);
				}
				Post(() =>
				{
					SettingUp = false;
					if (viaOllama)
					{
						preferences.Model = pick.Ollama;
						SavePreferences();
						FindBrain();
					}
					else
					{
						mainframe.ShowLocal(pick);
					}
					Greet();
				});
			}
			catch (OperationCanceledException)
			{
				Post(() =>
				{
					SettingUp = false;
					mainframe.ShowSetup(machine, pick, viaOllama, "Cancelled. It picks up where it left off.");
				});
			}
			catch (Exception ex2)
			{
				string problem = Brain.Brief(ex2.Message) ?? ((ex2.Message.Length > 70) ? (ex2.Message.Substring(0, 67) + "...") : ex2.Message);
				Post(() =>
				{
					SettingUp = false;
					mainframe.ShowSetup(machine, pick, viaOllama, problem);
				});
			}
		});
	}

