	private void SplitKeys()
	{
		if (!preferences.Tiered)
		{
			string text = Voice.Unprotect(preferences.TextKey);
			bool flag = text != null && Cloud.KindOf(text) == "nvidia";
			if (flag)
			{
				preferences.NvidiaKey = preferences.TextKey;
				preferences.NvidiaModel = preferences.TextModel;
			}
			else if (text != null)
			{
				preferences.PaidKey = preferences.TextKey;
				preferences.PaidModel = preferences.TextModel;
			}
			preferences.Tier = ((text != null) ? (flag ? 1 : 2) : 0);
			preferences.Tiered = true;
			if (!testing)
			{
				SavePreferences();
			}
		}
	}

	private Cloud TierCloud()
	{
		string saved;
		if (preferences.Tier == 1)
		{
			saved = preferences.NvidiaKey;
		}
		else
		{
			saved = ((preferences.Tier == 2) ? preferences.PaidKey : null);
		}
		string text = Voice.Unprotect(saved);
		if (text != null)
		{
			return new Cloud(text, (preferences.Tier == 1) ? preferences.NvidiaModel : preferences.PaidModel);
		}
		return null;
	}

