	private void ListCloud(string key, bool connecting)
	{
		Cloud probe = new Cloud(key, null);
		if (connecting)
		{
			mainframe.ShowProblem("Checking key...");
		}
		ThreadPool.QueueUserWorkItem((object param0) =>
		{
			List<string> found = null;
			string problem = null;
			try
			{
				found = Brain.CloudModels(key);
			}
			catch (BrainException ex)
			{
				problem = ex.Message;
			}
			catch (Exception ex2)
			{
				Brain.Log("https://" + probe.Company.ToLowerInvariant() + "/models", -1L, ex2.Message);
				problem = ((brain.Remote != null && brain.Remote.Key == key && brain.Remote.Model != null) ? (probe.Company + " is slow. Using " + brain.Remote.Model + ".") : ("Couldn't reach " + probe.Company + ". Check your internet."));
			}
			Post(() =>
			{
				if (problem != null)
				{
					if (connecting || brain.Remote != null)
					{
						mainframe.ShowProblem(Brain.Brief(problem) ?? ((problem.Length > 60) ? (problem.Substring(0, 57) + "...") : problem));
					}
				}
				else
				{
					if (connecting)
					{
						Cloud cloud = new Cloud(key, Brain.DefaultCloudModel(probe.Kind, found));
						if (cloud.Model == null)
						{
							mainframe.ShowProblem("That key can't use any chat models.");
							return;
						}
						brain.Cancel();
						brain.Remote = cloud;
						if (cloud.Kind == "nvidia")
						{
							preferences.NvidiaKey = Voice.Protect(key);
						}
						else
						{
							preferences.PaidKey = Voice.Protect(key);
						}
						preferences.Tier = ((cloud.Kind == "nvidia") ? 1 : 2);
						Keep(cloud);
						ShowTiers();
					}
					if (brain.Remote != null && !(brain.Remote.Key != key))
					{
						cloudModels = found;
						if (brain.Remote.Model == null || !found.Contains(brain.Remote.Model))
						{
							brain.Remote.Model = Brain.DefaultCloudModel(brain.Remote.Kind, found) ?? brain.Remote.Model;
							Keep(brain.Remote);
						}
						brain.Model = brain.Remote.Model;
						mainframe.ShowCloud(brain.Remote, cloudModels);
						if (connecting)
						{
							Greet();
						}
					}
				}
			});
		});
	}

