	internal void SetUpFreeVoice(bool told = false)
	{
		if (SettingUpVoice)
		{
			return;
		}
		SettingUpVoice = true;
		kokoro.Cancel = false;
		voiceGot = (voiceTotal = 0L);
		ShowVoice(note: false);
		mainframe.VoiceNote("This may take some time. For a better sounding, faster voice, get an API key.", problem: false);
		ShowInstall();
		ThreadPool.QueueUserWorkItem((object param0) =>
		{
			string problem = null;
			bool cancelled = false;
			Action<string, long, long> progress = (string text, long done, long total) =>
			{
				Post(() =>
				{
					if (total > 0)
					{
						voiceGot = done;
						voiceTotal = total;
					}
					ShowInstall();
				});
			};
			try
			{
				kokoro.Install(progress);
				kokoro.Warm();
			}
			catch (OperationCanceledException)
			{
				problem = "Cancelled. It picks up where it left off.";
				cancelled = true;
			}
			catch (Exception ex2)
			{
				problem = Voice.Short(ex2.Message);
			}
			if (problem != null && !cancelled && !testing)
			{
				Brain.Log("free voice setup", -1L, problem);
			}
			Post(() =>
			{
				SettingUpVoice = false;
				ShowInstall();
				ShowVoice();
				if (problem != null)
				{
					mainframe.VoiceNote(problem, problem: true);
					if (told && !cancelled)
					{
						balloonPage = null;
						balloonUpdate = false;
						balloonMainframe = true;
						tray.ShowBalloonTip(15000, "Capri's free voice didn't download", problem + " Click to try again from Capri Mainframe.", ToolTipIcon.Warning);
					}
				}
				else
				{
					if (voice.Key == null || preferences.Quiet || voiceBroke)
					{
						TestVoice();
					}
					GetFreeEars();
					EarsArrived();
				}
			});
		});
	}

	internal static string Listening(string picked, string windows)
	{
		return LocalEars.Spoken(Brain.LanguageCode(picked), (picked == null) ? windows : null);
	}

