	private void GetFreeEars(bool retry = false)
	{
		if (testing || settingUpEars || !FreeChatOn || parakeet.Installed || !parakeet.Fits)
		{
			return;
		}
		settingUpEars = true;
		parakeet.Cancel = false;
		earsGot = (earsTotal = 0L);
		ShowInstall();
		if (!SettingUpVoice && !retry)
		{
			balloonPage = null;
			balloonUpdate = false;
			balloonMainframe = true;
			tray.ShowBalloonTip(8000, "Getting Capri's ears", Engine.Amount(parakeet.Size) + ", one time. Then she hears any mic, offline. Click to watch it download.", ToolTipIcon.Info);
		}
		ThreadPool.QueueUserWorkItem((object param0) =>
		{
			string problem = null;
			Action<string, long, long> progress = (string text, long done, long total) =>
			{
				Post(() =>
				{
					if (total > 0)
					{
						earsGot = done;
						earsTotal = total;
					}
					ShowInstall();
				});
			};
			try
			{
				parakeet.Install(progress);
			}
			catch (OperationCanceledException)
			{
				problem = "Cancelled.";
			}
			catch (Exception ex2)
			{
				problem = Voice.Short(ex2.Message);
			}
			if (problem != null)
			{
				Brain.Log("ears setup", -1L, problem);
			}
			Post(() =>
			{
				settingUpEars = false;
				ShowInstall();
				if (problem != null)
				{
					EarsFailed(problem);
				}
				else
				{
					earsFailures = 0;
					if (!parakeet.Installed)
					{
						GetFreeEars();
					}
					else if (!EarsArrived() && chatting && local)
					{
						mainframe.VoiceNote("Her own ears are in.", problem: false);
					}
				}
			});
		});
	}

	private void EarsFailed(string problem)
	{
		if (problem == "Cancelled." || !chatting || !local)
		{
			mainframe.VoiceNote("Her own ears didn't download: " + problem, problem: true);
			return;
		}
		earsFailures++;
		int num = EarsRetryWait(earsFailures);
		earsRetryAt = clock.Elapsed.TotalSeconds + (double)num;
		string text;
		if (num < 60)
		{
			text = num + " seconds";
		}
		else
		{
			text = ((num == 60) ? "a minute" : (num / 60 + " minutes"));
		}
		string text2 = " I'll try again in " + text + ".";
		if (earsAwaited && earsFailures == 1)
		{
			EarsNote(earsLead + "My ears didn't download, so type to me for now. " + problem + text2, problem: true);
		}
		else
		{
			mainframe.VoiceNote("Her own ears didn't download: " + problem + text2, problem: true);
		}
	}

	internal static int EarsRetryWait(int failures)
	{
		return Math.Min(300, 30 << Math.Max(0, Math.Min(4, failures - 1)));
	}

	private void CheckHearing(double now)
	{
		if (earsRetryAt >= 0.0 && now >= earsRetryAt)
		{
			earsRetryAt = -1.0;
			if (chatting && local)
			{
				GetFreeEars(retry: true);
			}
		}
		if (!chatting || !local || !earsReady || ears.Muted || micHeard || micWarned)
		{
			micQuietFrom = -1.0;
		}
		else if (micQuietFrom < 0.0)
		{
			micQuietFrom = now;
		}
		else if (now - micQuietFrom >= 20.0 && talkState != TalkState.Thinking && now - earsWarned >= 8.0)
		{
			micWarned = true;
			Missed("I can't hear anything from your mic. Pick the right one under VOICE, or let desktop apps use your mic in Windows Settings > Privacy & security > Microphone.", problem: true);
		}
	}

	private void HeardLevel(double value)
	{
		if (value >= 0.0005)
		{
			micHeard = true;
		}
		pill.SetLevel((local && (earsShut || transcribing || noiseHold || !earsReady)) ? 0.0 : value);
	}

