	private void CheckWake(double now)
	{
		if (testing && !wakeChecks)
		{
			return;
		}
		if (!preferences.HeyCapri || quitting)
		{
			if (wakeOpen)
			{
				CloseWake();
			}
			return;
		}
		if (!WakeReady)
		{
			if (wakeOpen)
			{
				CloseWake();
			}
			GetWake(now);
			return;
		}
		if (wakeAskedVoice || wakeTries > 0)
		{
			wakeAskedVoice = false;
			wakeTries = 0;
			wakeRetryAt = -1.0;
		}
		heyCapri.Held = now < voiceUntil || speaker.Busy;
		if (now >= wakeMuteAt)
		{
			wakeMuteAt = now + 2.0;
			wakeMicMuted = MicMuted(preferences.Mic) == true;
			wakeHandsFree = HandsFreeMic(preferences.Mic);
		}
		if (WakePaused)
		{
			if (wakeOpen)
			{
				CloseWake();
			}
		}
		else if (wakeHandsFree != null)
		{
			if (wakeOpen)
			{
				CloseWake();
			}
			if (!wakeHandsFreeSaid)
			{
				wakeHandsFreeSaid = true;
				string text = "I'm not listening for \"Hey Capri\" on your Bluetooth headset: while its mic is open, everything you hear drops to phone-call quality. Pick another mic under VOICE, or use my talk key.";
				if (wakeTell)
				{
					WakeNote(text, problem: false);
				}
				else
				{
					mainframe.VoiceNote(text, problem: false);
				}
			}
		}
		else if (wakeOpen && !testing && heyCapri.Stalled)
		{
			CloseWake();
			wakeRetryAt = now + 2.0;
		}
		else if (!wakeOpen && now >= wakeRetryAt)
		{
			OpenWake(now);
		}
	}

	private void OpenWake(double now)
	{
		if (!testing && !heyCapri.Warmed)
		{
			if (wakeWarming)
			{
				return;
			}
			wakeWarming = true;
			ThreadPool.QueueUserWorkItem((object param0) =>
			{
				string problem = null;
				try
				{
					heyCapri.Warm();
				}
				catch (Exception ex2)
				{
					problem = Voice.Short(ex2.Message);
				}
				if (problem != null && !wakeMicSaid)
				{
					Brain.Log("hey capri", -1L, problem);
				}
				Post(() =>
				{
					wakeWarming = false;
					if (!preferences.HeyCapri)
					{
						heyCapri.Dispose();
					}
					else if (problem != null)
					{
						wakeRetryAt = clock.Elapsed.TotalSeconds + 30.0;
						if (!wakeMicSaid)
						{
							wakeMicSaid = true;
							WakeNote("I can't listen for \"Hey Capri\": " + problem, problem: true);
						}
					}
				});
			});
			return;
		}
		wakeOpens++;
		try
		{
			if (!testing)
			{
				heyCapri.Listen(preferences.Mic);
			}
		}
		catch (Exception ex)
		{
			if (!(ex is VoiceException) && !(ex is IOException) && !wakeMicSaid)
			{
				Brain.Log("hey capri", -1L, Voice.Short(ex.Message));
			}
			wakeRetryAt = now + 30.0;
			if (!wakeMicSaid)
			{
				wakeMicSaid = true;
				WakeNote("I can't listen for \"Hey Capri\": " + ex.Message, problem: true);
			}
			return;
		}
		wakeOpen = true;
		if (!wakeSaid)
		{
			wakeSaid = true;
			string text = "Listening for \"Hey Capri\". Nothing leaves your PC until you say it.";
			if (wakeTell)
			{
				WakeNote(text, problem: false);
			}
			else
			{
				mainframe.VoiceNote(text, problem: false);
			}
		}
	}

	private void CloseWake()
	{
		wakeOpen = false;
		if (!testing)
		{
			heyCapri.Pause();
		}
	}

	private void WakeChanged()
	{
		if (testing && !wakeChecks)
		{
			return;
		}
		wakeTell = preferences.HeyCapri;
		wakeSaid = (wakeMicSaid = (wakeHandsFreeSaid = false));
		wakeRetryAt = (wakeMuteAt = -1.0);
		wakeTries = 0;
		if (preferences.HeyCapri)
		{
			CheckWake(clock.Elapsed.TotalSeconds);
			return;
		}
		heyCapri.Cancel = true;
		if (wakeAskedVoice && SettingUpVoice)
		{
			kokoro.Cancel = true;
		}
		wakeAskedVoice = false;
		wakeOpen = false;
		if (!testing)
		{
			heyCapri.Dispose();
		}
		mainframe.VoiceNote("Not listening for \"Hey Capri\".", problem: false);
	}

	private void GetWake(double now)
	{
		if (settingUpWake || SettingUpVoice || now < wakeRetryAt)
		{
			return;
		}
		if (IntPtr.Size != 8)
		{
			if (!wakeMicSaid)
			{
				wakeMicSaid = true;
				WakeNote("Listening for \"Hey Capri\" needs 64-bit Windows.", problem: true);
			}
		}
		else if (!(wakeVoiceTest ?? heyCapri.VoiceIn))
		{
			if (wakeAskedVoice)
			{
				wakeAskedVoice = false;
				wakeRetryAt = now + (double)EarsRetryWait(++wakeTries);
				return;
			}
			wakeAskedVoice = true;
			wakeTell = true;
			WakeNote("To hear \"Hey Capri\" I need my free voice, so I'm getting it: " + Engine.Amount(LocalVoice.PackSize) + ", then " + Engine.Amount(WakeWord.PackSize) + " more, one time.", problem: false);
			getWakeVoice();
		}
		else
		{
			wakeAskedVoice = false;
			wakeTell = true;
			WakeNote("Getting what I need to hear \"Hey Capri\": " + Engine.Amount(WakeWord.PackSize) + ", one time. It all stays on your PC.", problem: false);
			getWakePack();
		}
	}

	private void FetchWake()
	{
		settingUpWake = true;
		wakeFetches++;
		heyCapri.Cancel = false;
		ThreadPool.QueueUserWorkItem((object param0) =>
		{
			string problem = null;
			int shown = -1;
			Action<string, long, long> progress = (string text, long done, long total) =>
			{
				int percent = ((total > 0) ? ((int)(done * 10 / total) * 10) : 0);
				if (percent != shown)
				{
					shown = percent;
					Post(() =>
					{
						if (settingUpWake && preferences.HeyCapri)
						{
							mainframe.VoiceNote("Getting \"Hey Capri\" (" + Engine.Amount(WakeWord.PackSize) + "): " + percent + "%", problem: false);
						}
					});
				}
			};
			try
			{
				heyCapri.Install(progress);
				heyCapri.Warm();
			}
			catch (OperationCanceledException)
			{
				problem = "Cancelled.";
			}
			catch (Exception ex2)
			{
				problem = Voice.Short(ex2.Message);
			}
			if (problem != null && problem != "Cancelled.")
			{
				Brain.Log("hey capri setup", -1L, problem);
			}
			Post(() =>
			{
				settingUpWake = false;
				if (preferences.HeyCapri)
				{
					if (problem == null)
					{
						wakeTries = 0;
						wakeRetryAt = -1.0;
					}
					else
					{
						int num = EarsRetryWait(++wakeTries);
						wakeRetryAt = clock.Elapsed.TotalSeconds + (double)num;
						WakeNote("\"Hey Capri\" didn't download: " + problem + " I'll try again in " + ((num < 60) ? (num + " seconds") : ((num == 60) ? "a minute" : (num / 60 + " minutes"))) + ".", problem: true);
					}
				}
			});
		});
	}

	private void WakeNote(string text, bool problem)
	{
		mainframe.VoiceNote(text, problem);
		if (!hidden && !chatting && talkState == TalkState.Off)
		{
			Say(text);
		}
	}

	private void HeardHeyCapri()
	{
		if (testing && !wakeChecks)
		{
			return;
		}
		wakeHeard++;
		if (!preferences.HeyCapri || !wakeOpen || WakePaused || quitting || IsDisposed)
		{
			return;
		}
		CloseWake();
		if (hidden)
		{
			SetHidden(value: false);
		}
		ToggleChat();
		if (!chatting)
		{
			return;
		}
		string text = WakeLines[random.Next(WakeLines.Length)];
		Job job = this.job;
		if (local && job != null && working != null)
		{
			SayAside(text, job);
			return;
		}
		heard = "hey capri";
		box.Prompt = "> you: ";
		if (local)
		{
			Answer(++asking, text, TalkState.Talking);
		}
		else
		{
			Begin(++asking, text, TalkState.Talking, null);
		}
	}

	private void ShowInstall()
	{
		bool settingUpVoice = SettingUpVoice;
		bool flag = settingUpEars;
		bool flag2 = settingUpHd;
		if (!settingUpVoice && !flag && !flag2)
		{
			mainframe.HideInstall();
			return;
		}
		long done = (settingUpVoice ? voiceGot : 0) + (flag ? earsGot : 0) + (flag2 ? hdGot : 0);
		long total = ((!settingUpVoice) ? 0 : ((voiceTotal > 0) ? voiceTotal : LocalVoice.PackSize)) + ((!flag) ? 0 : ((earsTotal > 0) ? earsTotal : parakeet.Size)) + ((!flag2) ? 0 : ((hdTotal > 0) ? hdTotal : QwenVoice.PackSize));
		string text;
		if (settingUpVoice && flag)
		{
			text = "Installing the speech model + ears";
		}
		else if (settingUpVoice)
		{
			text = "Installing the local speech model";
		}
		else
		{
			text = (flag ? "Installing her ears" : "Installing her HD voice");
		}
		mainframe.ShowInstall((flag2 && (settingUpVoice || flag)) ? (text + " + HD voice") : text, done, total);
	}

