	private void SetUpHd()
	{
		if (settingUpHd)
		{
			return;
		}
		settingUpHd = true;
		qwen.Cancel = false;
		hdGot = (hdTotal = 0L);
		ShowInstall();
		mainframe.VoiceNote("Getting her HD voice (" + Engine.Amount(QwenVoice.PackSize) + "), one time. Pick another free voice to stop.", problem: false);
		ThreadPool.QueueUserWorkItem((object param0) =>
		{
			string problem = null;
			bool cancelled = false;
			Action<string, long, long> progress = (string text, long done, long total) =>
			{
				Post(() =>
				{
					if (total > 0)
					{
						hdGot = done;
						hdTotal = total;
					}
					ShowInstall();
				});
			};
			try
			{
				qwen.Install(progress);
			}
			catch (OperationCanceledException)
			{
				cancelled = true;
			}
			catch (Exception ex2)
			{
				problem = Voice.Short(ex2.Message);
			}
			if (problem != null)
			{
				Brain.Log("HD voice setup", -1L, problem);
			}
			Post(() =>
			{
				settingUpHd = false;
				ShowInstall();
				ShowVoice();
				if (!cancelled)
				{
					if (problem != null)
					{
						mainframe.VoiceNote(problem, problem: true);
					}
					else if (preferences.HdVoice)
					{
						hdTest = voice.Key == null;
						WakeHd();
					}
				}
			});
		});
	}

	private void WakeHd()
	{
		if (wakingHd || testing)
		{
			return;
		}
		wakingHd = true;
		hdUsed = clock.Elapsed.TotalSeconds;
		ThreadPool.QueueUserWorkItem((object param0) =>
		{
			string problem = null;
			bool stopped = false;
			long num = (qwen.Awake ? (-1) : QwenVoice.FreeRoom());
			if (num >= 0 && num < 2684354560u)
			{
				problem = "Her HD voice needs about " + Engine.Amount(2684354560L) + " of free graphics memory, so she's on her free voice. Close games or pick a smaller brain.";
			}
			else
			{
				try
				{
					qwen.Warm();
				}
				catch (OperationCanceledException)
				{
					stopped = true;
				}
				catch (Exception ex2)
				{
					problem = Voice.Short(ex2.Message);
				}
			}
			Post(() =>
			{
				wakingHd = false;
				bool flag = hdTest;
				string text = hdLine;
				hdTest = false;
				hdLine = null;
				if (!stopped)
				{
					if (!preferences.HdVoice)
					{
						qwen.Stop();
					}
					else
					{
						if (problem != null)
						{
							HdTrouble(problem);
						}
						if (text != null)
						{
							CheckVoice(text, quiet: true);
						}
						else if (flag && problem == null)
						{
							TestVoice();
						}
					}
				}
			});
		});
	}

	private Func<string, byte[]> Hd(Func<string, byte[]> fallback)
	{
		if (!preferences.HdVoice || preferences.Silent || !qwen.Installed || clock.Elapsed.TotalSeconds < hdRest)
		{
			return fallback;
		}
		if (HdStepsAside())
		{
			qwen.Stop();
			return fallback;
		}
		hdUsed = clock.Elapsed.TotalSeconds;
		if (!qwen.Awake)
		{
			WakeHd();
			return fallback;
		}
		return qwen.Or(fallback, (string problem) =>
		{
			Post(() =>
			{
				HdTrouble(problem);
			});
		});
	}

	private void HdTrouble(string problem)
	{
		if (!testing)
		{
			Brain.Log("HD voice", -1L, problem);
		}
		qwen.Stop();
		hdRest = clock.Elapsed.TotalSeconds + 600.0;
		mainframe.VoiceNote(problem, problem: true);
	}

	private void CheckHd(double now)
	{
		if (!(now - hdChecked < 3.0))
		{
			hdChecked = now;
			if (!wakingHd && qwen.Awake && (!preferences.HdVoice || preferences.Silent || now - hdUsed > 600.0 || HdStepsAside()))
			{
				qwen.Stop();
			}
		}
	}

	private bool HdStepsAside()
	{
		if (preferences.HdGameRest)
		{
			return Native.Gaming();
		}
		return false;
	}

	internal void ChooseVoiceStyle(string name)
	{
		if (name == "HD")
		{
			ChooseHd();
			return;
		}
		if (preferences.HdVoice || settingUpHd)
		{
			preferences.HdVoice = false;
			qwen.Cancel = true;
			qwen.Stop();
		}
		kokoro.Style = LocalVoice.Find(name);
		preferences.VoiceStyle = ((kokoro.Style == LocalVoice.Styles[0]) ? null : kokoro.Style.Name);
		preferences.ServerVoice = false;
		SavePreferences();
		ShowVoice();
		if (voice.Key == null && kokoro.Installed)
		{
			TestVoice();
		}
	}

	internal void TestVoice()
	{
		if (preferences.Silent)
		{
			mainframe.VoiceNote("Her voice is OFF. Pick another row under VOICE to hear her.", problem: true);
			return;
		}
		if (voice.Key == null && Speak == null && !kokoro.Installed && !preferences.ServerVoice)
		{
			mainframe.VoiceNote("Get her free voice, or paste an ElevenLabs key.", problem: true);
			return;
		}
		if (voice.Key != null && voice.VoiceId == null && Speak == null)
		{
			mainframe.VoiceNote("Paste your Voice ID first.", problem: true);
			return;
		}
		if (hidden)
		{
			SetHidden(value: false);
		}
		brain.Cancel();
		heard = "voice check";
		box.Prompt = "> sys: ";
		Answer(++asking, "Voice link online. Sentiu minha falta, choom?", TalkState.Talking);
	}

	private static string ServerAddress(string url, string api)
	{
		string text;
		if (!(api == "file"))
		{
			text = Typed(url);
			if (text == null)
			{
				if (!(api == "fish"))
				{
