	private static double Fundamental(short[] sound, int rate)
	{
		int num = sound.Length / 4;
		int num2 = Math.Min(rate / 5, sound.Length / 2);
		int num3 = rate / 1000;
		int num4 = rate / 60;
		double[] array = new double[num4 + 2];
		double num5 = 0.0;
		for (int i = num3; i <= num4 + 1; i++)
		{
			for (int j = num; j < num + num2 && j + i < sound.Length; j++)
			{
				array[i] += (double)sound[j] * (double)sound[j + i];
			}
			if (i <= num4)
			{
				num5 = Math.Max(num5, array[i]);
			}
		}
		for (int k = num3 + 1; k <= num4; k++)
		{
			if (array[k] >= 0.8 * num5 && array[k] >= array[k - 1] && array[k] >= array[k + 1])
			{
				return (double)rate / (double)k;
			}
		}
		return 0.0;
	}

	private static string FakeServer(string[] replies, List<string> asked, out TcpListener listener, int status = 200, int delay = 0, bool drip = false, int missing = 0)
	{
		TcpListener server = new TcpListener(IPAddress.Loopback, 0);
		server.Start();
		listener = server;
		ThreadPool.QueueUserWorkItem((object param0) =>
		{
			try
			{
				string[] array = replies;
				foreach (string text in array)
				{
					using TcpClient tcpClient = server.AcceptTcpClient();
					using NetworkStream networkStream = tcpClient.GetStream();
					MemoryStream memoryStream = new MemoryStream();
					byte[] array2 = new byte[8192];
					string text2 = "";
					while (true)
					{
						int num = networkStream.Read(array2, 0, array2.Length);
						if (num <= 0)
						{
							break;
						}
						memoryStream.Write(array2, 0, num);
						text2 = Encoding.UTF8.GetString(memoryStream.ToArray());
						int num2 = text2.IndexOf("\r\n\r\n", StringComparison.Ordinal);
						if (num2 >= 0)
						{
							Match match = Regex.Match(text2, "Content-Length:\\s*(\\d+)", RegexOptions.IgnoreCase);
							if (memoryStream.Length >= num2 + 4 + (match.Success ? int.Parse(match.Groups[1].Value) : 0))
							{
								break;
							}
						}
					}
					lock (asked)
					{
						asked.Add(text2);
					}
					Match match2 = Regex.Match(text, "^!(\\d{3}) ");
					byte[] bytes = Encoding.UTF8.GetBytes(match2.Success ? text.Substring(match2.Length) : text);
					if (!drip && delay > 0)
					{
						Thread.Sleep(delay);
					}
					byte[] bytes2 = Encoding.ASCII.GetBytes("HTTP/1.1 " + (match2.Success ? match2.Groups[1].Value : status.ToString()) + " Reply\r\nContent-Type: application/json\r\nContent-Length: " + (bytes.Length + missing) + "\r\nConnection: close\r\n\r\n");
					networkStream.Write(bytes2, 0, bytes2.Length);
					if (!drip)
					{
						networkStream.Write(bytes, 0, bytes.Length);
					}
					else
					{
						byte[] array3 = bytes;
						foreach (byte value in array3)
						{
							networkStream.WriteByte(value);
							Thread.Sleep(delay);
						}
					}
				}
			}
			catch (Exception)
			{
			}
		});
		return "http://127.0.0.1:" + ((IPEndPoint)server.LocalEndpoint).Port;
	}

