	private void ToggleChat()
	{
		if (chatting)
		{
			StopChat();
			return;
		}
		if (FreeChatOn && (preferences.Quiet || preferences.Silent || voice.Key == null))
		{
			StartLocal();
			return;
		}
		if ((preferences.Quiet || preferences.Silent) && voice.Key != null)
		{
			heard = "(voice)";
			box.Prompt = "> you: ";
			Answer(++asking, "ElevenLabs isn't picked, so voice chat is off. Pick it under CLOUD VOICE in the Mainframe to talk to me.", TalkState.Talking, quiet: true);
			return;
		}
		if (voice.Key == null || voice.VoiceId == null)
		{
			heard = "(voice)";
			box.Prompt = "> you: ";
			Answer(++asking, (voice.Key == null) ? "Voice chat needs an ElevenLabs key, choom. Make one with Restrict key turned off, then paste it under VOICE in Capri Mainframe. Type to me for now." : "Voice chat needs my Voice ID, choom. Right-click me, open Capri Mainframe and pick a voice in the Voice ID box under VOICE. Type to me for now.", TalkState.Talking);
			mainframe.Restore();
			return;
		}
		chatting = true;
		ears.Muted = false;
		if (!testing && !muteKey)
		{
			muteKey = ByMouse(preferences.MuteVk) || Native.RegisterHotKey(Handle, 17229, preferences.MuteMods | 0x4000, preferences.MuteVk);
		}
		pill.SetChat(on: true, micMuted: false);
		pillUntil = clock.Elapsed.TotalSeconds + 3.0;
		brain.Cancel();
		CloseTalk();
		OpenLink();
	}

