	private void ListenLocally()
	{
		lock (waking)
		{
			utterance = null;
			quietRun = 0;
			loudRun = 0;
			noiseHold = false;
			preroll.Clear();
			room = -1.0;
			lineAt = -100.0;
		}
		earsAwaited = false;
		if (OwnEars)
		{
			ListenOwn();
			return;
		}
		Hearing.Own = null;
		GetFreeEars();
		Dictation opened;
		try
		{
			opened = Dictation.Make();
		}
		catch (Exception ex)
		{
			HearLater("Windows speech recognition isn't on this PC: " + Voice.Short(ex.Message));
			return;
		}
		opened.Language = preferences.Language;
		dictation = opened;
		opened.Heard = (string text) =>
		{
			OnUi(() =>
			{
				if (dictation == opened)
				{
					HeardDictation(text);
				}
			});
		};
		opened.Lost = (string problem) =>
		{
			OnUi(() =>
			{
				if (dictation == opened)
				{
					DictationLost(problem);
				}
			});
		};
		EarsNote(earsLead + "One sec, opening my ears.", problem: false);
		opened.Start((string problem) =>
		{
			OnUi(() =>
			{
				if (dictation == opened)
				{
					Dictated(problem);
				}
			});
		});
	}

	private void Dictated(string problem)
	{
		if (!chatting || !local)
		{
			return;
		}
		if (problem != null)
		{
			DictationLost(problem);
			return;
		}
		try
		{
			if (!testing && !ears.Listening)
			{
				ears.Start();
			}
		}
		catch (VoiceException)
		{
		}
		earsReady = true;
		dictation.Hold(ears.Muted);
		CheckEars(clock.Elapsed.TotalSeconds);
		string text = MicName(preferences.Mic);
		string text2 = ((text == null || ears.Muted) ? null : Dictation.OtherMic(preferences.Mic, text, Dictation.DefaultMic()));
		if (text2 != null)
		{
			EarsNote(earsLead + "Free voice chat on, but Windows speech only hears your default mic, not " + text + ". The fix is under VOICE.", problem: false);
			mainframe.VoiceNote(text2, problem: true);
		}
		else
		{
			Companion companion = this;
			string text3;
			if (ears.Muted)
			{
				text3 = earsLead + "Free voice chat is ready; your mic is muted.";
			}
			else
			{
				text3 = ((earsLead.Length > 0) ? (earsLead + "Free voice chat is on; talk and I'll type back.") : "Free voice chat on. Talk and I'll type back.");
			}
			companion.EarsNote(text3, problem: false);
		}
	}

	private void DictationLost(string problem)
	{
		Dictation dictation = this.dictation;
		this.dictation = null;
		dictation?.Dispose();
		if (chatting && local)
		{
			earsReady = false;
			if (OwnEars)
			{
				ListenOwn();
			}
			else
			{
				HearLater(problem);
			}
		}
	}

