	private void HeardDictation(string text)
	{
		if (chatting && local && earsReady)
		{
			CheckEars(clock.Elapsed.TotalSeconds);
			text = Hearing.Clean(text);
			if (!earsShut && text.Length != 0)
			{
				mainframe.VoiceNote("Free voice chat on. Talk and I'll type back.", problem: false);
