	private void CheckEars(double now)
	{
		earsShut = local && (!earsReady || transcribing || ears.Muted || (talkState == TalkState.Thinking && working == null) || now < voiceUntil);
		if (earsShut)
		{
			lock (waking)
			{
				utterance = null;
				preroll.Clear();
				loudRun = 0;
				quietRun = 0;
			}
			pill.SetLevel(0.0);
		}
	}

	private void Missed(string text, bool problem)
	{
		mainframe.VoiceNote(text, problem);
		double totalSeconds = clock.Elapsed.TotalSeconds;
		if (!(totalSeconds - earsWarned < 8.0) && talkState != TalkState.Thinking)
		{
			earsWarned = totalSeconds;
			EarsNote(text, problem);
		}
	}

	private void Gather(short[] chunk)
	{
		double num = VoiceLevel(chunk);
		lock (waking)
		{
			if (!local || !earsReady || dictation != null || ears.Muted || earsShut || transcribing)
			{
				utterance = null;
				preroll.Clear();
				loudRun = 0;
				quietRun = 0;
				return;
			}
			if (room < 0.0)
			{
				room = Math.Min(Math.Max(num, 0.0003), 1.0 / 150.0);
			}
			else if (num < room)
			{
				room = Math.Max(num, 0.0003);
			}
			else if (utterance == null)
			{
				room = Math.Min(num, room * 1.02);
			}
			double wake = RoomWake();
			bool flag = num >= wake;
			if (noiseHold)
			{
				quietRun = ((!flag) ? (quietRun + 1) : 0);
				if (quietRun >= 9)
				{
					noiseHold = false;
					quietRun = 0;
				}
				return;
			}
			if (utterance == null)
			{
				preroll.Add(chunk);
				if (preroll.Count > 4)
				{
					preroll.RemoveAt(0);
				}
				loudRun = (flag ? (loudRun + 1) : 0);
				if (loudRun >= 2)
				{
					utterance = new List<short[]>(preroll);
					preroll.Clear();
					loudRun = 0;
					quietRun = 0;
				}
				return;
			}
			utterance.Add(chunk);
			quietRun = ((!flag) ? (quietRun + 1) : 0);
			if (utterance.Count >= 20)
			{
				double num2 = 1.0;
				double num3 = 0.0;
				for (int i = utterance.Count - 20; i < utterance.Count; i++)
				{
					double val = VoiceLevel(utterance[i]);
					num2 = Math.Min(num2, val);
					num3 = Math.Max(num3, val);
				}
				if (num3 < num2 * 1.2)
				{
					room = Math.Max(room, num2);
					utterance = null;
					quietRun = 0;
					return;
				}
			}
			if (quietRun < 9 && utterance.Count < 150)
			{
				return;
			}
			short[][] taken = utterance.ToArray();
			bool flag2 = quietRun < 9;
			utterance = null;
			quietRun = 0;
			int ticket = chatTicket;
			int request = asking;
			if (flag2)
			{
				double num4 = 1.0;
				for (int j = 4; j < taken.Length; j++)
				{
					num4 = Math.Min(num4, VoiceLevel(taken[j]));
				}
				room = Math.Max(room, num4);
				noiseHold = true;
				Post(() =>
				{
					if (ticket == chatTicket && local)
					{
						Missed("I heard 15 seconds without a pause. Try a shorter line or lower your mic volume.", problem: false);
					}
				});
			}
			else if (LineCounts(taken, wake, clock.Elapsed.TotalSeconds))
			{
				transcribing = true;
				Post(() =>
				{
					Transcribe(taken, ticket, request, wake);
				});
			}
		}
	}

	private double RoomWake()
	{
		return Math.Max(0.006, Math.Min(room * 3.0, Math.Max(0.02, room * 1.6)));
	}

	private bool LineCounts(short[][] taken, double wake, double now)
	{
		if (!Speech(taken, wake))
		{
			return false;
		}
		double num = 0.0;
		foreach (short[] samples in taken)
		{
			num = Math.Max(num, VoiceLevel(samples));
		}
		if (now - lineAt < 60.0 && num < lineLevel / 3.16 && !Speech(taken))
		{
			return false;
		}
		lineAt = now;
		lineLevel = num;
		return true;
	}

	private static double VoiceLevel(short[] samples)
	{
		if (samples.Length == 0)
		{
			return 0.0;
		}
		double num = 0.0;
		double num2 = 0.0;
		foreach (short num3 in samples)
		{
			num += 0.3 * ((double)num3 - num);
			num2 += num * num;
		}
		return Math.Sqrt(num2 / (double)samples.Length) / 32768.0;
	}

	private static bool Speech(short[][] taken, double wake = 0.02)
	{
		int num = 0;
		double num2 = 1.0;
		double num3 = 0.0;
		foreach (short[] array in taken)
		{
			double num4 = VoiceLevel(array);
			if (!(num4 < wake))
			{
				num += array.Length;
				num2 = Math.Min(num2, num4);
				num3 = Math.Max(num3, num4);
			}
		}
		if (num >= 4800)
		{
			if (num >= 12800)
			{
				return num3 >= num2 * 1.2;
			}
			return true;
		}
		return false;
	}

	private void Transcribe(short[][] taken, int ticket, int request, double wake = 0.02)
	{
		if (ticket != chatTicket || !local || !chatting)
		{
			return;
		}
		if (request != asking)
		{
			transcribing = false;
			CheckEars(clock.Elapsed.TotalSeconds);
			return;
		}
		if (ears.Muted || (talkState == TalkState.Thinking && working == null) || clock.Elapsed.TotalSeconds < voiceUntil || !Speech(taken, wake))
		{
			transcribing = false;
			CheckEars(clock.Elapsed.TotalSeconds);
			if (!earsShut)
			{
				Missed("I couldn't make out any words. Try closer to the mic.", problem: false);
			}
			return;
		}
		int num = 0;
		foreach (short[] array in taken)
		{
			num += array.Length;
		}
		short[] samples = new short[num];
		int num2 = 0;
		foreach (short[] array2 in taken)
		{
			Array.Copy(array2, 0, samples, num2, array2.Length);
			num2 += array2.Length;
		}
		CheckEars(clock.Elapsed.TotalSeconds);
		mainframe.VoiceNote("Hearing you...", problem: false);
		ThreadPool.QueueUserWorkItem((object param0) =>
		{
			string text = null;
			string problem = null;
			try
			{
				text = Hearing.Text(samples);
			}
			catch (Exception ex)
			{
				problem = Voice.Short(ex.Message);
			}
			Post(() =>
			{
				HeardLocally(ticket, request, text, problem);
			});
		});
	}

	private void HeardLocally(int ticket, int request, string text, string problem)
	{
		if (ticket == chatTicket && chatting && local)
		{
			transcribing = false;
			CheckEars(clock.Elapsed.TotalSeconds);
			if (request != asking || ears.Muted)
			{
				mainframe.VoiceNote("Free voice chat on. Talk and I'll type back.", problem: false);
			}
			else if (problem != null)
			{
				Missed("I couldn't hear that. Try again, or check your mic under VOICE.", problem: true);
				mainframe.VoiceNote(problem, problem: true);
			}
			else if (string.IsNullOrEmpty(text))
			{
				Missed("I couldn't make out any words. Try again closer to the mic.", problem: false);
			}
			else
			{
				mainframe.VoiceNote("Free voice chat on. Talk and I'll type back.", problem: false);
				Hear(text, text, "> you: ");
			}
		}
	}

	private void OpenLink()
	{
		mainframe.VoiceNote("Opening voice chat...", problem: false);
		int ticket = ++chatTicket;
		string key = voice.Key;
		string voiceId = voice.VoiceId;
		string agentId = preferences.AgentId;
		bool stale = Agent.Stale(preferences.AgentVersion, preferences.AgentPersonality);
		string stamp = "";
		string language = Brain.LanguageCode(Brain.Language);
		string polyglot = preferences.AgentPolyglot;
		ThreadPool.QueueUserWorkItem((object param0) =>
		{
			string url = null;
			string problem = null;
			try
			{
				if (agentId == null)
				{
					agentId = Agent.Create(key, voiceId);
				}
				else if (stale)
				{
					try
					{
						Agent.Tune(key, agentId);
					}
					catch (VoiceException ex)
					{
						if (ex.Status != 404 && ex.Status != 400)
						{
							throw;
						}
						agentId = Agent.Create(key, voiceId);
					}
				}
				try
				{
					url = Agent.Address(key, agentId);
				}
				catch (VoiceException ex2)
				{
					if (ex2.Status != 404 && ex2.Status != 400)
					{
						throw;
					}
					agentId = Agent.Create(key, voiceId);
					url = Agent.Address(key, agentId);
				}
				if (language != "en" && polyglot != agentId)
				{
					try
					{
						Agent.Polyglot(key, agentId);
						polyglot = agentId;
					}
					catch (VoiceException ex3)
					{
						Brain.Log("https://api.elevenlabs.io/v1/convai/agents", -1L, "Voice chat couldn't switch languages: " + ex3.Message);
						language = "en";
					}
				}
			}
			catch (VoiceException ex4)
			{
				problem = ex4.Message;
			}
			catch (Exception ex5)
			{
				problem = Voice.Short("Voice chat failed: " + ex5.Message);
			}
			Post(() =>
			{
				if (ticket == chatTicket && chatting)
				{
					if (problem != null)
					{
						ChatFailed(problem);
					}
					else
					{
						if (preferences.AgentId != agentId || preferences.AgentVersion != 20 || preferences.AgentPolyglot != polyglot || (preferences.AgentPersonality ?? "") != stamp)
						{
							preferences.AgentId = agentId;
							preferences.AgentVersion = 20;
							preferences.AgentPolyglot = polyglot;
							preferences.AgentPersonality = stamp;
							SavePreferences();
						}
						Connect(url, voiceId, language);
					}
				}
			});
		});
	}

	private void Connect(string url, string voiceId, string language = "en")
	{
		Agent opened = new Agent();
		opened.Language = language;
		opened.Act = (string tool, ToolArguments args) => AgentAct(opened, tool, args);
		opened.Opened += (int rate) =>
		{
			Post(() =>
			{
				if (agent == opened)
				{
					ChatOpened(rate);
				}
			});
		};
		opened.Heard += (string text) =>
		{
			Post(() =>
			{
				if (agent == opened)
				{
					ChatHeard(text);
				}
			});
		};
		opened.Replied += (string text) =>
		{
			Post(() =>
			{
				if (agent == opened)
				{
					ChatReplied(text);
				}
			});
		};
		opened.Audio += (short[] samples) =>
		{
			Post(() =>
			{
				if (agent == opened && !dropping)
				{
					if (Unprompted())
					{
						dropping = true;
						checkedIn = true;
						Hush();
					}
					else
					{
						stirred = Environment.TickCount;
						speaker.Play(ChatVoice(samples));
						if (!frames.Enabled && !hidden)
						{
							frames.Start();
						}
					}
				}
			});
		};
		opened.Interrupted += () =>
		{
			Post(() =>
			{
				if (agent == opened)
				{
					Hush();
				}
			});
		};
		opened.Closed += (string problem) =>
		{
			Post(() =>
			{
				if (agent == opened)
				{
					if (problem != null)
					{
						ChatFailed(problem);
					}
					else
					{
						Rest();
					}
				}
			});
		};
		agent = opened;
		opened.Start(url, voiceId);
	}

	private short[] ChatVoice(short[] samples)
	{
		int pitch = VoiceFx.Pitch;
		int speed = VoiceFx.Speed;
		int robot = VoiceFx.Robot;
		int num = VoiceFx.Glitch;
		VoiceFx.Layering layers = VoiceFx.Layers;
		if (chatFx != null && (chatFx.Pitch != pitch || chatFx.Speed != speed || chatFx.Robot != robot || chatFx.Glitch != num || chatFx.Rate != chatRate || !chatFx.Layers.Same(layers)))
		{
			speaker.Play(chatFx.Flush());
			chatFx = null;
		}
		if (chatFx == null && !VoiceFx.Plain(pitch, speed, robot, num, layers))
		{
			chatFx = new VoiceFx.Live(chatRate, pitch, speed, robot, num, Environment.TickCount, timed: true, layers);
		}
		if (chatFx == null)
		{
			return samples;
		}
		chatTail.Stop();
		chatTail.Start();
		return chatFx.Push(samples);
	}

	private void ChatTail()
	{
		chatTail.Stop();
		if (chatFx != null && agent != null && !dropping)
		{
			speaker.Play(chatFx.Flush());
		}
	}

	private void Hush()
	{
		speaker.Clear();
		chatTail.Stop();
		chatFx = null;
	}

	private void ChatOpened(int rate)
	{
		chatRate = rate;
		chatTail.Stop();
		chatFx = null;
		try
		{
			speaker.Open(rate);
			if (!testing)
			{
				ears.Start();
			}
		}
		catch (VoiceException ex)
		{
			ChatFailed(ex.Message);
			return;
		}
		spoke = false;
		checkedIn = false;
		quietSince = -1.0;
		lock (waking)
		{
			wokeAt = ((backlog != null) ? clock.Elapsed.TotalSeconds : (-1.0));
			if (backlog != null)
			{
				foreach (short[] item in backlog)
				{
					agent.Send(item);
				}
			}
			backlog = null;
		}
		mainframe.VoiceNote(muteKey ? ("Voice chat on. " + MuteKeyName + " mutes your mic.") : "Voice chat on. Talk to her.", problem: false);
	}

	private void ChatFailed(string problem)
	{
		StopChat();
		mainframe.VoiceNote(problem, problem: true);
		bool flag = Broke(problem);
		if (flag && !FreeChatOn)
		{
			heard = "(voice)";
			box.Prompt = "> you: ";
			Begin(++asking, "Out of ElevenLabs credits, so voice chat is off. Type to me for now, choom.", TalkState.Talking, null);
		}
		else if (flag)
		{
			preferences.Quiet = true;
			SavePreferences();
			mainframe.Sync();
			StartLocal(credits: true);
		}
		else
		{
			heard = "(voice)";
			box.Prompt = "> you: ";
			Begin(++asking, "Can't open my voice link. Right-click me and open Capri Mainframe. The reason and the fix are under VOICE. If you're stuck, just join the Discord, choom. It's under Help in my right-click menu.", TalkState.Dormant, null);
		}
	}

	private string MouseKey(string tool, ToolArguments args)
	{
		if (args == null || brain.Model == null)
		{
			return null;
		}
		string text;
		if (tool == "use_computer")
		{
			text = args.Task;
		}
		else
		{
			text = ((preferences.QuickHands || !Security.On(5)) ? null : CursorJob(tool, args));
		}
		if (!string.IsNullOrWhiteSpace(text))
		{
			return Regex.Replace(text.Trim().ToLowerInvariant(), "\\s+", " ");
		}
		return null;
	}

	private bool Claim(string key)
	{
		lock (mouseJobs)
		{
			if (mouseJobs.Exists((string held) => SameJob(held, key)))
			{
				return false;
			}
			mouseJobs.Add(key);
			return true;
		}
	}

	internal static bool SameJob(string one, string other)
	{
		if (one == other)
		{
			return true;
		}
		HashSet<string> hashSet = new HashSet<string>();
		HashSet<string> hashSet2 = new HashSet<string>();
		foreach (Match item in Regex.Matches(one.ToLowerInvariant(), "[\\p{L}\\p{N}']+"))
		{
			if (!JobFiller.IsMatch(item.Value))
			{
				hashSet.Add(item.Value);
			}
		}
		foreach (Match item2 in Regex.Matches(other.ToLowerInvariant(), "[\\p{L}\\p{N}']+"))
		{
			if (!JobFiller.IsMatch(item2.Value))
			{
				hashSet2.Add(item2.Value);
			}
		}
		if (hashSet.Count == 0 || hashSet2.Count == 0)
		{
			return false;
		}
		int num = 0;
		foreach (string item3 in hashSet)
		{
			if (hashSet2.Contains(item3))
			{
				num++;
			}
		}
		return num * 10 >= (hashSet.Count + hashSet2.Count - num) * 6;
	}

	private void Free(string key)
	{
		lock (mouseJobs)
		{
			mouseJobs.Remove(key);
		}
	}

	private string Later(Agent told, string tool, ToolArguments args, string key)
	{
		if (!Claim(key))
		{
			return "Capri is already doing that job with her cursor. Don't call the tool again, and don't repeat what you already told them.";
		}
		int ticket = asking;
		ThreadPool.QueueUserWorkItem((object param0) =>
		{
			string result;
			try
			{
				result = DoTool(tool, args, ticket);
			}
			finally
			{
				Free(key);
			}
			Finished(told, tool, result, ticket);
		});
		return "Capri started that job with her cursor. It can take a minute, and you'll hear how it went when it's done. If you already told them she's on it, don't say it again; if you didn't, say so in a few words. Don't say it's done yet, and don't call the tool again for it.";
	}

	private void Finished(Agent told, string tool, string result, int ticket)
	{
		if (string.IsNullOrEmpty(result))
		{
			return;
		}
		if (result == "You pressed Esc, so I stopped.")
		{
			if (escTold == ticket)
			{
				return;
			}
			escTold = ticket;
		}
		lock (shortcutGate)
		{
			toolAsked = true;
			toolDone = result;
		}
		stirred = Environment.TickCount;
		Action<string> action = finishedTest;
		if (action != null)
		{
			action(result);
			return;
		}
		if (told != null && told.Ready)
		{
			told.Say("(Capri's hands finished the " + tool + " job: " + result + ") Tell them how it went in one short line. Don't call a tool for it again.");
			return;
		}
		Post(() =>
		{
			if (talkState != TalkState.Thinking)
			{
				Answer(++asking, result, TalkState.Talking);
			}
		});
	}

	private string AgentAct(Agent opened, string tool, ToolArguments args)
	{
		stirred = Environment.TickCount;
		lock (shortcutGate)
		{
			toolAsked = true;
			if (tool == shortcutTool && Environment.TickCount - shortcutAt < 10000)
			{
				return shortcutResult ?? "Already doing that.";
			}
		}
		string text = (Security.Asks(tool, args) ? null : MouseKey(tool, args));
		if (text != null)
		{
			return Later(opened, tool, args, text);
		}
		string text2 = DoTool(tool, args);
		if (string.IsNullOrEmpty(text2))
		{
			text2 = "You pressed Esc, so I stopped.";
		}
		lock (shortcutGate)
		{
			toolDone = text2;
		}
		stirred = Environment.TickCount;
		return text2;
	}

	private bool VoiceAnswer(string text, int ticket, Agent asker)
	{
		string resumed = Security.Holding;
		bool flag = resumed != null && (Security.Agrees(text) || Security.Declines(text));
		if (resumed != null && !flag)
		{
			Security.Drop();
		}
		if (!flag)
		{
			return false;
		}
		lock (shortcutGate)
		{
			toolAsked = true;
			heardLast = text;
			toolDone = null;
			shortcutTool = resumed;
			shortcutAt = Environment.TickCount;
			shortcutResult = null;
		}
		ThreadPool.QueueUserWorkItem((object param0) =>
		{
			int tickCount = Environment.TickCount;
			string text2 = Security.Resume(text, (string held, ToolArguments heldArgs) => DoTool(held, heldArgs, ticket)) ?? "Okay, I left it alone.";
			lock (shortcutGate)
			{
				shortcutResult = text2;
			}
			stirred = Environment.TickCount;
			if (text2 != "Okay, I left it alone." && Environment.TickCount - tickCount > 8000)
			{
				Finished(asker, resumed, text2, ticket);
			}
			else
			{
				string obj = ((text2 == "Okay, I left it alone.") ? "They said no, so Capri left it alone. Say so in one short line and don't call a tool for it." : ("Capri's hands did what they just said yes to (" + resumed + "): " + text2 + " Don't call a tool for it again. React to it in one short line."));
				Action<string> action = finishedTest;
				if (action != null)
				{
					action(obj);
				}
				else if (asker != null)
				{
					asker.Tell(obj);
				}
			}
		});
		return true;
	}

	private bool Unprompted()
	{
		return Environment.TickCount - stirred >= 12000;
	}

	private static readonly string[] RideLines = new string[5] { "Segura firme, choom!", "Sobe, Capri! Ninguém me tira daqui.", "Seu cursor agora é meu.", "Vamos dar uma volta.", "Hehe, carona grátis." };

	// what speech recognition makes of her name (capre, cápria, cabre, kapri...) turned back into "Capri"
	private static readonly Regex NameSlip = new Regex(@"\b(?:[ck]+[aáàâã]+[pb]+[rl]+[eéêiíy]+[aeo]?|[ck]+[aáàâã]+[pb]+[eéêiíy]+[rl]+[ey]?|[ck]+[aáàâã]+[pb]+r[iíy]+[aáeé])\b", RegexOptions.IgnoreCase | RegexOptions.CultureInvariant);

	private static string FixName(string said)
	{
		if (string.IsNullOrEmpty(said))
		{
			return said;
		}
		return NameSlip.Replace(said, (Match m) => Regex.IsMatch(m.Value, "^(?i:caprese|capiro|cabere)$") ? m.Value : "Capri");
	}

	// her keyboard shortcuts, said out loud: lie down, go quiet, hide, show up, ride the mouse
	private bool VoiceShortcut(string said)
	{
		if (!preferences.VoiceOrders)
		{
			return false;
		}
		if (ReminderByVoice(said))
		{
			return true;
		}
		string text = new string((said ?? "").Normalize(NormalizationForm.FormD).Where((char c) => CharUnicodeInfo.GetUnicodeCategory(c) != UnicodeCategory.NonSpacingMark).ToArray()).ToLowerInvariant();
		if (text.Length > 80 || Regex.IsMatch(text, "\\b(nao|never|don'?t|dont)\\b"))
		{
			return false;
		}
		Action action = null;
		if (Regex.IsMatch(text, "\\b(d[ei]s?[cs]?[ae]r?|d[ei]ce|d[ei]ss?[ae]|sai[ar]?|sai[ar]? de cima|hop off|get off|get down|para de andar)\\b"))
		{
			action = () =>
			{
				if (riding)
				{
					StopRide();
					Zap(0.8, ground: false, Cue.Zap);
					SayOne("she hopped off their mouse cursor", "Tá bom, tô descendo.", "Fim da carona, choom.", "Ok, ok, desci.", "Valeu pela carona!");
				}
				else
				{
					Zap(0.25, ground: seat != null, Cue.Spark);
					SayOne("they told her to get off the mouse, but she was not riding it", "Eu nem tô no seu mouse, choom.", "Já tô no chão.");
				}
			};
		}
		else if (Regex.IsMatch(text, "\\b(s[ou]b[eai]r?|s[ou]bi|monta[r]?|mont[ae]|pula[r]?|pul[ae]|ride|rider|hop on)\\b.*\\b(m[ao]u?s[ei]?|mause|maus|mouses?|curs[oa]r?|cursos?|ponteiro|setinha|seta)\\b"))
		{
			action = RideByVoice;
		}
		else if (Regex.IsMatch(text, "\\b(d[ei]i?t[aeio]r?|deitada|deitadinha|lie down|lay down|lie|deitase)\\b"))
		{
			action = () =>
			{
				if (lying)
				{
					Zap(0.25, ground: true, Cue.Spark);
					SayOne("they told her to lie down, but she is already lying down", "Já tô deitada, choom.", "Mais deitada que isso só dormindo.");
				}
				else if (seat == null || clip != perch || !LieDown())
				{
					Zap(0.3, ground: seat != null, Cue.Spark);
					SayOne("they told her to lie down, but she can only lie down on top of a window and she is not on one", "Me põe em cima de uma janela que eu deito.", "Aqui não dá, choom. Me coloca numa janela.");
				}
				else
				{
					Zap(0.5, ground: true, Cue.Spark);
					SayOne("she lay down to rest, as they asked", "Aah, que bom deitar um pouco.", "Hora do descanso.", "Vou ficar aqui de boa.", "Deitadinha, como você pediu.");
				}
			};
		}
		else if (Regex.IsMatch(text, "\\b(fi[ck][ae]r? (qu|k)i?e?t[ao]|(qu|k)i?etinh[ao]|fi[ck][ae]r? em silencio|silencio|silencia|cala (a )?boca|calad[ao]|be quiet|shush|shh+|psiu)\\b"))
		{
			action = () =>
			{
				if (!shushed)
				{
					ToggleShush();
					Zap(0.4, ground: seat != null, Cue.Spark);
					SayOne("she went quiet as they asked (she will stop chiming in on her own)", "Tá, fico quietinha.", "Shh... modo silencioso.", "Ok, não falo mais. Por enquanto.");
				}
				else
				{
					Zap(0.2, ground: seat != null, Cue.Spark);
					SayOne("they told her to be quiet, but she already is", "Já tô quietinha.", "Mais quieta que isso eu sumo.");
				}
			};
		}
		else if (Regex.IsMatch(text, "\\b(e?s?cond[aeiou]r?|e?s?cond[ea]-?se|sumir?|sum[ae] daqui|some daqui|hide|raide)\\b"))
		{
			action = () =>
			{
				if (!hidden)
				{
					SayOne("she is vanishing from the screen to hide, as they asked; say a quick goodbye", "Fui!", "Me acha se puder.", "Sumindo...", "Até já, choom.");
					Zap(1.0, ground: seat != null, Cue.Zap);
					hideKeepsEars = chatting;
					BeginInvoke((Action)(() => SetHidden(value: true)));
				}
			};
		}
		else if (Regex.IsMatch(text, "\\b(apar[ae](c|ss|s)[aeiou]r?|aparecida|volt[ae]r?|show yourself|come back|cade voce|reaparec[ae])\\b"))
		{
			action = () =>
			{
				if (hidden)
				{
					SetHidden(value: false);
					Zap(1.0, ground: seat != null, Cue.Arrive);
					SayOne("she just reappeared on the screen after hiding, because they called her back", "Voltei!", "Sentiu minha falta?", "Tô aqui, choom.", "Chamou?");
				}
				else
				{
					Zap(0.3, ground: seat != null, Cue.Spark);
					SayOne("they called her to show up, but she was not hidden", "Já tô aqui, choom.", "Eu nunca saí.");
				}
			};
		}
		if (action == null || !IsHandleCreated)
		{
			return false;
		}
		BeginInvoke(action);
		return true;
	}

	// in a voice chat her AI already answers what they said, so it only learns what she did, right away
	// otherwise a line her brain wrote earlier shows at once, and the next one is written in the background
	private readonly Dictionary<string, Queue<string>> orderLines = new Dictionary<string, Queue<string>>();

	private void SayOne(string what, params string[] lines)
	{
		Agent told = agent;
		if (chatting && told != null)
		{
			told.Tell("Capri just obeyed the spoken order the user just gave: " + what + ". It is already done, so don't call a tool for it. Answer them with one short, fresh line of your own about it, in character and in their language.");
			return;
		}
		string said = null;
		lock (orderLines)
		{
			if (orderLines.TryGetValue(what, out var queue) && queue.Count > 0)
			{
				said = queue.Dequeue();
			}
		}
		Remark("order", said ?? lines[random.Next(lines.Length)]);
		Brain mind = brain;
		if (mind == null || mind.Model == null)
		{
			return;
		}
		string ask = "(System note: Capri just obeyed a spoken order from the user: " + what + ". Write one short, fresh line she says about it, in character and in Brazilian Portuguese. Only the line.)";
		ThreadPool.QueueUserWorkItem((object param0) =>
		{
			string line = null;
			try
			{
				line = Brain.Clean(mind.Ask(ask));
			}
			catch (Exception)
			{
			}
			if (string.IsNullOrWhiteSpace(line) || line.Length > 160)
			{
				return;
			}
			lock (orderLines)
			{
				if (!orderLines.TryGetValue(what, out var queue))
				{
					queue = (orderLines[what] = new Queue<string>());
				}
				if (queue.Count < 3)
				{
					queue.Enqueue(line);
				}
			}
		});
	}

