	private void SayTime(DateTime now)
	{
		string hour = (now.Hour == 0) ? "meia-noite" : ((now.Hour == 12) ? "meio-dia" : ((now.Hour == 1 || now.Hour == 13) ? "uma hora" : (now.Hour + " horas")));
		string said = (now.Minute == 0) ? ("São " + hour + " em ponto.") : ((now.Minute == 30) ? ("São " + hour + " e meia.") : ("São " + now.ToString("HH:mm") + "."));
		if (now.Hour == 0 || now.Hour == 12 || now.Hour == 1 || now.Hour == 13)
		{
			said = said.Replace("São ", "É ");
		}
		Zap(0.3, ground: seat != null, Cue.Spark);
		Remark("time", said);
	}

	private static int SpokenNumber(string word)
	{
		if (int.TryParse(word, out var n))
		{
			return n;
		}
		switch (word.Replace("ê", "e"))
		{
		case "um":
		case "uma":
			return 1;
		case "dois":
		case "duas":
			return 2;
		case "tres":
			return 3;
		case "quatro":
			return 4;
		case "cinco":
			return 5;
		case "dez":
			return 10;
		case "quinze":
			return 15;
		case "vinte":
			return 20;
		case "trinta":
		case "meia":
			return 30;
		case "quarenta":
			return 40;
		default:
			return 0;
		}
	}

	// "me lembra de beber água em 30 minutos" or "daqui a 10 minutos me lembra de tirar o bolo"
	private bool ReminderByVoice(string said)
	{
		string text = (said ?? "").ToLowerInvariant().Trim().TrimEnd('.', '!', '?');
		if (text.Length > 200 || !Regex.IsMatch(text, "\\blembr"))
		{
			return false;
		}
		Match m = Regex.Match(text, "lembr\\w*(?:-me)?\\s+(?:de\\s+|que\\s+|pra\\s+|para\\s+)?(.+?)\\s+(?:em|daqui a|daqui)\\s+" + ReminderAmount + "\\s*" + ReminderUnit + "\\b");
		string task = null;
		string amount = null;
		string unit = null;
		if (m.Success)
		{
			task = m.Groups[1].Value;
			amount = m.Groups[2].Value;
			unit = m.Groups[3].Value;
		}
		else
		{
			m = Regex.Match(text, "(?:em|daqui a|daqui)\\s+" + ReminderAmount + "\\s*" + ReminderUnit + "\\b,?\\s+(?:me\\s+)?lembr\\w*(?:-me)?\\s+(?:de\\s+|que\\s+|pra\\s+|para\\s+)?(.+)");
			if (!m.Success)
			{
				return false;
			}
			amount = m.Groups[1].Value;
			unit = m.Groups[2].Value;
			task = m.Groups[3].Value;
		}
		int n = SpokenNumber(amount);
		if (amount == "meia")
		{
			n = 30;
			unit = "min";
		}
		if (n <= 0 || string.IsNullOrWhiteSpace(task))
		{
			return false;
		}
		TimeSpan wait = unit.StartsWith("s") ? TimeSpan.FromSeconds(n) : (unit.StartsWith("h") ? TimeSpan.FromHours(n) : TimeSpan.FromMinutes(n));
		task = Regex.Replace(task, "^(capri,?\\s+)", "").Trim();
		lock (reminders)
		{
			reminders.Add(new KeyValuePair<DateTime, string>(DateTime.Now + wait, task));
		}
		string when = unit.StartsWith("s") ? (n + " segundos") : (unit.StartsWith("h") ? (n + ((n == 1) ? " hora" : " horas")) : (n + ((n == 1) ? " minuto" : " minutos")));
		if (!IsHandleCreated)
		{
			return true;
		}
		BeginInvoke((Action)(() =>
		{
			Zap(0.4, ground: seat != null, Cue.Spark);
			SayOne("she set a reminder to tell them to '" + task + "' in " + when, "Fechado, te lembro em " + when + ".", "Anotado. Daqui " + when + " eu te chamo.");
		}));
		return true;
	}

	// runs on the signal timer, at most once a second
	private void CheckHelpers()
	{
		DateTime now = DateTime.Now;
		if (testing || quitting || now < nextHelperTick)
		{
			return;
		}
		nextHelperTick = now.AddSeconds(1.0);
		string due = null;
		lock (reminders)
		{
			int i = reminders.FindIndex((KeyValuePair<DateTime, string> r) => r.Key <= now);
			if (i >= 0)
			{
				due = reminders[i].Value;
				reminders.RemoveAt(i);
			}
		}
		if (due != null)
		{
			Zap(1.0, ground: seat != null, Cue.Arrive);
			Remark("reminder", "Ei, choom! Tá na hora: " + due + ".");
			return;
		}
		if (Pomodoro > 0 && now >= pomoEnd)
		{
			pomoBreak = !pomoBreak;
			pomoEnd = now.AddMinutes(Pomodoros[Pomodoro, pomoBreak ? 1 : 0]);
			Zap(pomoBreak ? 1.0 : 0.5, ground: seat != null, pomoBreak ? Cue.Zap : Cue.Spark);
			Remark("pomodoro", pomoBreak ? ("Pausa! " + Pomodoros[Pomodoro, 1] + " minutos pra respirar.") : ("Fim da pausa. Mais " + Pomodoros[Pomodoro, 0] + " minutos de foco."));
			return;
		}
		int half = now.Hour * 2 + now.Minute / 30;
		if (chimeSaid < 0)
		{
			chimeSaid = half;
		}
		if (Chime > 0 && half != chimeSaid && (now.Minute == 0 || (Chime == 2 && now.Minute == 30)))
		{
			chimeSaid = half;
			if (!hidden && !Hushed)
			{
				SayTime(now);
				return;
			}
		}
		if (now.Second % 5 == 0 && preferences.PcAlerts)
		{
			CheckPc(now);
		}
	}

	[System.Runtime.InteropServices.DllImport("kernel32.dll")]
	private static extern bool GetSystemTimes(out long idle, out long kernel, out long user);

	private void CheckPc(DateTime now)
	{
		if (GetSystemTimes(out var idle, out var kernel, out var user))
		{
			long[] last = cpuLast;
			cpuLast = new long[3] { idle, kernel, user };
			if (last != null)
			{
				long total = kernel - last[1] + (user - last[2]);
				double busy = (total > 0) ? (1.0 - (double)(idle - last[0]) / (double)total) : 0.0;
				cpuHot = (busy > 0.9) ? (cpuHot + 1) : 0;
				if (cpuHot >= 6 && now - cpuToldAt > TimeSpan.FromMinutes(15.0) && !hidden && !Hushed)
				{
					cpuHot = 0;
					cpuToldAt = now;
					Zap(0.6, ground: seat != null, Cue.Spark);
					Remark("pc", new string[3] { "Seu PC tá fervendo, choom. CPU no talo faz um tempão.", "Tá sentindo esse calor? A CPU tá quase derretendo.", "Ei, alguma coisa tá comendo toda a sua CPU." }[random.Next(3)]);
					return;
				}
			}
		}
		PowerStatus power = SystemInformation.PowerStatus;
		if (power.BatteryChargeStatus.HasFlag(BatteryChargeStatus.NoSystemBattery) || power.PowerLineStatus == PowerLineStatus.Online)
		{
			batteryTold = false;
		}
		else if (!batteryTold && power.BatteryLifePercent <= 0.2f)
		{
			batteryTold = true;
			Zap(0.6, ground: seat != null, Cue.Spark);
			Remark("battery", "Bateria em " + (int)Math.Round(power.BatteryLifePercent * 100f) + "%. Liga o carregador, choom.");
		}
	}

	// hops onto the cursor with a burst of lightning, a crackle and a line
	private void RideByVoice()
	{
		if (riding)
		{
			Zap(0.3, ground: false, Cue.Spark);
			SayOne("they told her to ride the mouse, but she is already riding it", "Já tô no seu cursor, choom.", "Eu já tô aqui em cima.");
			return;
		}
		if (hidden)
		{
			SetHidden(value: false);
		}
		Zap(0.8, ground: seat != null, Cue.Zap);
		StartRide(quiet: true);
		Zap(1.0, ground: false, Cue.Arrive);
		if (chatting && agent != null)
		{
			SayOne("she jumped onto their mouse cursor and is riding it now", RideLines);
			return;
		}
		Say(RideLines[random.Next(RideLines.Length)] + (hotkey ? (" (" + hopName + " pra eu descer)") : ""));
	}

	private void ChatHeard(string text)
	{
		if (!chatting)
		{
			return;
		}
		text = FixName(text);
		Brain.Transcribe("You (voice)", text);
		spoke = true;
		stirred = Environment.TickCount;
		checkedIn = false;
		wokeAt = -1.0;
		int ticket = ++asking;
		heard = text;
		box.Prompt = "> you: ";
		Brain.Learn(text);
		dropping = false;
		if (VoiceShortcut(text) || hidden)
		{
			return;
		}
		string tool = null;
		ToolArguments args = null;
		bool flag = VoiceAnswer(text, ticket, agent);
		bool flag2 = !flag && Hands.Heard(text, out tool, out args);
		lock (shortcutGate)
		{
			if (!flag)
			{
				toolAsked = flag2;
				heardLast = text;
				toolDone = null;
			}
		}
		if (flag2)
		{
			Agent told = agent;
			string key = MouseKey(tool, args);
			bool claimed = key != null && Claim(key);
			lock (shortcutGate)
			{
				shortcutTool = tool;
				shortcutAt = Environment.TickCount;
				shortcutResult = null;
			}
			ThreadPool.QueueUserWorkItem((object param0) =>
			{
				int tickCount = Environment.TickCount;
				string text2;
				try
				{
					text2 = ((key != null && !claimed) ? "Already doing that." : DoTool(tool, args, ticket));
				}
				finally
				{
					if (claimed)
					{
						Free(key);
					}
				}
				if (string.IsNullOrEmpty(text2))
				{
					text2 = "You pressed Esc, so I stopped.";
				}
				lock (shortcutGate)
				{
					shortcutResult = text2;
				}
				stirred = Environment.TickCount;
				if (Security.IsHold(text2))
				{
					if (told != null)
					{
						told.Tell(text2);
					}
				}
				else if (Environment.TickCount - tickCount > 8000)
				{
					Finished(told, tool, text2, ticket);
				}
				else if (told != null)
				{
					told.Tell("Capri's hands already did what they just asked (" + tool + "): " + text2 + " Don't call a tool for it again. React to it in one short line.");
				}
			});
		}
		reply = null;
		replyDone = -1.0;
		Say(null);
		talkState = TalkState.Thinking;
		box.Leaving = -1.0;
		UpdateAnimation();
	}

	private void ChatReplied(string text)
	{
		if (!chatting)
		{
			return;
		}
		checkedIn = !spoke;
		spoke = false;
		if (dropping)
		{
			return;
		}
		if (checkedIn && Unprompted())
		{
			dropping = true;
			Hush();
			return;
		}
		string text2 = Computer.Mask(Voice.Spoken(text));
		string promised = null;
		lock (shortcutGate)
		{
			if (!toolAsked && heardLast != null && Hands.Promised(text2))
			{
				promised = heardLast;
				heardLast = null;
			}
		}
		if (promised != null)
		{
			string missed = text2;
			ThreadPool.QueueUserWorkItem((object param0) =>
			{
				Thread.Sleep(4000);
				lock (shortcutGate)
				{
					if (toolAsked)
					{
						return;
					}
				}
				Brain.Log("https://api.elevenlabs.io/v1/convai/conversation", -1L, "Voice chat said she'd do it but no tool ran. Heard: " + promised + " | Said: " + missed);
			});
		}
		Brain.Transcribe("Capri (voice)", text2);
		reply = text2;
		replyStart = clock.Elapsed.TotalSeconds;
		replyDone = -1.0;
		talkState = TalkState.Talking;
		box.Leaving = -1.0;
		pace = 15.0;
		Say(null);
	}

	private void StopChat()
	{
		if (!chatting)
		{
			return;
		}
		bool flag = local;
		chatting = false;
		local = false;
		earsReady = false;
		earsAwaited = false;
		earsRetryAt = -1.0;
		micQuietFrom = -1.0;
		if (muteKey && !ByMouse(preferences.MuteVk))
		{
			Native.UnregisterHotKey(Handle, 17229);
		}
		muteKey = false;
		chatTicket++;
		Agent agent = this.agent;
		this.agent = null;
		agent?.Stop();
		Dictation dictation = this.dictation;
		this.dictation = null;
		dictation?.Dispose();
		ears.Stop();
		ears.Muted = false;
		Hearing.Own = null;
		if (!testing)
		{
			ThreadPool.QueueUserWorkItem((object param0) =>
			{
				parakeet.Dispose();
			});
		}
		Hush();
		dropping = false;
		checkedIn = false;
		quietSince = -1.0;
		wokeAt = -1.0;
		lock (waking)
		{
			resting = false;
			backlog = null;
			preroll.Clear();
			loudRun = 0;
			utterance = null;
			quietRun = 0;
			noiseHold = false;
		}
		earsShut = false;
		transcribing = false;
		pill.SetChat(on: false, micMuted: false);
		pillUntil = clock.Elapsed.TotalSeconds + 3.0;
		ShowVoice();
		if (flag)
		{
			if (asking == earsNotice)
			{
				CloseTalk();
			}
			mainframe.VoiceNote("Free voice chat off. Click the wave to listen again.", problem: false);
		}
	}

	private void CheckChat(double now)
	{
		if (agent != null && ears.Muted && !speaker.Busy)
		{
			Rest();
			mainframe.VoiceNote("Mic muted. Voice chat is paused until you unmute.", problem: false);
		}
		else if (agent == null || (!checkedIn && (!(wokeAt >= 0.0) || !(now - wokeAt >= 8.0))) || speaker.Busy)
		{
			quietSince = -1.0;
		}
		else if (quietSince < 0.0)
		{
			quietSince = now;
		}
		else if (now - quietSince >= 1.2)
		{
			Rest();
		}
	}

	private void Rest()
	{
		if (chatting)
		{
			Agent agent = this.agent;
			this.agent = null;
			chatTicket++;
			agent?.Stop();
			dropping = false;
			checkedIn = false;
			quietSince = -1.0;
			wokeAt = -1.0;
			lock (waking)
			{
				resting = true;
				backlog = null;
				preroll.Clear();
				loudRun = 0;
			}
			mainframe.VoiceNote("Voice chat resting. Talk and she'll pick up.", problem: false);
		}
	}

	private void Wake()
	{
		if (!chatting || agent != null)
		{
			lock (waking)
			{
				backlog = null;
				return;
			}
		}
		OpenLink();
	}

	private void ToggleMic()
	{
		if (chatting)
		{
			ears.Muted = !ears.Muted;
			if (dictation != null && earsReady)
			{
				dictation.Hold(ears.Muted);
			}
			pill.SetChat(on: true, ears.Muted);
			pillUntil = clock.Elapsed.TotalSeconds + 3.0;
			CheckEars(clock.Elapsed.TotalSeconds);
			if (local && earsReady)
			{
				Mainframe mainframe = this.mainframe;
				string text;
				if (ears.Muted)
				{
					text = "Mic muted. Click the mic to unmute.";
				}
				else
				{
					text = (transcribing ? "Hearing you..." : "Free voice chat on. Talk and I'll type back.");
				}
				mainframe.VoiceNote(text, problem: false);
			}
			else if (!local)
			{
				this.mainframe.VoiceNote(ears.Muted ? "Mic muted. Voice chat pauses once she stops talking." : "Mic on. Talk and she'll pick up.", problem: false);
			}
		}
	}

	private void Listen(short[] chunk)
	{
		if (local)
		{
			Gather(chunk);
			return;
		}
		lock (waking)
		{
			if (resting)
			{
				preroll.Add(chunk);
				if (preroll.Count > 5)
				{
					preroll.RemoveAt(0);
				}
				loudRun = ((!speaker.Busy && Speaker.Loudness(chunk, 0, chunk.Length) >= 0.02) ? (loudRun + 1) : 0);
				if (loudRun >= 2)
				{
					resting = false;
					loudRun = 0;
					backlog = new List<short[]>(preroll);
					preroll.Clear();
					Post(Wake);
				}
				return;
			}
			if (backlog != null)
			{
				backlog.Add(chunk);
				if (backlog.Count > 80)
				{
					backlog.RemoveAt(0);
				}
				return;
			}
		}
		agent?.Send(speaker.Busy ? new short[chunk.Length] : chunk);
	}

	internal void Hear(string text)
	{
		Hear(text, text, "> you: ");
	}

	private void Hear(string text, string shown, string prompt, int switches = 0)
	{
		text = FixName((text ?? "").Trim());
		shown = FixName(shown);
		if (text.Length == 0)
		{
			return;
		}
		if (prompt == "> you: " && VoiceShortcut(text))
		{
			return;
		}
		if (text.Length > 240)
		{
			text = text.Substring(0, 240);
		}
		Job job = this.job;
		if (job != null && working != null && !job.Asking && prompt == "> you: ")
		{
			Brain.Transcribe(local ? "You (voice)" : "You", text);
			job.Tell(text);
			working = "Got it. Esc stops me.";
			UpdateTalk(clock.Elapsed.TotalSeconds);
			SayAside("Got it.", job);
			return;
		}
		if (local)
		{
			talkState = TalkState.Thinking;
			CheckEars(clock.Elapsed.TotalSeconds);
		}
		if (hidden)
		{
			SetHidden(value: false);
		}
		hideAsked = false;
		brain.Cancel();
		voice.Stop();
		int ticket = ++asking;
		heard = shown;
		box.Prompt = prompt;
		if (meeting.Asking && prompt == "> you: ")
		{
			string text2 = meeting.Take(text, out var called);
			if (text2 != null)
			{
				if (called != null)
				{
					CallThem(called);
				}
				MeetLine(ticket, text2);
				return;
			}
		}
		text = Hands.Manners(text, out var askPlease);
		if (askPlease)
		{
			Answer(ticket, "Say please.", TalkState.Talking);
			return;
		}
		Func<string, string> think = Think;
		if (think == null && brain.Model == null && Security.Holding != null)
		{
			if (Security.Agrees(text) || Security.Declines(text))
			{
				think = (string param0) => Security.Resume(text, DoTool) ?? "Okay, I left it alone.";
			}
			else
			{
				Security.Drop();
			}
		}
		if (think == null && brain.Model == null && Hands.Heard(text, out var quick, out var quickArgs) && (quick == "media" || quick == "nap" || quick == "move_yourself" || quick == "animate"))
		{
			think = (string param0) => Security.Said(DoTool(quick, quickArgs));
		}
		if (think == null)
		{
			if (brain.Model == null)
			{
				Answer(ticket, "My brain's offline. Right-click me, open Capri Mainframe and press Set up her brain, or press Free key there for a free NVIDIA key. If you're stuck, just join the Discord, choom. It's under Help in my right-click menu.", TalkState.Dormant);
				FindBrain();
				mainframe.Restore();
				return;
			}
			think = brain.Ask;
		}
		reply = null;
		replyDone = -1.0;
		Say(null);
		talkState = TalkState.Thinking;
		thinkingSince = clock.Elapsed.TotalSeconds;
		slowWarned = false;
		box.Leaving = -1.0;
		UpdateAnimation();
		bool quiet = local;
		Cloud remote = brain.Remote;
		if (!testing && (voice.Key == null || quiet || voiceBroke) && kokoro.Installed && !preferences.Quiet && !preferences.Silent)
		{
			ThreadPool.QueueUserWorkItem((object param0) =>
			{
				try
				{
					kokoro.Warm();
				}
				catch (Exception)
				{
				}
			});
		}
		if (!testing && preferences.HdVoice && (voice.Key == null || quiet || voiceBroke || preferences.Quiet) && !preferences.Silent && qwen.Installed && !qwen.Awake && clock.Elapsed.TotalSeconds >= hdRest && !HdStepsAside())
		{
			WakeHd();
		}
		ThreadPool.QueueUserWorkItem((object param0) =>
		{
			if (ticket != asking)
			{
				return;
			}
			TalkState state = TalkState.Talking;
			string problem = null;
			bool stuck = false;
			string said;
			try
			{
				said = Computer.Mask(think(text));
			}
			catch (BrainException ex)
			{
				said = ((ex.Message == "My brain's offline. Right-click me, open Capri Mainframe and press Set up her brain, or press Free key there for a free NVIDIA key. If you're stuck, just join the Discord, choom. It's under Help in my right-click menu.") ? "My brain's offline. Right-click me, open Capri Mainframe and press Set up her brain, or press Free key there for a free NVIDIA key. If you're stuck, just join the Discord, choom. It's under Help in my right-click menu." : (ex.Told ? ex.Message : "My brain couldn't answer. The error is under BRAIN in Capri Mainframe."));
				problem = ex.Message;
				state = TalkState.Dormant;
				stuck = Brain.Stalled(ex);
			}
			catch (Exception error)
			{
				said = Brain.Explain(error, remote) ?? "That reply was cancelled. Try again.";
				problem = said;
				state = TalkState.Dormant;
				stuck = Brain.Stalled(error);
			}
			if (string.IsNullOrWhiteSpace(said))
			{
				said = "My brain sent an empty reply. Try again.";
				problem = said;
				state = TalkState.Dormant;
			}
			try
			{
				if (!IsDisposed)
				{
					BeginInvoke((Action)(() =>
					{
						if (stuck && ticket == asking && Hops(remote, switches))
						{
							Hear(text, shown, prompt, switches + 1);
						}
						else
						{
							if (problem != null && ticket == asking)
							{
								mainframe.ShowProblem(Brain.Brief(problem) ?? ((problem.Length > 60) ? (problem.Substring(0, 57) + "...") : problem));
							}
							Answer(ticket, said, state, quiet);
