	private byte[] Voiced(Func<string, byte[]> speak, Func<string, byte[]> free, string words, out string problem)
	{
		problem = null;
		try
		{
			return (speak == free) ? speak(words) : VoiceFx.Styled(speak(words), words);
		}
		catch (VoiceException ex)
		{
			problem = ex.Message;
			if (speak == free || !Broke(ex.Message))
			{
				return null;
			}
			voiceBroke = true;
			if (free == null && FreeChatOn && !testing)
			{
				Post(() =>
				{
					GetFreeVoice();
				});
				problem = "Out of ElevenLabs credits, so she's getting her free voice.";
				return null;
			}
			if (free == null)
			{
				problem = "Out of ElevenLabs credits. Pick PREBUILT LOCAL in Capri Mainframe and get her free voice.";
				return null;
			}
			try
			{
				byte[] result = free(words);
				problem = "Out of ElevenLabs credits, so she's using her free voice.";
				return result;
			}
			catch (Exception ex2)
			{
				problem = Voice.Short("Free voice glitched: " + ex2.Message);
				return null;
			}
		}
		catch (Exception ex3)
		{
			problem = Voice.Short("Voice glitched: " + ex3.Message);
			return null;
		}
	}

	private static bool Broke(string problem)
