		int num = (int)((now - speechStart) * 12.0);
		if (mouths != null)
		{
			if (num >= mouths.Length)
			{
				speech = null;
				mouths = null;
				return -1;
			}
			if (clip != idle || shown == blinkGlitch)
			{
				return -1;
			}
			return mouths[num];
		}
		int num2 = (int)((double)num / 12.0 * 28.0);
		if (num2 >= speech.Length)
		{
