	internal static int MouthFor(char letter, int step)
	{
		char value = char.ToLowerInvariant(letter);
		if ("aeo".IndexOf(value) >= 0)
		{
			if (!char.IsUpper(letter))
			{
				return 3;
			}
			return 4;
		}
		if ("iuy".IndexOf(value) >= 0)
		{
			return 2;
		}
		if ("mbp".IndexOf(value) >= 0 || !char.IsLetter(letter))
		{
			return 0;
		}
		if (step % 2 != 1)
		{
			return 2;
		}
		return 1;
	}

