	internal static void Nod(Graphics graphics, Bitmap strip, int cell, int width, float wide, float tall, float nod, bool sitting, float shiftX = 0f, float shiftY = 0f)
	{
		int num = strip.Height;
		float scale = tall / (float)num;
		float left = cell * width;
		float drop = nod * 10f;
		float lean = nod * 0.22f;
		float num2 = shiftY / scale;
		float head = (float)(sitting ? 196 : 138) - num2;
		float chest = (float)(sitting ? 232 : 176) - num2;
		float neck = (float)(sitting ? 214 : 152) - num2;
		Func<float, float, PointF> at = (float x, float y) =>
		{
			float num4 = ((y <= head) ? 1f : ((y >= chest) ? 0f : ((chest - y) / (chest - head))));
			num4 = num4 * num4 * (3f - 2f * num4);
			return new PointF((x + (neck - y) * lean * num4) * scale - wide / 2f + shiftX, (y + drop * num4) * scale - tall / 2f + shiftY);
		};
		Action<float, float> action = (float top, float bottom) =>
		{
			graphics.DrawImage(strip, new PointF[3]
			{
				at(0f, top),
				at(width, top),
				at(0f, bottom)
			}, new RectangleF(left, top, width, bottom - top), GraphicsUnit.Pixel, NodEdges);
		};
		action(chest, num);
		for (float num3 = chest; num3 > head; num3 -= 3f)
		{
			action(Math.Max(head, num3 - 3f), num3 + 1f);
		}
		action(0f, head + 1f);
	}

