	private Preferences LoadPreferences()
	{
		try
		{
			using FileStream stream = File.OpenRead(settingsPath);
			Preferences preferences = (Preferences)new DataContractJsonSerializer(typeof(Preferences)).ReadObject(stream);
			if (preferences.Size < 140 || preferences.Size > 560)
			{
				preferences.Size = 240;
			}
			preferences.PerchFps = PerchRate(preferences.PerchFps);
			CheckKeys(preferences);
			preferences.TuneOnce();
			return preferences;
		}
		catch
		{
			return Preferences.Fresh();
		}
	}

	private void SavePreferences()
	{
		Point point;
		if (onPanel)
		{
