		{
			point = (lying ? new Point(anchor.X + (int)((float)preferences.Size * SitX) - (int)((float)preferences.Size * (facingLeft ? 0.7f : 0.3f)), anchor.Y) : anchor);
		}
		preferences.X = point.X;
		preferences.Y = point.Y;
		preferences.HasPosition = true;
		try
		{
			Directory.CreateDirectory(Path.GetDirectoryName(settingsPath));
			string text = settingsPath + ".new";
			using (FileStream stream = File.Create(text))
			{
				new DataContractJsonSerializer(typeof(Preferences)).WriteObject(stream, preferences);
			}
			if (File.Exists(settingsPath))
			{
				File.Replace(text, settingsPath, null);
			}
			else
			{
				File.Move(text, settingsPath);
			}
		}
		catch (IOException)
		{
		}
		catch (UnauthorizedAccessException)
		{
		}
	}

