	private static bool LoggedSince(string line, DateTime from)
	{
		if (line.Length >= 19 && DateTime.TryParseExact(line.Substring(0, 19), "yyyy-MM-dd HH:mm:ss", CultureInfo.InvariantCulture, DateTimeStyles.None, out var result))
		{
			return result >= from.AddTicks(-(from.Ticks % 10000000));
		}
		return false;
	}

